window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0069", [{"word":"inorganic","ipa_uk":"/ˌɪnɔːˈɡænɪk/","ipa_us":"/ˌɪnɔːrˈɡænɪk/","definition_zh":"无机的；不含碳化合物的；非生物来源的","definition_en":"not containing carbon compounds in the chemical sense, and more broadly not arising from or belonging to living things","core_image":"一块灰白石英晶体旁没有一片叶子，只有层层岩壁与矿物粉末","scene":"The geologist ruled out any biological origin and logged the crust as an inorganic deposit.","sceneCN":"这里 inorganic 指「非生物来源的」（第 2 个义项：不由生命过程形成）；地质学家排除生物成因，把这一结壳记作无机沉积。图中可辨识物件：石英晶体、岩层剖面、放大镜、标本袋。","pos":[{"tag":"adj.","zh":"无机的；不含碳化合物的；非生物来源的（无比较级变化时用 more/most，也可直接作定语）"}],"collocations":[{"phrase":"inorganic chemistry","zh":"无机化学"},{"phrase":"inorganic compound","zh":"无机化合物"},{"phrase":"inorganic matter","zh":"无机物质"},{"phrase":"inorganic fertilizer","zh":"无机肥料；化肥"},{"phrase":"inorganic origin","zh":"无机成因"},{"phrase":"inorganic growth","zh":"外延式增长；靠并购而非自身经营实现的增长"}],"forms":[{"label":"比较级","form":"more inorganic（化学语境一般不用比较级，需要时用 more）"},{"label":"最高级","form":"most inorganic"},{"label":"副词形式","form":"inorganically（以无机的方式；非生物地）"},{"label":"作定语","form":"inorganic + 名词（如 inorganic salt、inorganic waste）"}],"derivatives":[{"word":"organ","pos":"n.","zh":"器官；风琴；机构"},{"word":"organic","pos":"adj.","zh":"有机的；生物体的；有机耕作的"},{"word":"organism","pos":"n.","zh":"生物体；有机体"},{"word":"organize","pos":"v.","zh":"组织；安排"},{"word":"organization","pos":"n.","zh":"组织；机构；编排"},{"word":"organelle","pos":"n.","zh":"细胞器"}],"senses":[{"no":"01","title":"Chemistry without carbon","titleCN":"无机化学：不以碳骨架为中心的化合物","definition":"describing chemical compounds that are not built on carbon chains or rings, the traditional dividing line of inorganic chemistry","definitionCN":"指不以碳链或碳环为骨架的化合物，这是无机化学与传统有机化学的分界","example":"Inorganic chemistry covers salts, metals, acids and coordination compounds.","exampleCN":"无机化学研究盐类、金属、酸以及配位化合物。","why":"The prefix in- negates organic, and organic chemistry was defined in the nineteenth century as the chemistry of carbon compounds, so everything outside that family became inorganic.","whyCN":"前缀 in- 否定 organic；19 世纪把有机化学界定为碳化合物的化学，于是不属于这一族的东西统统被叫作无机。"},{"no":"02","title":"Not made by living things","titleCN":"非生物来源：不经过生命过程形成","definition":"formed by physical or chemical processes alone, with no involvement of plants, animals or microbes","definitionCN":"仅由物理或化学过程形成，没有植物、动物或微生物参与","example":"The crystals grew by purely inorganic processes in the cave water.","exampleCN":"这些晶体在洞穴水里完全靠无机过程生长出来。","why":"The chemical division was extended to origins: what living bodies build is organic, what rock and water build is inorganic.","whyCN":"化学上的分界被推广到成因：生物体建造的属有机，岩石与水建造的属无机。"},{"no":"03","title":"Mineral ions in nutrition","titleCN":"无机养分：植物吸收的矿质离子","definition":"in biology, the mineral salts and ions that plants and animals take up, as opposed to carbon-based food molecules","definitionCN":"生物学中指动植物吸收的矿质盐与离子，与含碳的食物分子相对","example":"Plants absorb inorganic ions such as nitrate, phosphate and potassium from the soil.","exampleCN":"植物从土壤中吸收硝酸根、磷酸根、钾等无机离子。","why":"Nutrient studies separate the mineral ions a plant takes from the organic compounds it builds, so the adjective marks the raw mineral input.","whyCN":"养分研究把植物吸收的矿质离子与它合成的有机化合物分开，这个形容词就标出未加工的矿物输入。"},{"no":"04","title":"Abiotic origin in geology","titleCN":"地质无机成因：不经生物而形成的矿藏","definition":"in earth science, describing deposits or hydrocarbons whose origin is argued to be abiotic rather than biological","definitionCN":"地球科学中指其成因被主张为非生物而非生物的沉积物或碳氢化合物","example":"The debate over inorganic petroleum asks whether oil can form without buried organisms.","exampleCN":"关于无机石油的争论，追问的是石油能否不经埋藏的生物体而形成。","why":"The word lets geologists state a contested claim in one adjective: the material exists, but its source is not life.","whyCN":"这个形容词让地质学家用一个词表明有争议的主张：物质确实存在，但来源不是生命。"},{"no":"05","title":"Inorganic business growth","titleCN":"外延式增长：靠并购而非自身经营扩大","definition":"in business, growth achieved by buying other firms or assets rather than by expanding existing operations","definitionCN":"商业上指通过收购其他公司或资产、而非扩大自身经营获得的增长","example":"The group's expansion was largely inorganic, driven by a string of acquisitions.","exampleCN":"该集团的扩张基本是外延式的，靠一连串收购推动。","why":"Finance borrowed the living metaphor: organic growth grows from within like a body, while inorganic growth is assembled from outside parts.","whyCN":"金融借用了生物学隐喻：organic growth 像身体一样从内部生长，inorganic growth 则像从外部拼装零件。"},{"no":"06","title":"Lacking living structure","titleCN":"无生命结构：不会自我修复的整体","definition":"having no organised living structure, so that damage is permanent and no self-repair occurs","definitionCN":"没有有组织的生命结构，因而损伤不可逆、不会自我修复","example":"An inorganic body cannot heal itself, so every crack stays where it formed.","exampleCN":"无生命的物体无法自愈，因此每一道裂缝都会留在原处。","why":"This is the plain negation of the biological sense: whatever a living body does by organisation, an inorganic body cannot do.","whyCN":"这是生物学义项的直接否定：生命体靠组织结构做到的事，无机物体一件也做不到。"},{"no":"07","title":"Non-biodegradable waste","titleCN":"无机废弃物：不能靠微生物分解","definition":"in waste management, material such as glass, metal or plastic that microbes cannot break down","definitionCN":"废弃物管理中指玻璃、金属、塑料这类微生物无法分解的材料","example":"Inorganic waste such as glass and metal can be recycled instead of landfilled.","exampleCN":"玻璃、金属这类无机废弃物可以回收，而不必填埋。","why":"Because decomposition is a biological process, materials that resist it are grouped as inorganic regardless of their chemistry.","whyCN":"由于分解是生物过程，抵抗分解的材料就被归为无机，尽管其化学构成未必如此。"},{"no":"08","title":"Hard form in art and design","titleCN":"无机形态：几何、坚硬、不带生命曲线","definition":"in art and design criticism, describing shapes that are angular and lifeless rather than flowing and bodily","definitionCN":"艺术与设计批评中指棱角分明、没有生命感而非流畅有机的形态","example":"Her later sculptures moved from organic curves to hard inorganic geometry.","exampleCN":"她后期的雕塑从有机曲线转向坚硬的无机几何形态。","why":"Critics borrowed the adjective to contrast two families of form, so a welded plate can be called inorganic without any claim about chemistry.","whyCN":"批评家借用这个形容词来对照两类形态，因此一块焊接钢板也可以被称作无机的，而不涉及任何化学判断。"}],"etymology":{"intro":{"en":"Inorganic is the negative of organic, and organic descends from Greek organon 'tool, instrument, bodily organ'. The chemistry sense is a nineteenth-century narrowing of the word.","cn":"inorganic 是 organic 的否定形式，而 organic 出自希腊语 organon「工具、器械、身体器官」。化学义是 19 世纪对词义的收窄。"},"items":[{"era":"GREEK ORGANON","en":"Greek organon named a tool or implement and, in medicine and philosophy, an organ of the body. It is built on ergon 'work', so the underlying picture is an instrument for doing work.","cn":"希腊语 organon 指工具或器械，在医学与哲学中也指身体器官。它由 ergon「工作」构成，底层意象是「用于做工的器具」。"},{"era":"LATIN ORGANUM","en":"Latin took the word as organum, used for an instrument and later for a musical instrument. The adjective organicus appears in later Latin with the sense 'instrumental'.","cn":"拉丁语借入为 organum，指器具，后也指乐器。后期拉丁语中出现形容词 organicus，意为「器具的、工具性的」。"},{"era":"ENGLISH ORGANIC","en":"English organic appears around 1600, first meaning 'relating to bodily organs', then 'belonging to living things'. The exact first citation is uncertain.","cn":"英语 organic 约在 1600 年出现，最初意为「与身体器官有关的」，随后转为「属于生物的」。最早的确切书证存疑。"},{"era":"CHEMISTRY DIVIDES","en":"Around the 1840s chemists fixed a boundary: organic compounds contain carbon and were once thought to require a living force, while mineral compounds do not. Inorganic was coined for the second class.","cn":"约 1840 年代，化学家确定了一条界线：有机化合物含碳、曾被认为需要「生命力」参与，矿物化合物则不需要。inorganic 就是为后一类造的词。"},{"era":"THE LIVING FORCE FALLS","en":"When Wohler made urea from ammonium cyanate in 1828, the idea that organic compounds required life began to collapse, yet the chemical label organic survived and inorganic stayed its partner.","cn":"1828 年维勒用氰酸铵合成尿素后，「有机化合物必须有生命参与」的观念开始瓦解，但 organic 这一化学标签保留下来，inorganic 也随之成为它的对偶。"},{"era":"UNCERTAIN DETAILS","en":"The exact person who first wrote inorganic in its chemical sense is not recorded, and the first English date is uncertain; it is usually placed in the 1840s but the citation is not fixed.","cn":"来源不确定：最先以化学义使用 inorganic 的人并无记载，英语首见年代存疑，通常定在 1840 年代，但书证并不确定。"}]},"similar":{"note":{"en":"The first group holds words that look alike but divide the world differently; the second holds near-synonyms for 'not alive' that are often used loosely.","cn":"第一组是形近但划分世界方式不同的词；第二组是常被宽泛替换的「非生命」近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"organic","ipa":"/ɔːˈɡænɪk/","tag":"the direct opposite","definition":"Means carbon-based in chemistry, coming from living things, or grown without synthetic chemicals in farming. It is not simply the antonym of artificial.","definitionCN":"化学上指含碳的，也指来自生物的，或农业上不用合成化学品的。它并不等于「人造」的反义词。"},{"word":"nonorganic","ipa":"/ˌnɒnɔːˈɡænɪk/","tag":"farming label, not chemistry","definition":"Used mainly for food grown without organic certification. It says nothing about carbon compounds, so it is not a chemical term.","definitionCN":"主要用于未经有机认证生产的食品。它不涉及碳化合物，因此不是化学术语。"},{"word":"mineral","ipa":"/ˈmɪnərəl/","tag":"material class","definition":"Names a natural inorganic solid with a definite structure. All minerals are inorganic in origin, but many inorganic substances, such as table salt in solution, are not minerals.","definitionCN":"指具有确定结构的天然无机固体。矿物在成因上都是无机的，但许多无机物（如溶解的食盐）并不是矿物。"}]},{"heading":"NEAR MEANING","entries":[{"word":"abiotic","ipa":"/ˌeɪbaɪˈɒtɪk/","tag":"no life involved","definition":"Describes a process or factor with no biological component. It overlaps with inorganic origin but is used of environments and factors, not of substances.","definitionCN":"描述不含生物成分的过程或因素。它与无机成因重叠，但多用于环境与因素，而不是具体物质。"},{"word":"inanimate","ipa":"/ɪnˈænɪmət/","tag":"without life, not without carbon","definition":"Means 'not alive' and can describe a stone, a robot or a dull party. It says nothing about chemical composition, unlike inorganic.","definitionCN":"意为「无生命的」，可形容石头、机器人或沉闷的聚会。与 inorganic 不同，它完全不涉及化学组成。"},{"word":"synthetic","ipa":"/sɪnˈθetɪk/","tag":"made by humans","definition":"Means produced by chemical synthesis rather than extracted from nature. A synthetic compound may be organic, so it is not a synonym of inorganic.","definitionCN":"指通过化学合成而非从自然中提取得到的。合成化合物也可能是有机的，因此它不是 inorganic 的同义词。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"in- 'not' + organic: the chemistry of everything that is not carbon-based.","cn":"in-「不」+ organic：研究一切不以碳为骨架之物的化学。"},{"en":"The family runs organ, organic, organism, organize, organization and organelle.","cn":"同族词包括 organ、organic、organism、organize、organization、organelle。"},{"en":"Fixed phrases mark the field: inorganic chemistry, inorganic compound, inorganic fertilizer, inorganic waste.","cn":"固定搭配标出领域：无机化学、无机化合物、无机肥料、无机废弃物。"},{"en":"Organic means carbon-based in chemistry and certified in farming; inorganic is the chemical opposite only.","cn":"organic 在化学上指含碳、在农业上指获认证；inorganic 只是化学上的对立面。"},{"en":"Wohler's urea synthesis in 1828 ended the belief that organic compounds needed a living force.","cn":"1828 年维勒合成尿素，终结了「有机化合物需要生命力」的信念。"}],"abstract":[{"en":"Picture a salt crystal growing in dark water, with no leaf, no cell and no seed anywhere near it.","cn":"想象一枚盐晶在暗处的水中生长，周围没有叶子、没有细胞、也没有种子。"},{"en":"Picture a company bought whole and bolted on, adding size without growing a single new customer of its own.","cn":"想象一家公司被整体买下、拼接进来，规模变大了，却没有自己长出一个新客户。"},{"en":"Picture a welded steel sculpture: hard angles, no curve that suggests a body.","cn":"想象一件焊接钢雕：棱角坚硬，没有一处曲线暗示身体。"}]},"examples":[{"en":"Inorganic salts dissolved in the lake water raise its mineral content.","cn":"溶解在湖水中的无机盐提高了它的矿物含量。"},{"en":"The lab keeps organic and inorganic samples in separate cabinets.","cn":"实验室把有机样品与无机样品存放在不同的柜子里。"},{"en":"Investors questioned whether the company's inorganic growth could be sustained.","cn":"投资者质疑这家公司的外延式增长能否持续。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「in（不）+ organic（有机的）」——不属于生命与碳化学的东西 → inorganic 无机的","word":"inorganic"},"root":"拉丁 in-「不」+ 希腊 organon「器官、工具」→ 英语 organic；19 世纪化学把不含碳的化合物称作 inorganic。","sensesIntro":{"en":"Eight senses follow one negation: the word first removes carbon from chemistry, then removes life from origin, then removes inner organisation from growth, waste and form.","cn":"八个义项沿同一条否定线展开：先把碳从化学中拿掉，再把生命从成因中拿掉，最后把内在组织性从增长、废弃物与形态中拿掉。"},"semanticMap":{"core":{"en":"CORE IMAGE: a mineral crust with no leaf, no cell and no seed anywhere near it.","cn":"核心意象：一层矿物结壳，周围没有叶子、没有细胞、也没有种子。"},"chain":["NOT CARBON","NOT LIVING","MINERAL INPUT","ABIOTIC ORIGIN","OUTSIDE GROWTH","HARD FORM"],"branches":[{"senses":"S1","en":"CHEMISTRY: carbon is the dividing line, so salts, metals and acids are inorganic.","cn":"化学分界：碳是界线，因此盐、金属与酸都属无机。"},{"senses":"S2 · S4","en":"ORIGIN: the same line is drawn through time, asking whether life took part in forming the material.","cn":"成因：同一条界线沿时间延伸，追问生命是否参与了物质的形成。"},{"senses":"S3","en":"RAW INPUT: plants absorb mineral ions as inorganic nutrients before building organic matter.","cn":"原料输入：植物先吸收作为无机养分的矿质离子，再合成有机物。"},{"senses":"S5","en":"EXTERNAL GROWTH: business borrows the biology, so buying a firm is inorganic and adding customers is organic.","cn":"外部增长：商业借用生物学说法，收购公司属无机，新增客户属有机。"},{"senses":"S6 · S7 · S8","en":"LIFELESS MATTER: no self-repair, no decomposition and no organic curve all follow from the same missing organisation.","cn":"无生命物质：不会自愈、不会被分解、没有有机曲线，都源于同一种「缺少组织性」。"}]},"affixes":{"intro":{"en":"Inorganic is a Latin negative prefix sitting on a Greek-derived adjective, so the word literally says 'not organ-like'.","cn":"inorganic 是拉丁否定前缀加在一个源自希腊语的形容词上，字面意思就是「不像器官的」。"},"latinIntro":{"en":"The Latin negative prefix in- (im-, il-, ir- before certain sounds) marks absence, while organicus and organum carry the Greek organon into English.","cn":"拉丁否定前缀 in-（在部分音前作 im-、il-、ir-）表示缺失，而 organicus 与 organum 把希腊语 organon 带进英语。"},"items":[{"word":"inorganic","structure":"in- (not) + organic","meaning":"not carbon-based; not produced by life","meaningCN":"不含碳骨架的；非生命产生的","example":"Inorganic pigments resist fading in sunlight.","exampleCN":"无机颜料在阳光下不易褪色。"},{"word":"organic","structure":"organ + -ic (adjective)","meaning":"relating to organs or to living, carbon-based matter","meaningCN":"与器官有关的；有机的、含碳的","example":"Organic compounds always contain carbon-hydrogen bonds.","exampleCN":"有机化合物总含有碳氢键。"},{"word":"organ","structure":"Greek organon (tool, instrument)","meaning":"a body part with a function; also an instrument","meaningCN":"具有特定功能的器官；也指乐器或机构","example":"The liver is the largest internal organ.","exampleCN":"肝脏是最大的内部器官。"},{"word":"organism","structure":"organ + -ism (system, condition)","meaning":"a living body made of coordinated parts","meaningCN":"由协调运作的各部分构成的生物体","example":"A single-celled organism still counts as life.","exampleCN":"单细胞生物仍然算作生命。"},{"word":"organize","structure":"organ + -ize (to make, to form)","meaning":"to arrange parts into a working whole","meaningCN":"把各部分安排成可运作的整体","example":"She organized the files by project.","exampleCN":"她按项目整理了档案。"},{"word":"organization","structure":"organize + -ation (noun of action)","meaning":"the act of arranging; a structured body","meaningCN":"安排的行为；有结构的团体","example":"The organization employs forty researchers.","exampleCN":"该机构雇用了四十名研究人员。"},{"word":"organelle","structure":"organ + -elle (French diminutive)","meaning":"a small functional structure inside a cell","meaningCN":"细胞内部的小型功能结构","example":"Mitochondria are organelles that release energy.","exampleCN":"线粒体是释放能量的细胞器。"},{"word":"inorganic chemistry","structure":"inorganic + chemistry (Greek khemeia)","meaning":"the branch studying non-carbon compounds","meaningCN":"研究非碳化合物的化学分支","example":"Inorganic chemistry explains why rust forms.","exampleCN":"无机化学解释了铁锈为何生成。"}],"latinEntries":[{"word":"in-","structure":"in- (negative prefix, assimilated to im-, il-, ir-)","meaning":"not, without","meaningCN":"不、无"},{"word":"organum","structure":"organum, organi (n., second declension; from Greek organon)","meaning":"instrument, tool, organ","meaningCN":"器具、工具、器官"},{"word":"organicus","structure":"organicus (adj., later Latin; from Greek organikos)","meaning":"instrumental; of an organ","meaningCN":"器具的；器官的"}]}},{"word":"carbon dioxide","ipa_uk":"/ˌkɑːbən daɪˈɒksaɪd/","ipa_us":"/ˌkɑːrbən daɪˈɑːksaɪd/","definition_zh":"二氧化碳（CO₂）；一种无色无味的温室气体","definition_en":"a colourless, odourless gas with the formula CO2, produced by burning carbon and by respiration, and absorbed by plants in photosynthesis","core_image":"一串气泡从汽水中升起，旁边一株绿植的叶片正把这些气泡吸进去","scene":"When the burners were lit, the carbon dioxide level inside the sealed chamber rose within minutes.","sceneCN":"这里 carbon dioxide 指「燃烧产生的二氧化碳气体」（第 1 个义项：CO₂ 这种物质本身）；点燃燃烧器后，密闭舱内的二氧化碳浓度几分钟内就升高了。图中可辨识物件：燃烧器、密封舱、气体检测仪、浓度曲线。","pos":[{"tag":"n.","zh":"二氧化碳（不可数名词；化学式 CO₂，缩写 CO2）"}],"collocations":[{"phrase":"carbon dioxide emissions","zh":"二氧化碳排放"},{"phrase":"carbon dioxide concentration","zh":"二氧化碳浓度"},{"phrase":"atmospheric carbon dioxide","zh":"大气中的二氧化碳"},{"phrase":"carbon dioxide capture","zh":"二氧化碳捕集"},{"phrase":"dissolved carbon dioxide","zh":"溶解态二氧化碳"},{"phrase":"carbon dioxide equivalent","zh":"二氧化碳当量"}],"forms":[{"label":"化学式","form":"CO₂（下标 2 表示两个氧原子）"},{"label":"缩写","form":"CO2（键盘书写形式）"},{"label":"不可数用法","form":"carbon dioxide（一般不加 -s；论及多种来源时可说 sources of carbon dioxide）"},{"label":"作定语","form":"carbon-dioxide + 名词（如 carbon-dioxide emissions，加连字符）"},{"label":"旧称","form":"fixed air（18 世纪对二氧化碳的旧称）"}],"derivatives":[{"word":"carbon","pos":"n.","zh":"碳；炭"},{"word":"dioxide","pos":"n.","zh":"二氧化物"},{"word":"monoxide","pos":"n.","zh":"一氧化物（如 carbon monoxide 一氧化碳）"},{"word":"carbonate","pos":"n.","zh":"碳酸盐"},{"word":"carbonic","pos":"adj.","zh":"碳酸的"},{"word":"decarbonize","pos":"v.","zh":"脱碳；减少碳排放"}],"senses":[{"no":"01","title":"The gas itself","titleCN":"二氧化碳：由碳与氧组成的无色气体","definition":"the chemical compound CO2, one carbon atom bonded to two oxygen atoms","definitionCN":"化学式 CO₂ 的化合物，一个碳原子与两个氧原子结合","example":"Every breath you exhale adds carbon dioxide to the room.","exampleCN":"你呼出的每一口气都会给房间增加二氧化碳。","why":"The name is a plain chemical description: carbon plus di- 'two' plus oxide, so one carbon with two oxygens.","whyCN":"这个名字就是直白的化学描述：carbon（碳）加 di-「二」再加 oxide（氧化物），即一个碳配两个氧。"},{"no":"02","title":"Product of respiration","titleCN":"呼吸产物：血液与呼气中的二氧化碳","definition":"the waste gas released by cells when they break down food, carried in blood and expelled through the lungs","definitionCN":"细胞分解食物时释放的废气，由血液运送并经肺排出","example":"Blood carbon dioxide is monitored during surgery because it helps drive breathing.","exampleCN":"手术中要监测血中二氧化碳，因为它参与驱动呼吸。","why":"Physiology uses the same molecule as a signal: its level tells the body how fast to breathe.","whyCN":"生理学把同一分子当作信号：它的浓度告诉身体该以多快的节奏呼吸。"},{"no":"03","title":"Input for photosynthesis","titleCN":"光合原料：植物从空气中固定的碳源","definition":"the carbon source that plants, algae and some bacteria fix into sugars using light energy","definitionCN":"植物、藻类与部分细菌利用光能把其固定为糖类的碳源","example":"Plants pull carbon dioxide from the air and fix it into sugar.","exampleCN":"植物从空气中吸收二氧化碳，并把它固定成糖。","why":"The same gas that is waste for animals is raw material for plants, so the noun appears on both sides of the carbon cycle.","whyCN":"对动物是废气、对植物是原料，同一个名词因此出现在碳循环的两端。"},{"no":"04","title":"Greenhouse gas","titleCN":"温室气体：吸收热量改变气候","definition":"the principal long-lived greenhouse gas whose accumulation in the atmosphere raises global temperature","definitionCN":"最主要的持久温室气体，其在大气中累积会提高全球温度","example":"Carbon dioxide traps heat and accounts for most of the observed warming.","exampleCN":"二氧化碳截留热量，造成了观测到的变暖中的大部分。","why":"Climate science names the molecule by its radiative effect, so a chemical formula becomes shorthand for a policy problem.","whyCN":"气候科学按辐射效应来称呼这个分子，于是化学式成了政策问题的代称。"},{"no":"05","title":"Product of combustion","titleCN":"燃烧产物：含碳燃料氧化的结果","definition":"the gas released when carbon-containing fuel burns completely in enough oxygen","definitionCN":"含碳燃料在氧气充足时完全燃烧所释放的气体","example":"A well-adjusted flame produces mainly water vapour and carbon dioxide.","exampleCN":"调节良好的火焰主要产生水蒸气和二氧化碳。","why":"Complete combustion oxidises every carbon atom, and the stable end product is exactly this molecule.","whyCN":"完全燃烧把每个碳原子都氧化，最稳定的终产物正是这个分子。"},{"no":"06","title":"Industrial gas and feedstock","titleCN":"工业气体：制冷、萃取与化工原料","definition":"the compressed or liquefied gas used in refrigeration, extraction, welding and chemical synthesis","definitionCN":"以压缩或液化形式用于制冷、萃取、焊接与化学合成的气体","example":"The plant uses carbon dioxide as a refrigerant and in urea production.","exampleCN":"该厂用二氧化碳作制冷剂，也用于生产尿素。","why":"Industry exploits the gas as a cheap, non-flammable working fluid, so the everyday substance acquires a technical role.","whyCN":"工业把它当作廉价、不可燃的工作介质，于是这种日常物质获得了一个技术角色。"},{"no":"07","title":"Carbonation of drinks","titleCN":"饮品碳酸化：气泡与口感","definition":"the dissolved gas that gives sparkling drinks their bubbles and slightly acidic taste","definitionCN":"溶解在饮料中、带来气泡与微酸口感的气体","example":"Sparkling water is ordinary water held under carbon dioxide pressure.","exampleCN":"气泡水就是加压二氧化碳下的普通水。","why":"Beverage makers simply press the gas into liquid, so the everyday sense is the same compound seen at the table.","whyCN":"饮料生产者只是把这种气体压进液体，日常义项就是餐桌上的同一种化合物。"},{"no":"08","title":"Fire suppression","titleCN":"灭火用途：隔绝氧气让火熄灭","definition":"the gas released in enclosed spaces to displace oxygen and stop combustion without water damage","definitionCN":"在密闭空间释放以排挤氧气、在不造成水损的情况下停止燃烧的气体","example":"The server room is protected by carbon dioxide extinguishers.","exampleCN":"机房由二氧化碳灭火器保护。","why":"Here the gas is valued for what it lacks: no oxygen support for fire remains once it fills the room.","whyCN":"这里看重的是它「没有」的东西：一旦充满房间，火就得不到氧气支持。"}],"etymology":{"intro":{"en":"The compound is named from Latin carbo 'charcoal' and Greek di- 'two' plus English oxide, itself coined from French oxygene. The gas's earlier name was 'fixed air'.","cn":"这个化合物名由拉丁 carbo「木炭」、希腊 di-「二」与英语 oxide 构成，而 oxide 又出自法语 oxygene。它更早的名字是「固定空气」。"},"items":[{"era":"LATIN CARBO","en":"Latin carbo, carbonis meant 'charcoal, a glowing coal'. English took the word through French charbon, and carbon was named as an element in the 1780s.","cn":"拉丁 carbo、carbonis 指「木炭、烧红的炭」。英语经法语 charbon 借入，carbon 在 1780 年代被定名为元素。"},{"era":"ENGLISH CARBON","en":"The European chemical tradition borrowed Latin names for new elements, so carbo supplied the root for carbon while the -on ending followed the model of other element names.","cn":"欧洲化学传统为新元素借用拉丁名，因此 carbo 提供 carbon 的词根，词尾 -on 则沿袭其他元素名的模式。"},{"era":"FRENCH OXYGENE","en":"In 1777 Lavoisier coined French oxygene from Greek oxys 'sharp, acid' and -gene 'producer', believing the gas generated acids. Oxide was then formed from it.","cn":"1777 年拉瓦锡由希腊 oxys「尖锐的、酸性的」与 -gene「产生者」造出法语 oxygene，因他相信这种气体产生酸。oxide 随后由它构成。"},{"era":"DI- AND DIOXIDE","en":"The prefix di- comes from Greek dis 'twice', and dioxide names an oxide with two oxygen atoms per molecule. The same di- pattern appears in monoxide and dioxide pairs.","cn":"前缀 di- 出自希腊 dis「两次」，dioxide 指每个分子含两个氧原子的氧化物。monoxide 与 dioxide 这一对用的也是同一种 di- 构词模式。"},{"era":"FIXED AIR AND CO2","en":"Joseph Black isolated the gas in the 1750s and called it 'fixed air'. The compound name carbon dioxide settled in the early nineteenth century as atomic formulas became standard.","cn":"约瑟夫·布拉克在 1750 年代分离出这种气体，称之为「固定空气」。随着原子式成为标准，carbon dioxide 这一化合物名在 19 世纪初固定下来。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertainty: the first English citation of carbon dioxide is uncertain, usually placed between 1800 and 1830; the exact authorship of the compound name cannot be traced with confidence.","cn":"来源不确定：carbon dioxide 的英语首见书证年代存疑，通常放在 1800 至 1830 年间；这一化合物名的确切造词者也难以确证。"}]},"similar":{"note":{"en":"The first group holds formulas that look almost identical but differ by one oxygen atom or one proton; the second holds other gases of the same air.","cn":"第一组是化学式几乎相同、只差一个氧原子或一个氢原子的词；第二组是同处一片天空的其他气体。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"carbon monoxide","ipa":"/ˌkɑːbən məˈnɒksaɪd/","tag":"one oxygen, deadly","definition":"CO, one carbon with one oxygen. It binds haemoglobin far more tightly than oxygen and is the commonest cause of gas poisoning.","definitionCN":"CO，一个碳配一个氧。它比氧更牢地结合血红蛋白，是气体中毒最常见的原因。"},{"word":"carbonate","ipa":"/ˈkɑːbəneɪt/","tag":"a salt, not a gas","definition":"A salt containing the CO3²⁻ group, such as calcium carbonate in limestone. It is a solid ionic compound, not a molecule in the air.","definitionCN":"含 CO₃²⁻ 基团的盐，如石灰石中的碳酸钙。它是固态离子化合物，而不是空气中的分子。"},{"word":"carbonic acid","ipa":"/kɑːˌbɒnɪk ˈæsɪd/","tag":"the dissolved acid form","definition":"H2CO3, formed when carbon dioxide dissolves in water. It exists mainly in equilibrium with dissolved gas and is what makes soda slightly acidic.","definitionCN":"H₂CO₃，二氧化碳溶于水时形成。它主要以与溶解气体的平衡形式存在，正是它让汽水略带酸性。"}]},{"heading":"NEAR MEANING","entries":[{"word":"methane","ipa":"/ˈmeθeɪn/","tag":"stronger greenhouse gas","definition":"CH4, the main component of natural gas. It traps far more heat per molecule than carbon dioxide but is far less abundant.","definitionCN":"CH₄，天然气的主要成分。单个分子截留的热量远多于二氧化碳，但在大气中丰度低得多。"},{"word":"water vapour","ipa":"/ˈwɔːtə ˈveɪpə/","tag":"the commonest greenhouse gas","definition":"Water in gas form. It absorbs more infrared than carbon dioxide, yet its amount is controlled by temperature and it cycles out within days.","definitionCN":"气态水。它吸收的红外辐射比二氧化碳更多，但其含量受温度控制，并在数日内循环离开大气。"},{"word":"nitrogen","ipa":"/ˈnaɪtrədʒən/","tag":"the bulk gas, not a greenhouse gas","definition":"N2, about four fifths of the air. It is almost inert and contributes almost nothing to warming, so it is never grouped with carbon dioxide as a greenhouse gas.","definitionCN":"N₂，约占空气的五分之四。它几乎惰性，对变暖几乎没有贡献，因此从不与二氧化碳一起归入温室气体。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"carbon + di- 'two' + oxide: one carbon, two oxygens.","cn":"carbon + di-「二」+ oxide：一个碳，两个氧。"},{"en":"Its eighteenth-century name was 'fixed air', because it could be 'fixed' in solids such as limestone.","cn":"它在 18 世纪叫「固定空气」，因为它能被「固定」进石灰石这类固体中。"},{"en":"The carbon cycle runs both ways: animals exhale it, plants fix it.","cn":"碳循环双向运行：动物呼出它，植物固定它。"},{"en":"Fixed phrases mark the fields: carbon dioxide emissions, concentration, capture, equivalent.","cn":"固定搭配标出领域：二氧化碳排放、浓度、捕集、当量。"},{"en":"The gas cools (refrigerant), extracts (supercritical fluid) and extinguishes (fire suppression).","cn":"这种气体能制冷、能萃取、也能灭火。"}],"abstract":[{"en":"Picture bubbles rising in a glass and a leaf on the windowsill quietly taking them in.","cn":"想象玻璃杯里气泡上升，窗台上的叶子正悄悄把它们收进去。"},{"en":"Picture a closed greenhouse: every extra flame adds a layer of invisible glass above the plants.","cn":"想象一座封闭温室：每多一团火焰，就在植物上方加了一层看不见的玻璃。"},{"en":"Picture a sealed server room filling with a gas that leaves no oxygen for any spark.","cn":"想象密封的机房被一种气体充满，任何火花都得不到氧气。"}]},"examples":[{"en":"Atmospheric carbon dioxide has risen sharply since the industrial revolution.","cn":"自工业革命以来，大气中的二氧化碳大幅上升。"},{"en":"The diver's exhaled carbon dioxide is absorbed by a scrubber canister.","cn":"潜水员呼出的二氧化碳由吸收罐吸收。"},{"en":"Adding carbon dioxide to the greenhouse boosted tomato growth in winter.","cn":"在温室中补充二氧化碳提高了冬季番茄的生长速度。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「carbon（碳）+ dioxide（二氧化物）」——碳烧完后的产物 → carbon dioxide 二氧化碳","word":"carbon dioxide"},"root":"拉丁 carbo「木炭」→ 英语 carbon；希腊 di-「二」+ 法语 oxide「氧化物」；英语 carbon dioxide。","sensesIntro":{"en":"Eight senses follow one molecule through the carbon cycle: it is made by breath and fire, taken in by leaves, kept in the air, dissolved in drinks, and finally used as a working gas.","cn":"八个义项让同一个分子走完碳循环：由呼吸与火焰产生，被叶片吸收，留在大气，溶于饮料，最终又被当作工业气体使用。"},"semanticMap":{"core":{"en":"CORE IMAGE: bubbles leaving a drink and being drawn into a leaf.","cn":"核心意象：气泡离开饮料，又被叶片吸进去。"},"chain":["BURN OR BREATHE","FORM THE GAS","ENTER THE AIR","FEED THE LEAF","TRAP HEAT","SERVE INDUSTRY"],"branches":[{"senses":"S1 · S5","en":"MAKING IT: combustion and respiration both oxidise carbon, so the gas is a shared end product.","cn":"生成：燃烧与呼吸都在氧化碳，因此这种气体是共同的终产物。"},{"senses":"S2","en":"INSIDE THE BODY: the same gas becomes a physiological signal for breathing.","cn":"体内：同一种气体变成控制呼吸的生理信号。"},{"senses":"S3","en":"PLANT FOOD: leaves reverse the animal direction and fix the carbon into sugar.","cn":"植物养料：叶片把动物的方向反转，把碳固定成糖。"},{"senses":"S4","en":"ATMOSPHERE: because it absorbs infrared, a formula turns into a climate policy term.","cn":"大气：由于吸收红外，一个化学式变成了气候政策术语。"},{"senses":"S6 · S7 · S8","en":"WORKING GAS: the same molecule cools, carbonates and extinguishes, all by being easy to compress and hard to burn.","cn":"工作气体：同一分子用于制冷、碳酸化与灭火，靠的都是易压缩、不可燃。"}]},"affixes":{"intro":{"en":"Carbon dioxide is a compound name built from three pieces: a Latin root for charcoal, a Greek numeral prefix, and a chemical suffix for oxygen compounds.","cn":"carbon dioxide 是由三块拼成的化合物名：表示木炭的拉丁词根、希腊数词前缀，以及表示含氧化合物的化学后缀。"},"latinIntro":{"en":"Latin carbo supplies carbon and its whole family, while the chemical suffix -ide came through French oxide, itself built on oxygene.","cn":"拉丁 carbo 提供 carbon 及其整族派生词，化学后缀 -ide 则经法语 oxide 传入，而 oxide 又建立在 oxygene 之上。"},"items":[{"word":"carbon dioxide","structure":"carbon + di- (two) + oxide","meaning":"CO2; the gas of combustion, respiration and photosynthesis","meaningCN":"CO₂；燃烧、呼吸与光合作用中的气体","example":"Carbon dioxide levels are logged every hour.","exampleCN":"二氧化碳浓度每小时记录一次。"},{"word":"carbon","structure":"Latin carbo, carbon- (charcoal)","meaning":"the element with atomic number 6","meaningCN":"原子序数为 6 的元素","example":"Carbon forms four bonds in organic molecules.","exampleCN":"碳在有机分子中形成四个键。"},{"word":"dioxide","structure":"di- (two) + oxide","meaning":"an oxide with two oxygen atoms","meaningCN":"含两个氧原子的氧化物","example":"Titanium dioxide is used as a white pigment.","exampleCN":"二氧化钛被用作白色颜料。"},{"word":"monoxide","structure":"mono- (one) + oxide","meaning":"an oxide with one oxygen atom","meaningCN":"含一个氧原子的氧化物","example":"Carbon monoxide is odourless and dangerous.","exampleCN":"一氧化碳无味且危险。"},{"word":"oxide","structure":"French oxide, from oxygene + -ide","meaning":"a compound of oxygen with another element","meaningCN":"氧与另一种元素形成的化合物","example":"Iron oxide gives the soil its red colour.","exampleCN":"氧化铁让土壤呈红色。"},{"word":"carbonate","structure":"carbon + -ate (salt suffix)","meaning":"a salt containing the CO3 group","meaningCN":"含 CO₃ 基团的盐","example":"Coral reefs are built of calcium carbonate.","exampleCN":"珊瑚礁由碳酸钙构成。"},{"word":"carbonic","structure":"carbon + -ic (acid-forming adjective)","meaning":"relating to carbon in its higher oxidation state","meaningCN":"与高价态碳有关的","example":"Carbonic acid forms when the gas dissolves.","exampleCN":"这种气体溶解时形成碳酸。"},{"word":"decarbonize","structure":"de- (remove) + carbon + -ize","meaning":"to reduce or remove carbon emissions","meaningCN":"减少或消除碳排放","example":"The city plans to decarbonize its bus fleet.","exampleCN":"该市计划让其公交车队脱碳。"},{"word":"carboniferous","structure":"carbon + -ferous (bearing)","meaning":"coal-bearing; also the coal-forming geological period","meaningCN":"含煤的；也指成煤的地质时期","example":"Carboniferous rocks hold most of Europe's coal.","exampleCN":"石炭纪岩层蕴藏欧洲大部分的煤。"}],"latinEntries":[{"word":"carbo","structure":"carbo, carbonis (m., third declension)","meaning":"charcoal, ember","meaningCN":"木炭、余烬"},{"word":"oxygène","structure":"French coinage (1777) from Greek oxys + -gene","meaning":"acid-former; the gas later called oxygen","meaningCN":"成酸者；后被称作氧的气体"},{"word":"oxidum","structure":"New Latin oxidum (n., second declension)","meaning":"oxide, a compound with oxygen","meaningCN":"氧化物，含氧的化合物"}]}},{"word":"oxygen","ipa_uk":"/ˈɒksɪdʒən/","ipa_us":"/ˈɑːksɪdʒən/","definition_zh":"氧；氧气","definition_en":"the chemical element of atomic number 8, a colourless gas forming about a fifth of the air and needed by most living things","core_image":"一支试管里的气泡汇入呼吸面罩，面罩外的空气被画成淡蓝色的同心圈","scene":"The climbers carried oxygen cylinders because the air at that altitude holds too little of it to breathe.","sceneCN":"这里 oxygen 指「供呼吸用的氧气」（第 2 个义项：空气中可呼吸的氧分子）；海拔太高，空气里的氧不足以维持呼吸，登山者只能自带氧气瓶。图中可辨识物件：氧气瓶、呼吸面罩、雪线、气压表。","pos":[{"tag":"n.","zh":"氧；氧气（不可数；指氧气瓶等具体容器时可说 an oxygen cylinder）"}],"collocations":[{"phrase":"dissolved oxygen","zh":"溶解氧"},{"phrase":"oxygen supply","zh":"供氧；氧气供应"},{"phrase":"oxygen therapy","zh":"氧疗"},{"phrase":"liquid oxygen","zh":"液氧"},{"phrase":"oxygen saturation","zh":"血氧饱和度"},{"phrase":"oxygen uptake","zh":"摄氧量"}],"forms":[{"label":"不可数用法","form":"oxygen（指元素或气体时不加 -s）"},{"label":"化学式","form":"O₂（双原子分子）"},{"label":"复数（少用）","form":"oxygens（化学语境指多种氧原子或样本）"},{"label":"形容词形式","form":"oxygenic（产氧的；含氧的）"},{"label":"相关动词","form":"oxygenate（给……加氧）"}],"derivatives":[{"word":"oxygenate","pos":"v.","zh":"给……充氧；氧合"},{"word":"oxygenation","pos":"n.","zh":"氧合；加氧过程"},{"word":"oxygenic","pos":"adj.","zh":"产氧的；含氧的"},{"word":"oxide","pos":"n.","zh":"氧化物"},{"word":"dioxide","pos":"n.","zh":"二氧化物"},{"word":"deoxygenate","pos":"v.","zh":"脱氧；去除氧"}],"senses":[{"no":"01","title":"The element","titleCN":"氧元素：原子序数 8","definition":"the chemical element with atomic number 8, the most abundant element in the earth's crust by mass","definitionCN":"原子序数为 8 的元素，按质量计是地壳中含量最高的元素","example":"Oxygen has eight protons and usually eight neutrons.","exampleCN":"氧有八个质子，通常也有八个中子。","why":"The name labels a single element rather than a substance, so it applies to atoms in water and rock as much as to the gas.","whyCN":"这个名字标的是单一元素而非某种实物，因此水与岩石里的氧原子同样适用，而不只是空气里的气体。"},{"no":"02","title":"Breathable gas","titleCN":"可呼吸的氧气：空气中的双原子分子","definition":"molecular O2, the form in the air that animals absorb through lungs or gills","definitionCN":"空气中的双原子分子 O₂，动物通过肺或鳃吸收的形式","example":"Divers watch their oxygen supply as the tank empties.","exampleCN":"气瓶见底时，潜水员会紧盯氧气存量。","why":"Daily usage quietly narrows the element to its diatomic gas, because that is the form bodies can actually take in.","whyCN":"日常用法把元素悄悄收窄为双原子气体，因为那是身体真正能吸入的形式。"},{"no":"03","title":"Dissolved oxygen in water","titleCN":"溶解氧：水体中可供水生生物利用的氧","definition":"O2 dissolved in water, measured as the key indicator of whether aquatic life can survive","definitionCN":"溶于水中的 O₂，是判断水生生物能否存活的关键指标","example":"Low dissolved oxygen kills fish before any toxin does.","exampleCN":"溶解氧过低会比任何毒物更早杀死鱼类。","why":"Water holds far less gas than air, so the dissolved fraction gets its own term in ecology and water management.","whyCN":"水中含气量远低于空气，因此溶解的那一部分在生态学与水管理中另有专门说法。"},{"no":"04","title":"Medical oxygen therapy","titleCN":"医疗氧疗：提高吸入气中的氧浓度","definition":"supplemental oxygen given to patients whose blood oxygen is too low","definitionCN":"给血氧过低的患者补充的氧气","example":"The nurse started oxygen when his saturation fell below ninety percent.","exampleCN":"他的血氧饱和度降到九成以下时，护士开始给他吸氧。","why":"Clinical usage treats the gas as a drug with a dose, so oxygen appears in prescriptions and ward charts.","whyCN":"临床把这种气体当作有剂量的药物，因此 oxygen 会出现在处方与病房记录上。"},{"no":"05","title":"Oxidizer in combustion","titleCN":"助燃剂：使燃烧更剧烈的氧化剂","definition":"the reactant that accepts electrons in combustion, letting fuels burn far faster than they would in plain air","definitionCN":"燃烧中接受电子的反应物，使燃料比在普通空气中烧得快得多","example":"Pure oxygen makes a spark become a flame in an instant.","exampleCN":"在纯氧中，一点火星瞬间就会变成火焰。","why":"Chemistry defines the element by its electron-hungry behaviour, and that behaviour is what fire exploits.","whyCN":"化学按「抢电子」的行为来定义这种元素，而火焰利用的正是这一行为。"},{"no":"06","title":"The acid-former that was wrong","titleCN":"成酸者：命名时的错误信念","definition":"the sense carried by the name itself, from Lavoisier's belief that oxygen was present in every acid","definitionCN":"名字本身携带的义项，源自拉瓦锡认为一切酸都含氧的信念","example":"The name oxygen preserves an early theory that later proved false.","exampleCN":"oxygen 这个名字保留了一个后来被证明错误的早期理论。","why":"Lavoisier built the name from Greek 'acid-producer', and although hydrochloric acid disproved it, the label was never replaced.","whyCN":"拉瓦锡用希腊语「成酸者」造了这个名字；尽管盐酸推翻了这一说法，标签却再没被更换。"},{"no":"07","title":"Atmospheric history","titleCN":"大气史：氧的累积改变地球","definition":"the rise of free oxygen in the early atmosphere, which oxidised minerals and made animal life possible","definitionCN":"早期大气中游离氧的上升，它氧化了矿物并使动物生命成为可能","example":"The Great Oxidation Event began when oxygen accumulated in the air.","exampleCN":"大氧化事件始于氧气在大气中累积之时。","why":"Earth scientists date rock layers by oxygen chemistry, so a gas becomes a geological clock.","whyCN":"地球科学家用氧的化学特征给岩层定年，于是某种气体成了地质时钟。"},{"no":"08","title":"A life-giving presence","titleCN":"像氧气一样：比喻不可或缺的活力","definition":"figuratively, something that a person or place needs in order to keep going, as if it were breathable air","definitionCN":"比喻某人或某处赖以维持的必需品，仿佛是可呼吸的空气","example":"The trip was oxygen for her after months of deadlines.","exampleCN":"在连续几个月的截止日期之后，这趟旅行对她就像氧气一样。","why":"Because the gas is the clearest case of 'you die without it', the noun slips into metaphor for any vital relief.","whyCN":"由于这种气体是「没有就活不下去」的最清楚例子，这个名词便滑入隐喻，指任何救命的缓解。"}],"etymology":{"intro":{"en":"Oxygen is a French coinage of 1777, built from Greek oxys 'sharp, acid' and -gene 'producer'. The name records a theory that was later overturned.","cn":"oxygen 是 1777 年的法语造词，由希腊 oxys「尖锐的、酸性的」与 -gene「产生者」构成。这个名字记录了一个后来被推翻的理论。"},"items":[{"era":"GREEK OXYS","en":"Greek oxys meant 'sharp' of taste and 'acid' in chemistry, from the same root as oxos ' vinegar'. It also described a sharp point or a keen mind.","cn":"希腊 oxys 指味觉上的「尖锐」，化学上即「酸性」，与 oxos「醋」同根。它也形容尖锐的端点或敏锐的心思。"},{"era":"GREEK -GENES","en":"The combining form -genes meant 'born of, producing', from the root gen- 'to be born, to produce'. It gave English -gen and -gene in many scientific words.","cn":"构词成分 -genes 意为「由……所生、产生」，出自词根 gen-「出生、产生」。它在许多科学词中给英语留下 -gen 与 -gene。"},{"era":"LAVOISIER 1777","en":"Lavoisier named the gas oxygene, taking it as the substance that produced acids. He had shown that air contains two distinct gases, one supporting life and one not.","cn":"拉瓦锡把这种气体命名为 oxygene，认为它是产生酸的物质。他已证明空气含有两种不同的气体，一种支持生命，一种不支持。"},{"era":"NEW LATIN OXYGENIUM","en":"Scientific Latin adopted the form oxygenium, and English oxygen entered through French in the late eighteenth century, soon after the chemical revolution.","cn":"科学拉丁语采用 oxygenium 这一形式，英语 oxygen 在 18 世纪末经法语进入，紧随化学革命之后。"},{"era":"THE THEORY FAILS","en":"Hydrochloric acid contains no oxygen, so the acid-former claim collapsed. Chemists kept the short, familiar name rather than rename the element.","cn":"盐酸不含氧，「成酸者」的主张随之破产。化学家保留了简短而熟悉的名字，而没有给元素改名。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertainty: the exact first English citation of oxygen is uncertain, usually given as 1789 but not fixed; whether Lavoisier or a collaborator first proposed the form is debated.","cn":"来源不确定：oxygen 的英语首见书证年代存疑，通常写作 1789 年但并不确定；究竟是拉瓦锡还是其合作者最先提出这一形式，仍有争议。"}]},"similar":{"note":{"en":"The first group holds words built on the same root that name different chemical objects; the second holds real gases that are often confused with oxygen in daily speech.","cn":"第一组是同根但指不同化学对象的词；第二组是日常话语中常与氧混淆的真实气体。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"oxide","ipa":"/ˈɒksaɪd/","tag":"a compound, not the element","definition":"A compound in which oxygen is bonded to another element, such as iron oxide. Oxygen is the element; an oxide is what it forms.","definitionCN":"氧与另一种元素结合成的化合物，如氧化铁。oxygen 是元素，oxide 是它形成的化合物。"},{"word":"oxygenation","ipa":"/ˌɒksɪdʒəˈneɪʃn/","tag":"the process","definition":"The act or process of adding oxygen to blood, water or a compound. It names an event, while oxygen names the substance.","definitionCN":"向血液、水或化合物加氧的行为或过程。它命名事件，而 oxygen 命名物质。"},{"word":"oxygenic","ipa":"/ˌɒksɪˈdʒenɪk/","tag":"the adjective","definition":"Describes something that produces or contains oxygen, especially photosynthesis that releases it.","definitionCN":"描述产生或含氧的事物，尤指释放氧的光合作用。"}]},{"heading":"NEAR MEANING","entries":[{"word":"air","ipa":"/eə/","tag":"the mixture, not the element","definition":"The mixture of gases we breathe, roughly four fifths nitrogen and one fifth oxygen. Oxygen is one component; air is the whole blend.","definitionCN":"我们呼吸的混合气体，约五分之四为氮、五分之一为氧。oxygen 是其中一个成分，air 是整体混合物。"},{"word":"ozone","ipa":"/ˈəʊzəʊn/","tag":"three atoms, not two","definition":"O3, a pungent gas formed from oxygen by electrical discharge. It shields the earth from ultraviolet light but is toxic to breathe.","definitionCN":"O₃，由氧经放电形成的有刺激性气味的气体。它替地球挡住紫外线，但吸入有毒。"},{"word":"hydrogen","ipa":"/ˈhaɪdrədʒən/","tag":"the other light gas","definition":"The lightest element, H2, which burns readily and was once used in airships. It reacts with oxygen to make water, so the two are partners, not synonyms.","definitionCN":"最轻的元素 H₂，易燃，曾用于飞艇。它与氧反应生成水，因此二者是搭档而非同义词。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Greek oxys 'acid' + -gene 'producer': the acid-former, an early theory kept in the name.","cn":"希腊 oxys「酸」+ -gene「产生者」：成酸者，一个被名字保留下来的早期理论。"},{"en":"The family runs oxide, dioxide, oxygenate, oxygenation, oxygenic and deoxygenate.","cn":"同族词包括 oxide、dioxide、oxygenate、oxygenation、oxygenic、deoxygenate。"},{"en":"Fixed phrases mark the fields: dissolved oxygen, oxygen therapy, oxygen saturation, liquid oxygen.","cn":"固定搭配标出领域：溶解氧、氧疗、血氧饱和度、液氧。"},{"en":"Air is about a fifth oxygen; the rest is mostly nitrogen.","cn":"空气约五分之一是氧，其余主要是氮。"},{"en":"Oxygen supports burning; nitrogen mostly does not, which is why a smothered flame dies.","cn":"氧助燃，氮基本不助燃，这也是被闷住的火焰会熄灭的原因。"}],"abstract":[{"en":"Picture a climber on a white ridge breathing from a tank while the thin air offers almost nothing.","cn":"想象雪脊上一名登山者靠气瓶呼吸，而稀薄的空气几乎什么也给不了。"},{"en":"Picture a spark in a jar of pure gas turning instantly into a blue flame.","cn":"想象纯氧罐中的一点火星瞬间变成蓝色火焰。"},{"en":"Picture a patient's face relaxing as the mask fogs slightly and the monitor number climbs.","cn":"想象患者的面罩起了一层薄雾，监护仪上的数字回升，他的表情放松下来。"}]},"examples":[{"en":"Oxygen makes up about twenty-one percent of dry air.","cn":"氧约占干燥空气的百分之二十一。"},{"en":"The lake's dissolved oxygen dropped after the algae bloom died off.","cn":"藻华死亡后，湖水的溶解氧下降。"},{"en":"Welders use oxygen to raise the temperature of a flame.","cn":"焊工用氧来提高火焰温度。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「oxy（酸）+ gen（产生）」——早期以为它是一切酸的来源 → oxygen 氧","word":"oxygen"},"root":"希腊 oxys「尖锐的、酸的」+ -genes「产生者」→ 法语 oxygene（1777，拉瓦锡）→ 英语 oxygen。","sensesIntro":{"en":"Eight senses follow one element from the periodic table into air, water, blood, fire and metaphor, with the sixth sense recording the error inside the name itself.","cn":"八个义项让同一个元素从周期表走进空气、水、血液与火焰，最后进入隐喻；第六个义项记录的是名字自身携带的错误。"},"semanticMap":{"core":{"en":"CORE IMAGE: pale blue rings of air drawn into a mask.","cn":"核心意象：淡蓝色的空气圈被吸进一只面罩。"},"chain":["ELEMENT EIGHT","TWO-ATOM GAS","BREATHE IT","DISSOLVE IT","OXIDIZE","GIVE LIFE"],"branches":[{"senses":"S1","en":"THE ATOM: the element is defined by its eight protons, present in water and rock alike.","cn":"原子：这个元素由八个质子定义，水与岩石中同样存在。"},{"senses":"S2 · S3","en":"AVAILABLE GAS: the diatomic form is what lungs and gills can take, whether in air or dissolved in water.","cn":"可用气体：双原子形式才是肺与鳃能吸收的，无论在空气中还是溶于水。"},{"senses":"S4 · S7","en":"MEASURED AND HISTORICAL: medicine doses it and geology dates the air by it.","cn":"计量与历史：医学按剂量使用，地质学用它给大气定年。"},{"senses":"S5","en":"ELECTRON HUNGER: the element's reactivity is what makes fire fast.","cn":"抢电子：元素的高反应性正是火之所以猛烈的原因。"},{"senses":"S6 · S8","en":"NAMING AND METAPHOR: one sense survives only inside the word's history, the other only in figurative speech.","cn":"命名与隐喻：一个义项只活在词的历史里，另一个只活在比喻用法中。"}]},"affixes":{"intro":{"en":"Oxygen is a scientific coinage, not an inherited word: a Greek adjective for 'sharp', a Greek suffix for 'producer', and a French chemical ending.","cn":"oxygen 是科学造词而非传承词：一个表示「尖锐」的希腊形容词、一个表示「产生者」的希腊后缀，以及一个法语化学词尾。"},"latinIntro":{"en":"Scientific Latin created oxygenium to fit Latin word shape, and the same -gen- root later produced hydrogen, nitrogen and nitrogenous.","cn":"科学拉丁语为符合拉丁词形造出 oxygenium，同一 -gen- 词根后来又生出 hydrogen、nitrogen 与 nitrogenous。"},"items":[{"word":"oxygen","structure":"Greek oxys + -genes (acid-producing)","meaning":"the element O and its diatomic gas","meaningCN":"元素 O 及其双原子气体","example":"Oxygen is consumed at the cathode.","exampleCN":"氧在阴极被消耗。"},{"word":"oxide","structure":"oxygen + -ide (compound suffix)","meaning":"a compound of oxygen with another element","meaningCN":"氧与另一种元素形成的化合物","example":"Aluminium oxide forms a protective layer.","exampleCN":"氧化铝形成一层保护膜。"},{"word":"dioxide","structure":"di- (two) + oxide","meaning":"an oxide carrying two oxygen atoms","meaningCN":"带两个氧原子的氧化物","example":"Carbon dioxide is a dioxide by formula.","exampleCN":"从化学式看，二氧化碳就是一种二氧化物。"},{"word":"oxygenate","structure":"oxygen + -ate (verb)","meaning":"to combine or enrich with oxygen","meaningCN":"使与氧结合；给……充氧","example":"The pump oxygenates the pond at night.","exampleCN":"水泵在夜间给池塘充氧。"},{"word":"oxygenation","structure":"oxygenate + -ion (noun of action)","meaning":"the process of adding oxygen","meaningCN":"加氧的过程","example":"Blood oxygenation improved within minutes.","exampleCN":"血液氧合在几分钟内改善。"},{"word":"oxygenic","structure":"oxygen + -ic (adjective)","meaning":"producing or containing oxygen","meaningCN":"产生氧或含氧的","example":"Oxygenic photosynthesis released the first free oxygen.","exampleCN":"产氧光合作用释放了最早的游离氧。"},{"word":"deoxygenate","structure":"de- (remove) + oxygen + -ate","meaning":"to remove oxygen from","meaningCN":"从……中除去氧","example":"Boiling deoxygenates the water.","exampleCN":"煮沸会使水脱氧。"},{"word":"hydrogen","structure":"Greek hydor + -genes (water-forming)","meaning":"the lightest element, partner of oxygen in water","meaningCN":"最轻的元素，在水中与氧为伴","example":"Hydrogen burns to form water.","exampleCN":"氢燃烧生成水。"},{"word":"nitrogen","structure":"Greek nitron + -genes (nitre-forming)","meaning":"the inert bulk gas of the atmosphere","meaningCN":"大气中占主体的惰性气体","example":"Nitrogen dilutes the oxygen in air.","exampleCN":"氮稀释了空气中的氧。"}],"latinEntries":[{"word":"oxygenium","structure":"oxygenium (n., New Latin, second declension)","meaning":"oxygen, the acid-former of early chemistry","meaningCN":"氧，早期化学所称的成酸者"},{"word":"oxidum","structure":"oxidum (n., New Latin, second declension)","meaning":"oxide","meaningCN":"氧化物"},{"word":"oxygenare","structure":"oxygenare (verb, New Latin, first conjugation)","meaning":"to combine with oxygen","meaningCN":"使与氧结合"}]}},{"word":"oxygenation","ipa_uk":"/ˌɒksɪdʒəˈneɪʃn/","ipa_us":"/ˌɑːksɪdʒəˈneɪʃn/","definition_zh":"氧合；加氧；充氧过程","definition_en":"the process of adding oxygen to a substance, to water, or to the blood","core_image":"透明管路里的血液由暗红转为鲜红，旁边水槽中气泡不断翻涌","scene":"The nurse watched the monitor as blood oxygenation improved within a minute of starting the mask.","sceneCN":"这里 oxygenation 指「血液氧合」（第 2 个义项：血液携带氧的过程）；戴上氧气面罩一分钟内，血氧就开始改善。图中可辨识物件：监护仪、氧气面罩、血液管路、血氧曲线。","pos":[{"tag":"n.","zh":"氧合；加氧；充氧（多作不可数名词，指过程时可加限定语如 tissue oxygenation）"}],"collocations":[{"phrase":"blood oxygenation","zh":"血液氧合"},{"phrase":"oxygenation level","zh":"氧合水平"},{"phrase":"tissue oxygenation","zh":"组织氧合"},{"phrase":"oxygenation system","zh":"充氧系统；增氧系统"},{"phrase":"extracorporeal membrane oxygenation","zh":"体外膜肺氧合（ECMO）"},{"phrase":"oxygenation capacity","zh":"充氧能力"}],"forms":[{"label":"不可数用法","form":"oxygenation（指过程时一般不加 -s）"},{"label":"动词形式","form":"oxygenate（给……充氧；使氧合）"},{"label":"形容词形式","form":"oxygenated（充氧的；氧合的）"},{"label":"施动名词","form":"oxygenator（氧合器；充氧装置）"},{"label":"反向过程","form":"deoxygenation（脱氧）"}],"derivatives":[{"word":"oxygenate","pos":"v.","zh":"使氧合；给……充氧"},{"word":"oxygenated","pos":"adj.","zh":"充氧的；含氧的"},{"word":"oxygenator","pos":"n.","zh":"氧合器；充氧机"},{"word":"oxygen","pos":"n.","zh":"氧；氧气"},{"word":"deoxygenation","pos":"n.","zh":"脱氧；缺氧过程"},{"word":"oxygenic","pos":"adj.","zh":"产氧的；含氧的"}],"senses":[{"no":"01","title":"Adding oxygen in general","titleCN":"一般加氧：把氧引入某种介质","definition":"the general process of bringing oxygen into a liquid, a gas mixture or a material","definitionCN":"把氧引入液体、气体混合物或材料的一般过程","example":"Oxygenation of the tank began as soon as the aerator switched on.","exampleCN":"增氧机一开，水槽的充氧就开始了。","why":"The noun simply names the act behind the verb oxygenate: oxygen is made to enter something that lacked it.","whyCN":"这个名词就是动词 oxygenate 所表动作的名称化：让氧进入原本缺氧的东西。"},{"no":"02","title":"Blood oxygenation","titleCN":"血液氧合：红细胞装载氧的过程","definition":"in medicine, the loading of oxygen onto haemoglobin as blood passes through the lungs or an oxygenator","definitionCN":"医学中指血液经过肺或氧合器时，血红蛋白装载氧的过程","example":"Blood oxygenation improved within a minute of starting the mask.","exampleCN":"戴上氧气面罩一分钟内，血液氧合就改善了。","why":"Clinical usage measures the result as a percentage, so the process word becomes a number on a monitor.","whyCN":"临床把这个过程的结果量成百分比，于是过程名词变成了监护仪上的一个数字。"},{"no":"03","title":"Aeration of water","titleCN":"水体增氧：避免缺氧与死鱼","definition":"the artificial or natural addition of oxygen to ponds, rivers and lakes so that aquatic life can breathe","definitionCN":"向池塘、河流与湖泊人工或自然地补充氧，使水生生物得以呼吸","example":"Emergency oxygenation saved the fish when the algae bloom collapsed.","exampleCN":"藻华崩溃时，紧急增氧救下了鱼群。","why":"Water holds little gas, so managers speak of oxygenation rather than of oxygen itself when they describe the remedy.","whyCN":"水中含气量低，因此管理者谈到补救措施时说的是「增氧过程」，而不是氧本身。"},{"no":"04","title":"Wastewater treatment","titleCN":"污水处理：给活性污泥供氧","definition":"the deliberate supply of oxygen to microbial tanks so that aerobic bacteria can break down waste","definitionCN":"向微生物池有意供氧，好让好氧细菌分解废物","example":"The plant's oxygenation tanks keep the microbes alive through the night.","exampleCN":"污水厂的曝气池整夜维持微生物存活。","why":"Engineering borrows the medical word because the goal is the same: keep living cells supplied with oxygen.","whyCN":"工程借用医学词，因为目标相同：让活细胞持续得到氧。"},{"no":"05","title":"Oxygenation vs oxidation","titleCN":"加氧与氧化的区别：插入氧原子不等于失电子","definition":"in organic chemistry, the introduction of oxygen atoms into a molecule, distinguished from oxidation as loss of electrons","definitionCN":"有机化学中指把氧原子引入分子，与以失电子定义的氧化相区别","example":"Enzyme-catalysed oxygenation added a hydroxyl group without changing the oxidation state.","exampleCN":"酶催化的加氧反应加上了一个羟基，却没有改变氧化态。","why":"Chemists needed a narrow word for inserting oxygen, because oxidation had already been defined by electron transfer.","whyCN":"化学家需要一个窄义的词专指「插入氧」，因为 oxidation 早已按电子转移来定义。"},{"no":"06","title":"Letting wine breathe","titleCN":"醒酒：让酒液与空气接触","definition":"in wine tasting, the exposure of wine to air so that tannins soften and aromas open up","definitionCN":"品酒中指让葡萄酒接触空气，使单宁柔化、香气展开","example":"A hour of oxygenation softened the young cabernet noticeably.","exampleCN":"一小时的醒酒让这款年轻赤霞珠明显柔和了。","why":"The same process word is used at the table, where the aim is flavour rather than breathing.","whyCN":"同一个过程词也用在餐桌上，那里追求的是风味而不是呼吸。"},{"no":"07","title":"Hyperbaric oxygenation","titleCN":"高压氧疗：在高压舱内提高溶解氧","definition":"in medicine, the delivery of oxygen under raised pressure so that far more of it dissolves directly in plasma","definitionCN":"医学中指在加压条件下供氧，使更多氧直接溶于血浆","example":"Hyperbaric oxygenation treats divers with decompression sickness.","exampleCN":"高压氧治疗用于患减压病的潜水员。","why":"Pressure changes the physics, so the process gets a distinct name and a distinct chamber.","whyCN":"压力改变了物理条件，因此这一过程有了专门的名称与专门的舱室。"},{"no":"08","title":"Keeping deep water alive","titleCN":"海洋供氧：阻止深层水变成无氧区","definition":"in oceanography, the supply of oxygen to deeper water that keeps it from turning anoxic","definitionCN":"海洋学中指向较深层水体供氧，使其不至于变成无氧状态","example":"Weakening oxygenation turns shelf water into an oxygen minimum zone.","exampleCN":"供氧减弱会把陆架水变成最低含氧区。","why":"Because oxygen is consumed as deep water ages, oceanographers name the resupply as a process of its own.","whyCN":"由于深层水随时间消耗氧，海洋学家把这种补充单独命名为一个过程。"}],"etymology":{"intro":{"en":"Oxygenation is the English action noun built on oxygenate, whose stem is the French coinage oxygene 'acid-former'. The suffix -ation comes from Latin -atio.","cn":"oxygenation 是建立在 oxygenate 之上的英语动作名词，其词干是法语造词 oxygene「成酸者」。后缀 -ation 来自拉丁 -atio。"},"items":[{"era":"GREEK ROOT","en":"The stem rests on Greek oxys 'sharp, acid' and -genes 'producer', the same pieces Lavoisier used when he named oxygene in 1777.","cn":"词干建立在希腊 oxys「尖锐的、酸的」与 -genes「产生者」之上，正是拉瓦锡 1777 年命名 oxygene 时使用的那两块材料。"},{"era":"NEW LATIN OXYGENIUM","en":"Scientific Latin reshaped the French word as oxygenium, giving chemists a Latin noun to conjugate and to build verbs from.","cn":"科学拉丁语把法语词改写为 oxygenium，使化学家有了一个可变格的拉丁名词，并可由它造动词。"},{"era":"FRENCH VERB","en":"French oxygéner 'to oxygenate' appears in late eighteenth-century chemical writing, formed by adding the verb ending -er to oxygène.","cn":"法语动词 oxygéner「加氧」出现在 18 世纪末的化学文献中，由 oxygène 加动词词尾 -er 构成。"},{"era":"ENGLISH VERB","en":"English oxygenate is recorded from the late eighteenth century, as the new chemistry spread through British laboratories and lectures. The exact first date is uncertain.","cn":"英语 oxygenate 在 18 世纪末已有记录，随着新化学在英国实验室与讲座中传播。来源不确定（仅首见年代存疑）：最早确切年代存疑。"},{"era":"LATIN -ATIO","en":"The suffix -ation descends from Latin -atio, -ationis, the ending of action nouns such as radiatio and nutritio, so oxygenation names the action as a thing.","cn":"后缀 -ation 出自拉丁 -atio、-ationis，是 radiatio、nutritio 这类动作名词的词尾，因此 oxygenation 把动作命名为一个事物。"},{"era":"MEDICAL EXTENSION","en":"Twentieth-century medicine extended the word to blood and to machines, producing terms such as extracorporeal membrane oxygenation in the 1970s.","cn":"20 世纪的医学把这个词扩展到血液与机器，1970 年代产生了 extracorporeal membrane oxygenation（体外膜肺氧合）这类术语。"}]},"similar":{"note":{"en":"The first group holds chemically adjacent words that are constantly swapped by mistake; the second holds processes that also move a gas into a liquid but for different reasons.","cn":"第一组是化学上相邻、常被误换的词；第二组是同样把气体送入液体、但目的不同的过程。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"oxidation","ipa":"/ˌɒksɪˈdeɪʃn/","tag":"electron loss, not oxygen entry","definition":"The loss of electrons by a substance. It often involves oxygen, but it is defined by electron transfer, so it is not the same as adding oxygen atoms.","definitionCN":"物质失去电子的过程。它常涉及氧，但定义依据是电子转移，因此与「加入氧原子」并不等同。"},{"word":"oxygenate","ipa":"/ˈɒksɪdʒəneɪt/","tag":"the verb","definition":"The verb meaning to add oxygen to something. Oxygenation is the noun built from it, so one names the act and the other the act as a thing.","definitionCN":"意为给某物加氧的动词。oxygenation 是由它构成的名词，一个表动作，一个把动作当作事物。"},{"word":"oxygenated","ipa":"/ˈɒksɪdʒəneɪtɪd/","tag":"the resulting state","definition":"The adjective describing something that has received oxygen, such as oxygenated blood. It names a state, not an ongoing process.","definitionCN":"描述已获得氧的事物的形容词，如含氧血。它命名状态，而不是正在进行的过程。"}]},{"heading":"NEAR MEANING","entries":[{"word":"aeration","ipa":"/eəˈreɪʃn/","tag":"air, not pure oxygen","definition":"The mixing of air into a liquid or a solid. Air is mostly nitrogen, so aeration adds less oxygen than oxygenation does.","definitionCN":"把空气混入液体或固体。空气主要是氮，因此曝气加入的氧少于充氧。"},{"word":"perfusion","ipa":"/pəˈfjuːʒn/","tag":"flow, not gas exchange","definition":"The passage of blood through tissue. Good perfusion is needed for oxygenation, but it names the flow rather than the loading of oxygen.","definitionCN":"血液流经组织的过程。良好的灌注是氧合的前提，但它命名的是血流而不是氧的装载。"},{"word":"ventilation","ipa":"/ˌventɪˈleɪʃn/","tag":"air movement, not oxygen loading","definition":"The movement of air in and out of the lungs or a room. Ventilation delivers gas to the lung; oxygenation is what the blood does with it.","definitionCN":"空气进出肺或房间的运动。通气把气体送到肺泡，氧合则是血液对它的利用。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"oxygen + -ate + -ion: the act of putting oxygen in, turned into a noun.","cn":"oxygen + -ate + -ion：把氧放进去的动作，再变成名词。"},{"en":"The family runs oxygenate, oxygenated, oxygenator, deoxygenation and oxygenic.","cn":"同族词包括 oxygenate、oxygenated、oxygenator、deoxygenation、oxygenic。"},{"en":"Fixed phrases mark the fields: blood oxygenation, tissue oxygenation, oxygenation system.","cn":"固定搭配标出领域：血液氧合、组织氧合、充氧系统。"},{"en":"Doctors separate ventilation (air in) from oxygenation (oxygen into blood).","cn":"医生把通气（空气进入）与氧合（氧进入血液）分开说。"},{"en":"Wastewater plants oxygenate to keep aerobic bacteria alive.","cn":"污水厂充氧是为了让好氧细菌存活。"}],"abstract":[{"en":"Picture dark blood entering a clear tube and leaving it bright red.","cn":"想象暗红的血液进入透明管路，出来时已变成鲜红。"},{"en":"Picture a pond at dawn with a fountain throwing water into the air so fish stop gasping.","cn":"想象黎明时分的池塘，喷泉把水抛向空中，鱼不再浮头喘气。"},{"en":"Picture a glass of young red wine darkening and softening as it sits open on the table.","cn":"想象一杯年轻红酒在桌上敞着，颜色渐深、口感渐柔。"}]},"examples":[{"en":"Tissue oxygenation depends on both breathing and blood flow.","cn":"组织氧合同时取决于呼吸与血流。"},{"en":"The artificial oxygenation of the lake cost more than the fish it saved.","cn":"人工增氧的花费超过了它所救下的鱼。"},{"en":"Enzyme-controlled oxygenation is a common step in drug synthesis.","cn":"酶控制的加氧反应是药物合成中的常见步骤。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「oxygen（氧）+ ation（过程）」——把氧送进去的过程 → oxygenation 氧合、充氧","word":"oxygenation"},"root":"希腊 oxys「酸的」+ -genes「产生者」→ 法语 oxygene → 英语 oxygen + 拉丁 -atio → oxygenation。","sensesIntro":{"en":"Eight senses follow one act of loading oxygen: into a tank, into blood, into wastewater, into a molecule, into wine, and finally into deep ocean water.","cn":"八个义项都围绕同一个「装氧」动作：装进水槽、血液、污水、分子、葡萄酒，最后装进深海。"},"semanticMap":{"core":{"en":"CORE IMAGE: dark blood brightening as bubbles pass through the line.","cn":"核心意象：气泡流经管路，暗红的血变亮。"},"chain":["ADD OXYGEN","LOAD THE BLOOD","AERATE WATER","FEED MICROBES","INSERT AN ATOM","OPEN THE AROMA"],"branches":[{"senses":"S1","en":"PLAIN ADDITION: the bare process of making oxygen enter something.","cn":"单纯加入：让氧进入某物的最基本过程。"},{"senses":"S2 · S7","en":"MEDICINE: blood and pressure turn the process into a measurable clinical value.","cn":"医学：血液与压力把这个过程变成可测量的临床数值。"},{"senses":"S3 · S4 · S8","en":"WATER: ponds, sewage tanks and oceans all need the same resupply to stay alive.","cn":"水环境：池塘、污水池与海洋都需要同样的补给才能维持生命。"},{"senses":"S5","en":"MOLECULE: chemists narrow the word to oxygen atoms inserted into a structure.","cn":"分子：化学家把词义收窄为「插入结构中的氧原子」。"},{"senses":"S6","en":"PLEASURE: at the table the same process is used for taste, not for survival.","cn":"风味：在餐桌上，同一过程服务于味道而非生存。"}]},"affixes":{"intro":{"en":"Oxygenation is a three-piece construction: a Greek-derived stem for the gas, a verb ending, and a Latin action-noun ending.","cn":"oxygenation 由三块构成：源自希腊语的气体词干、动词词尾，以及拉丁动作名词词尾。"},"latinIntro":{"en":"New Latin oxygenium and oxygenare gave the verb its shape, while Latin -atio supplied the noun ending shared by radiation, nutrition and oxidation.","cn":"新拉丁语 oxygenium 与 oxygenare 给了动词词形，拉丁 -atio 则提供了与 radiation、nutrition、oxidation 共用的名词词尾。"},"items":[{"word":"oxygenation","structure":"oxygen + -ate + -ion","meaning":"the act or result of adding oxygen","meaningCN":"加氧的动作或其结果","example":"Oxygenation of the blood was monitored continuously.","exampleCN":"血液氧合被持续监测。"},{"word":"oxygenate","structure":"oxygen + -ate (verb)","meaning":"to treat with oxygen","meaningCN":"用氧处理；给……加氧","example":"The device oxygenates the blood outside the body.","exampleCN":"该装置在体外给血液加氧。"},{"word":"oxygenated","structure":"oxygenate + -ed (past participle)","meaning":"having received oxygen","meaningCN":"已获得氧的","example":"Oxygenated blood returns to the left side of the heart.","exampleCN":"含氧血回到心脏左侧。"},{"word":"oxygenator","structure":"oxygenate + -or (agent noun)","meaning":"a machine that adds oxygen to blood","meaningCN":"给血液加氧的机器","example":"The oxygenator ran for six hours during surgery.","exampleCN":"手术期间氧合器运行了六个小时。"},{"word":"deoxygenation","structure":"de- (remove) + oxygenation","meaning":"the removal or loss of oxygen","meaningCN":"氧的去除或流失","example":"Deoxygenation of the deep water followed the bloom.","exampleCN":"藻华之后，深层水出现脱氧。"},{"word":"oxygen","structure":"French oxygene, from Greek oxys + -genes","meaning":"the gas itself","meaningCN":"气体本身","example":"Oxygen enters the lungs with each breath.","exampleCN":"每次呼吸都有氧进入肺部。"},{"word":"oxygenic","structure":"oxygen + -ic (adjective)","meaning":"producing oxygen","meaningCN":"产生氧的","example":"Oxygenic algae changed the ancient atmosphere.","exampleCN":"产氧藻类改变了远古大气。"},{"word":"aeration","structure":"Greek aer (air) + -ation","meaning":"mixing air into a liquid","meaningCN":"把空气混入液体","example":"Aeration of the soil helps roots breathe.","exampleCN":"土壤通气有助于根系呼吸。"}],"latinEntries":[{"word":"oxygenium","structure":"oxygenium (n., New Latin, second declension)","meaning":"oxygen","meaningCN":"氧"},{"word":"oxygenare","structure":"oxygenare (verb, New Latin, first conjugation)","meaning":"to combine with oxygen","meaningCN":"使与氧结合"},{"word":"-atio","structure":"-atio, -ationis (f., third declension)","meaning":"action-noun suffix","meaningCN":"动作名词后缀"}]}},{"word":"nitrogen","ipa_uk":"/ˈnaɪtrədʒən/","ipa_us":"/ˈnaɪtrədʒən/","definition_zh":"氮；氮气","definition_en":"the chemical element of atomic number 7, a colourless, odourless gas that makes up about four fifths of the air","core_image":"一只无色气球悬在空气中，旁边一株豆科植物的根瘤被剖开露出粉红色内部","scene":"The farmer rotated legumes to add nitrogen to the soil without buying fertilizer.","sceneCN":"这里 nitrogen 指「土壤中的氮素养分」（第 3 个义项：氮肥与固氮）；豆科植物的根瘤菌把空气中的氮固定进土壤，农户因此不必买化肥。图中可辨识物件：豆科植株、根瘤剖面、土壤层、轮作示意牌。","pos":[{"tag":"n.","zh":"氮；氮气（不可数；化学式 N₂）"}],"collocations":[{"phrase":"nitrogen fixation","zh":"固氮作用"},{"phrase":"nitrogen fertilizer","zh":"氮肥"},{"phrase":"liquid nitrogen","zh":"液氮"},{"phrase":"nitrogen cycle","zh":"氮循环"},{"phrase":"nitrogen oxides","zh":"氮氧化物"},{"phrase":"nitrogen content","zh":"氮含量"}],"forms":[{"label":"不可数用法","form":"nitrogen（指元素或气体时不加 -s）"},{"label":"化学式","form":"N₂（双原子分子）"},{"label":"形容词形式","form":"nitrogenous（含氮的）"},{"label":"相关动词","form":"nitrify（硝化；使变成亚硝酸盐或硝酸盐）"},{"label":"化合物名词","form":"nitrate（硝酸盐）；nitrite（亚硝酸盐）"}],"derivatives":[{"word":"nitrogenous","pos":"adj.","zh":"含氮的"},{"word":"nitrate","pos":"n.","zh":"硝酸盐；硝酸根"},{"word":"nitrite","pos":"n.","zh":"亚硝酸盐"},{"word":"nitrify","pos":"v.","zh":"硝化；使转化为硝酸盐"},{"word":"denitrify","pos":"v.","zh":"反硝化；使氮逸出"},{"word":"nitrogenase","pos":"n.","zh":"固氮酶"}],"senses":[{"no":"01","title":"The element","titleCN":"氮元素：原子序数 7","definition":"the chemical element with atomic number 7, a non-metal that forms strong triple bonds in its diatomic form","definitionCN":"原子序数为 7 的元素，非金属，其双原子形式含牢固的三键","example":"Nitrogen has seven protons and typically seven neutrons.","exampleCN":"氮有七个质子，通常也有七个中子。","why":"The name labels an element, not just the air gas, so it also applies to nitrogen atoms inside proteins and fertilisers.","whyCN":"这个名字标的是元素而非仅仅是空气里的气体，因此蛋白质与肥料中的氮原子同样适用。"},{"no":"02","title":"The bulk gas of the air","titleCN":"大气主体：约占空气五分之四的惰性气体","definition":"molecular N2, the inert gas that dilutes oxygen and fills most of the atmosphere","definitionCN":"双原子分子 N₂，稀释氧、占据大气绝大部分的惰性气体","example":"Crisp packets are filled with nitrogen to stop the contents going stale.","exampleCN":"薯片包装充入氮气，防止内容物变陈。","why":"Because the triple bond makes N2 unreactive, industry values it precisely for doing nothing.","whyCN":"由于三键使 N₂ 极不活泼，工业看重的恰恰是它「什么都不做」。"},{"no":"03","title":"Soil fertility and fixation","titleCN":"土壤氮素：固氮、施肥与轮作","definition":"the nitrogen available to plants in soil, supplied by fertiliser or by bacteria that fix atmospheric gas","definitionCN":"土壤中可供植物利用的氮，来自肥料或固氮细菌","example":"Legumes add nitrogen to the soil through their root nodules.","exampleCN":"豆科植物通过根瘤给土壤补充氮。","why":"Plants cannot use N2 directly, so agricultural usage names the usable forms, not the gas overhead.","whyCN":"植物无法直接利用 N₂，因此农业用法指的是可利用的形态，而不是头顶上的气体。"},{"no":"04","title":"Inside proteins","titleCN":"蛋白质中的氮：氨基酸的基本成分","definition":"the nitrogen bound in amino acids, and therefore in every protein and in DNA","definitionCN":"结合在氨基酸中、从而存在于每种蛋白质与 DNA 中的氮","example":"Every amino acid carries at least one nitrogen atom.","exampleCN":"每种氨基酸都至少带有一个氮原子。","why":"Life's chemistry is built on nitrogen-containing groups, so the element doubles as a marker of protein content.","whyCN":"生命的化学建立在含氮基团之上，因此这个元素也成了蛋白质含量的标记。"},{"no":"05","title":"Liquid nitrogen","titleCN":"液氮：极低温的冷却与保存介质","definition":"nitrogen cooled to about minus 196 degrees Celsius, used for freezing, storage and cooling","definitionCN":"冷却到约零下 196 摄氏度的氮，用于冷冻、保存与降温","example":"Samples are stored in liquid nitrogen at the tissue bank.","exampleCN":"组织库中的样本保存在液氮里。","why":"The boiling point of the gas is so low that its liquid becomes a standard laboratory coolant.","whyCN":"这种气体的沸点极低，其液态因此成了实验室的标准冷却剂。"},{"no":"06","title":"Nitrogen oxides and smog","titleCN":"氮氧化物：交通排放与光化学烟雾","definition":"the family of nitrogen-oxygen compounds, especially NO and NO2, formed in hot engines and driving photochemical smog","definitionCN":"氮与氧的化合物一族，尤其是高温引擎生成的 NO 与 NO₂，会促成光化学烟雾","example":"Nitrogen oxides from traffic feed the smog over the valley.","exampleCN":"交通排放的氮氧化物助长了谷地上空的光化学烟雾。","why":"Pollution control needed a short collective label, so the element name stands in for its troublesome compounds.","whyCN":"污染控制需要一个简短的统称，于是元素名被用来指代它那些麻烦的化合物。"},{"no":"07","title":"The nitrogen cycle","titleCN":"氮循环：在空气、土壤与生物之间流转","definition":"the circulation of nitrogen among the atmosphere, soil, water and living things through fixation, assimilation and denitrification","definitionCN":"氮经固氮、同化与反硝化在大气、土壤、水体与生物之间循环","example":"The nitrogen cycle moves the element between air, soil and living things.","exampleCN":"氮循环让这个元素在空气、土壤与生物之间流转。","why":"Because the element changes chemical form at every step, the cycle is named after the element rather than any one compound.","whyCN":"由于这个元素在每一步都改变化学形态，循环便以元素而非某一种化合物命名。"},{"no":"08","title":"The nitre-former in the name","titleCN":"名字里的「硝石产生者」","definition":"the sense recorded by the name itself: Chaptal named the gas because it was found in nitre, that is, saltpetre","definitionCN":"名字本身记录的义项：夏普塔尔因这种气体存在于硝石（硝酸钾）中而为它命名","example":"The name nitrogen still says 'nitre-former', though the gas itself is inert.","exampleCN":"nitrogen 这个名字至今仍表示「硝石产生者」，尽管这种气体本身是惰性的。","why":"The French coinage nitrogene described where the element came from chemically, and English simply transliterated the claim.","whyCN":"法语造词 nitrogene 描述的是该元素在化学上的来源，英语只是把这个说法音译过来。"}],"etymology":{"intro":{"en":"Nitrogen is a French scientific coinage of 1790, built from Greek nitron 'soda, nitre' and -genes 'producer'. Its first element was already ambiguous in ancient Greek.","cn":"nitrogen 是 1790 年的法语科学造词，由希腊 nitron「碱、硝石」与 -genes「产生者」构成。它的第一块在古代希腊语中就已含混。"},"items":[{"era":"GREEK NITRON","en":"Greek nitron named native soda, a mineral salt used in cleaning, not saltpetre. Latin nitrum later shifted the word toward saltpetre, and chemistry inherited the confusion.","cn":"希腊 nitron 指天然碱，一种用于洗涤的矿物盐，而非硝石。拉丁 nitrum 后来把这个词引向硝石，化学继承了这一混淆。"},{"era":"GREEK -GENES","en":"The suffix -genes 'born of, producing' comes from the root gen- 'to be born'. It marks the element as something that generates a named substance.","cn":"后缀 -genes「由……所生、产生」出自词根 gen-「出生」。它把这个元素标记为能生成某种特定物质的东西。"},{"era":"FRENCH NITROGENE","en":"In 1790 the French chemist Chaptal coined nitrogene, because the gas was obtained from nitre and seemed to be the nitre-forming principle. The claim was later revised.","cn":"1790 年法国化学家夏普塔尔造出 nitrogene，因为这种气体可从硝石取得，似乎是成硝石的本原。这一说法后来被修正。"},{"era":"ENGLISH ARRIVAL","en":"English nitrogen appears in the 1790s, transliterating the French term as the new chemistry spread. Before that the gas was called 'dephlogisticated air' or 'mephitic air'.","cn":"英语 nitrogen 在 1790 年代出现，随新化学的传播音译了法语术语。在此以前，这种气体被称作「脱燃素空气」或「毒气」。"},{"era":"MODERN CHEMISTRY","en":"Once the element rather than the compound became the unit of chemistry, nitrogen named element 7 and its compounds were renamed as nitrides, nitrates and oxides.","cn":"当化学的单位从化合物转为元素后，nitrogen 成为 7 号元素的名称，其化合物则改称氮化物、硝酸盐与氧化物。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertainty: the exact first English citation is uncertain, and whether Chaptal or a colleague first suggested the form nitrogene is debated; Greek nitron itself has no agreed deeper origin.","cn":"来源不确定：英语首见的确切书证年代存疑，nitrogene 这一形式由夏普塔尔还是其同僚最先提出仍有争议；希腊 nitron 本身的更深来源也无定论。"}]},"similar":{"note":{"en":"The first group holds words sharing the nitre root whose chemistry differs sharply; the second holds other atmospheric gases that are often confused with nitrogen.","cn":"第一组是同出「硝石」词根但化学性质差别很大的词；第二组是常与氮混淆的其他大气气体。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"nitrate","ipa":"/ˈnaɪtreɪt/","tag":"a salt, not the element","definition":"A salt or ester of nitric acid, containing the NO3 group, such as potassium nitrate in fertiliser. Nitrogen is the element; nitrate is one of its compounds.","definitionCN":"硝酸的盐或酯，含 NO₃ 基团，如肥料中的硝酸钾。nitrogen 是元素，nitrate 是它的化合物之一。"},{"word":"nitrite","ipa":"/ˈnaɪtraɪt/","tag":"one less oxygen","definition":"A salt containing the NO2 group, used in cured meat and formed in soil as an intermediate step of nitrification.","definitionCN":"含 NO₂ 基团的盐，用于腌肉，也在土壤中作为硝化过程的中间产物生成。"},{"word":"nitrogenous","ipa":"/naɪˈtrɒdʒənəs/","tag":"the adjective","definition":"The adjective meaning 'containing nitrogen', as in nitrogenous waste. It describes a material, not the element itself.","definitionCN":"意为「含氮的」的形容词，如含氮废物。它描述材料，而不是元素本身。"}]},{"heading":"NEAR MEANING","entries":[{"word":"oxygen","ipa":"/ˈɒksɪdʒən/","tag":"the reactive fifth","definition":"The gas that makes up about a fifth of the air and supports combustion and respiration. Nitrogen dilutes it and does not burn.","definitionCN":"约占空气五分之一、支持燃烧与呼吸的气体。氮稀释它，且自身不燃烧。"},{"word":"argon","ipa":"/ˈɑːɡɒn/","tag":"the truly inert gas","definition":"A noble gas making up about one percent of the air, even less reactive than nitrogen. It is used where an absolutely inert atmosphere is needed.","definitionCN":"约占空气百分之一的稀有气体，比氮更不活泼。需要绝对惰性气氛时就用它。"},{"word":"ammonia","ipa":"/əˈməʊniə/","tag":"a compound, not the element","definition":"NH3, a pungent gas made industrially from nitrogen and hydrogen. It is the form in which nitrogen is turned into fertiliser.","definitionCN":"NH₃，工业上用氮与氢合成的刺激性气体。它正是氮被转化为肥料时所采取的形态。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Greek nitron 'nitre' + -genes 'producer': the nitre-former, a name kept from a chemical claim.","cn":"希腊 nitron「硝石」+ -genes「产生者」：成硝石者，一个源自化学主张的名字。"},{"en":"The family runs nitrogenous, nitrate, nitrite, nitrify, denitrify and nitrogenase.","cn":"同族词包括 nitrogenous、nitrate、nitrite、nitrify、denitrify、nitrogenase。"},{"en":"Fixed phrases mark the fields: nitrogen fixation, nitrogen cycle, liquid nitrogen, nitrogen oxides.","cn":"固定搭配标出领域：固氮、氮循环、液氮、氮氧化物。"},{"en":"Air is about four fifths nitrogen and one fifth oxygen.","cn":"空气约五分之四是氮，五分之一是氧。"},{"en":"Legumes fix nitrogen through root nodules, which is why farmers rotate them.","cn":"豆科植物靠根瘤固氮，这也是农户进行轮作的原因。"}],"abstract":[{"en":"Picture a bag of crisps puffed up with a gas that keeps every chip crisp.","cn":"想象一袋薯片鼓鼓的，里面充着一种让每片都保持酥脆的气体。"},{"en":"Picture a root nodule sliced open, pink inside, quietly turning air into soil fertility.","cn":"想象一颗根瘤被切开，内部粉红，正悄悄把空气变成土壤肥力。"},{"en":"Picture white vapour pouring off liquid nitrogen and rolling across the laboratory bench.","cn":"想象液氮上方涌出白色雾气，沿着实验台漫开。"}]},"examples":[{"en":"Nitrogen makes up roughly seventy-eight percent of the atmosphere.","cn":"氮约占大气的百分之七十八。"},{"en":"Excess nitrogen runoff from farms feeds algal blooms downstream.","cn":"农场过量的氮径流在下游催生藻华。"},{"en":"The welding shop uses nitrogen to purge oxygen from the pipes.","cn":"焊接车间用氮把管道中的氧排净。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「nitro（硝石）+ gen（产生）」——从硝石中得来的元素 → nitrogen 氮","word":"nitrogen"},"root":"希腊 nitron「天然碱、硝石」+ -genes「产生者」→ 法语 nitrogene（1790，夏普塔尔）→ 英语 nitrogen。","sensesIntro":{"en":"Eight senses follow one element from the periodic table through air, soil, protein, coolant, smog and the nitrogen cycle, ending with the naming claim that still sits inside the word.","cn":"八个义项让同一个元素从周期表走进空气、土壤、蛋白质、冷却剂、烟雾与氮循环，最后落在仍留在词里的那个命名主张上。"},"semanticMap":{"core":{"en":"CORE IMAGE: a colourless gas everywhere and a sliced pink root nodule.","cn":"核心意象：无处不在的无色气体，与一颗切开的粉色根瘤。"},"chain":["ELEMENT SEVEN","FILL THE AIR","FEED THE SOIL","BUILD PROTEIN","COOL AND FREEZE","CYCLE AGAIN"],"branches":[{"senses":"S1","en":"THE ATOM: element 7 is defined by seven protons and its triple bond.","cn":"原子：7 号元素由七个质子与三键定义。"},{"senses":"S2","en":"THE BULK GAS: inertness is a property, so packaging and welding value it for what it does not do.","cn":"主体气体：惰性本身即特性，包装与焊接看重的正是它「不做什么」。"},{"senses":"S3 · S7","en":"THE CYCLE: soil fertility and global circulation describe the same element changing form.","cn":"循环：土壤肥力与全球循环描述的是同一元素不断变换形态。"},{"senses":"S4","en":"LIFE: amino acids and DNA make nitrogen a marker of living matter.","cn":"生命：氨基酸与 DNA 使氮成为生命物质的标记。"},{"senses":"S5 · S6 · S8","en":"USES AND CLAIMS: liquid coolant, polluting oxides and the nitre story all hang off the same name.","cn":"用途与说法：液氮冷却、污染性氧化物与硝石故事，都挂在同一个名字上。"}]},"affixes":{"intro":{"en":"Nitrogen is a scientific compound of a Greek noun for nitre and a Greek suffix for producing, reshaped in French and then borrowed into English.","cn":"nitrogen 是科学造词：希腊语表示硝石的名词加希腊语表示产生的后缀，经法语改写后借入英语。"},"latinIntro":{"en":"Latin nitrum carried the nitre sense, and New Latin nitrogenium fixed the element name so that nitrate, nitrite and nitride could be built from it.","cn":"拉丁 nitrum 承载了「硝石」义，新拉丁语 nitrogenium 固定了元素名，使 nitrate、nitrite 与 nitride 得以由它构成。"},"items":[{"word":"nitrogen","structure":"Greek nitron + -genes (nitre-producing)","meaning":"element 7 and its diatomic gas","meaningCN":"7 号元素及其双原子气体","example":"Nitrogen is liquefied for storage.","exampleCN":"氮被液化以便储存。"},{"word":"nitrogenous","structure":"nitrogen + -ous (full of)","meaning":"containing nitrogen","meaningCN":"含氮的","example":"Nitrogenous waste builds up in the tank.","exampleCN":"含氮废物在水箱中累积。"},{"word":"nitrate","structure":"nitre + -ate (salt suffix)","meaning":"a salt of nitric acid","meaningCN":"硝酸的盐","example":"Nitrate levels in the well are too high.","exampleCN":"井水中的硝酸盐含量过高。"},{"word":"nitrite","structure":"nitre + -ite (lower oxidation suffix)","meaning":"a salt of nitrous acid","meaningCN":"亚硝酸的盐","example":"Nitrite is used to cure ham.","exampleCN":"亚硝酸盐用于腌制火腿。"},{"word":"nitrify","structure":"nitre + -ify (to make)","meaning":"to convert into nitrate by bacterial action","meaningCN":"经细菌作用转化为硝酸盐","example":"Bacteria nitrify the ammonia in the soil.","exampleCN":"细菌把土壤中的氨硝化。"},{"word":"denitrify","structure":"de- (remove) + nitrify","meaning":"to convert nitrate back into nitrogen gas","meaningCN":"把硝酸盐还原为氮气","example":"Wet soils denitrify quickly.","exampleCN":"潮湿土壤会迅速反硝化。"},{"word":"nitrogenase","structure":"nitrogen + -ase (enzyme suffix)","meaning":"the enzyme that fixes atmospheric nitrogen","meaningCN":"固定大气氮的酶","example":"Nitrogenase works only without oxygen.","exampleCN":"固氮酶只能在无氧条件下工作。"},{"word":"nitride","structure":"nitre + -ide (compound suffix)","meaning":"a compound of nitrogen with a metal","meaningCN":"氮与金属形成的化合物","example":"Silicon nitride is extremely hard.","exampleCN":"氮化硅极其坚硬。"},{"word":"nitric","structure":"nitre + -ic (adjective)","meaning":"relating to the higher oxide of nitrogen","meaningCN":"与高价态氮氧化物有关的","example":"Nitric acid dissolves copper.","exampleCN":"硝酸能溶解铜。"}],"latinEntries":[{"word":"nitrum","structure":"nitrum, nitri (n., second declension; from Greek nitron)","meaning":"native soda; later saltpetre","meaningCN":"天然碱；后指硝石"},{"word":"nitrogenium","structure":"nitrogenium (n., New Latin, second declension)","meaning":"nitrogen","meaningCN":"氮"},{"word":"-genes","structure":"-genes (Greek combining form, from gen-)","meaning":"born of, producing","meaningCN":"由……所生、产生"}]}},{"word":"nitrogenous","ipa_uk":"/naɪˈtrɒdʒənəs/","ipa_us":"/naɪˈtrɑːdʒənəs/","definition_zh":"含氮的；氮的","definition_en":"containing nitrogen, or relating to nitrogen","core_image":"一摊白色尿素晶体旁立着一支标着 N 的试管，气体正沿导管逸出","scene":"Fish excrete nitrogenous waste as ammonia through their gills.","sceneCN":"这里 nitrogenous 指「含氮的」（第 2 个义项：含氮排泄物）；鱼把蛋白质代谢产生的氮以氨的形式经鳃排出。图中可辨识物件：鱼鳃、氨逸出示意、水槽、检测试纸。","pos":[{"tag":"adj.","zh":"含氮的；氮的（多作定语，如 nitrogenous waste、nitrogenous base）"}],"collocations":[{"phrase":"nitrogenous waste","zh":"含氮废物"},{"phrase":"nitrogenous fertilizer","zh":"氮肥"},{"phrase":"nitrogenous compounds","zh":"含氮化合物"},{"phrase":"nitrogenous bases","zh":"含氮碱基"},{"phrase":"nitrogenous matter","zh":"含氮物质"},{"phrase":"nitrogenous pollution","zh":"氮污染"}],"forms":[{"label":"比较级","form":"more nitrogenous（指含氮比例更高时使用）"},{"label":"最高级","form":"most nitrogenous"},{"label":"名词形式","form":"nitrogen（氮）"},{"label":"名词化表达","form":"nitrogen content（含氮量，代替罕见的 nitrogenousness）"},{"label":"作定语","form":"nitrogenous + 名词（如 nitrogenous base、nitrogenous waste）"}],"derivatives":[{"word":"nitrogen","pos":"n.","zh":"氮；氮气"},{"word":"nitrate","pos":"n.","zh":"硝酸盐"},{"word":"nitrite","pos":"n.","zh":"亚硝酸盐"},{"word":"nitrify","pos":"v.","zh":"硝化"},{"word":"denitrify","pos":"v.","zh":"反硝化"},{"word":"nitrogenase","pos":"n.","zh":"固氮酶"}],"senses":[{"no":"01","title":"Containing nitrogen","titleCN":"含氮：成分中含有氮元素","definition":"containing nitrogen as a constituent, used of compounds, mixtures and materials","definitionCN":"作为成分含有氮，用于化合物、混合物与材料","example":"Nitrogenous compounds such as amines often smell of fish.","exampleCN":"胺类等含氮化合物常有鱼腥味。","why":"The suffix -ous turns the element name into 'full of', the plainest way Latin-derived English says a material contains something.","whyCN":"后缀 -ous 把元素名变成「充满……」的意思，这是拉丁来源的英语表达「某材料含有某物」最朴素的方式。"},{"no":"02","title":"Nitrogenous waste in excretion","titleCN":"含氮废物：蛋白质代谢的排出物","definition":"the nitrogen-rich end products of protein breakdown, excreted as ammonia, urea or uric acid","definitionCN":"蛋白质分解产生的高含氮终产物，以氨、尿素或尿酸形式排出","example":"Birds excrete nitrogenous waste as a uric acid paste.","exampleCN":"鸟类以尿酸糊状物排出含氮废物。","why":"Physiology groups three very different molecules under one adjective because all three carry the nitrogen that must be disposed of.","whyCN":"生理学把三种很不相同的分子归在同一个形容词下，因为它们都携带必须排出的氮。"},{"no":"03","title":"Nitrogenous fertilizer","titleCN":"氮肥：以氮为主要养分的肥料","definition":"fertiliser whose main nutrient is nitrogen, such as ammonium nitrate or urea","definitionCN":"以氮为主要养分的肥料，如硝酸铵或尿素","example":"Nitrogenous fertilizers drove most of the yield increase in the Green Revolution.","exampleCN":"绿色革命中大部分的增产来自氮肥。","why":"Agriculture describes fertilisers by their limiting nutrient, so the adjective replaces a long phrase such as 'rich in nitrogen'.","whyCN":"农业按限制性养分来描述肥料，因此这个形容词替代了「富含氮」这样的长说法。"},{"no":"04","title":"Nitrogenous bases of DNA","titleCN":"含氮碱基：遗传字母表的四个字母","definition":"in biochemistry, the nitrogen-containing rings adenine, thymine, guanine, cytosine and uracil that spell out genetic information","definitionCN":"生物化学中指腺嘌呤、胸腺嘧啶、鸟嘌呤、胞嘧啶与尿嘧啶这些含氮环，它们拼出遗传信息","example":"The four nitrogenous bases pair in a fixed way along the helix.","exampleCN":"四种含氮碱基沿螺旋以固定方式配对。","why":"The bases are named by what makes them chemically alike, since their nitrogen rings are what stack and pair.","whyCN":"这些碱基按化学上的共同点来命名，因为正是它们的含氮环负责堆叠与配对。"},{"no":"05","title":"Nitrogenous pollution","titleCN":"氮污染：氨、亚硝酸盐与硝酸盐超标","definition":"in water quality, pollution by nitrogen compounds such as ammonia, nitrite and nitrate from sewage or runoff","definitionCN":"水质中指氨、亚硝酸盐、硝酸盐等含氮化合物造成的污染，来源为污水或径流","example":"Nitrogenous pollution from sewage pushed ammonia levels above the limit.","exampleCN":"污水带来的氮污染使氨浓度超过限值。","why":"Monitoring agencies measure several compounds at once, so the adjective serves as a single regulatory label.","whyCN":"监测机构一次测量好几种化合物，因此这个形容词充当统一的监管标签。"},{"no":"06","title":"Nitrogenous food in old chemistry","titleCN":"含氮养分：旧化学对蛋白质类食物的称呼","definition":"in nineteenth-century nutrition science, the protein-rich part of food, contrasted with carbonaceous or fatty matter","definitionCN":"19 世纪营养学中指食物中富含蛋白质的部分，与碳质或脂肪物质相对","example":"Liebig divided foods into nitrogenous and carbonaceous kinds.","exampleCN":"李比希把食物分为含氮类与碳质类。","why":"Early nutritionists could not measure protein directly, so they classified foods by nitrogen content instead.","whyCN":"早期营养学家无法直接测量蛋白质，便按含氮量来给食物分类。"},{"no":"07","title":"Nitrogenous content in analysis","titleCN":"含氮量测定：凯氏定氮等分析方法","definition":"in analytical chemistry, the nitrogen fraction of a sample, measured to estimate protein or fertiliser strength","definitionCN":"分析化学中指样品的含氮部分，用于估算蛋白质或肥料效力","example":"Kjeldahl digestion measures the nitrogenous content of the sample.","exampleCN":"凯氏消解测定样品的含氮量。","why":"Because nitrogen is easy to convert to ammonia and titrate, it became the standard proxy for protein.","whyCN":"由于氮易于转化为氨并滴定，它成了估算蛋白质的标准代理指标。"},{"no":"08","title":"Nitrogenous matter in rock","titleCN":"岩石中的含氮有机质","definition":"in geology, the nitrogen-bearing organic residue preserved in shales and coals","definitionCN":"地质学中指保存在页岩与煤中的含氮有机残余物","example":"The shale preserves nitrogenous organic matter from an ancient sea.","exampleCN":"这片页岩保存着古海洋留下的含氮有机质。","why":"Geochemists use the adjective to separate the organic nitrogen signal from mineral nitrate in the same rock.","whyCN":"地球化学家用这个形容词把有机氮信号与同一岩层中的矿物硝酸盐区分开。"}],"etymology":{"intro":{"en":"Nitrogenous is nitrogen turned into an adjective by the Latin suffix -ous, which marks 'full of' a substance.","cn":"nitrogenous 是 nitrogen 经拉丁后缀 -ous 变成的形容词，该后缀表示「充满」某种物质。"},"items":[{"era":"GREEK NITRON","en":"The base noun comes from Greek nitron, which named native soda; the nitre sense arrived through Latin nitrum. The deeper origin of nitron is not established.","cn":"词根名词出自希腊 nitron，本指天然碱；硝石义经拉丁 nitrum 传入。nitron 更深的来源并无定论。"},{"era":"FRENCH NITROGENE","en":"Chaptal's 1790 coinage nitrogene combined that noun with -genes 'producer', naming the gas after the nitre it came from.","cn":"夏普塔尔 1790 年的造词 nitrogene 把这个名词与 -genes「产生者」结合，按气体所来自的硝石命名。"},{"era":"LATIN -OSUS","en":"The Latin adjective suffix -osus meant 'full of, abounding in', the source of English -ous in such words as porous and dangerous.","cn":"拉丁形容词后缀 -osus 意为「充满、富于」，是英语 porous、dangerous 等词中 -ous 的来源。"},{"era":"ENGLISH ADJECTIVE","en":"English nitrogenous is recorded in the early nineteenth century, as chemists needed an adjective for materials containing the newly named element.","cn":"英语 nitrogenous 在 19 世纪初已有记录，因为化学家需要为含这一新命名元素的材料造一个形容词。"},{"era":"SPREAD OF USES","en":"The adjective spread from chemistry into physiology and agriculture, where nitrogenous waste and nitrogenous fertilizer became fixed phrases.","cn":"这个形容词从化学扩散到生理学与农业，含氮废物与氮肥成了固定搭配。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertainty: the exact first English date of nitrogenous is uncertain, and the deeper origin of Greek nitron remains unresolved.","cn":"来源不确定：nitrogenous 的英语首见确切年代存疑，希腊 nitron 的更深来源仍无定论。"}]},"similar":{"note":{"en":"The first group holds words built on the same nitre stem that name different chemical objects; the second holds adjectives that also say a material contains something.","cn":"第一组是同出「硝石」词干但指不同化学对象的词；第二组是同样表示「材料含有某物」的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"nitrogen","ipa":"/ˈnaɪtrədʒən/","tag":"the noun","definition":"The element itself, or its gas. Nitrogenous is the adjective for things that contain it.","definitionCN":"元素本身或其气体。nitrogenous 是表示「含有它」的形容词。"},{"word":"nitrate","ipa":"/ˈnaɪtreɪt/","tag":"one compound","definition":"The NO3 salt. A nitrogenous material may contain nitrate, but nitrate is one specific compound.","definitionCN":"NO₃ 的盐。含氮材料可能含有硝酸盐，但硝酸盐是某一个具体化合物。"},{"word":"nitric","ipa":"/ˈnaɪtrɪk/","tag":"acid adjective","definition":"Relating to nitric acid or the higher oxides of nitrogen. It names a specific oxidation state, unlike the general nitrogenous.","definitionCN":"与硝酸或高价氮氧化物有关。与泛指的 nitrogenous 不同，它指名一个特定氧化态。"}]},{"heading":"NEAR MEANING","entries":[{"word":"proteinaceous","ipa":"/ˌprəʊtiːˈneɪʃəs/","tag":"protein, not nitrogen","definition":"Made of or resembling protein. Most proteinaceous matter is nitrogenous, but the two adjectives answer different questions.","definitionCN":"由蛋白质构成或类似蛋白质的。多数含蛋白质的物质确实含氮，但两个形容词回答的是不同问题。"},{"word":"ammoniacal","ipa":"/ˌæməˈniækl/","tag":"ammonia smell","definition":"Containing or smelling of ammonia. Ammonia is a nitrogen compound, yet ammoniacal says nothing about the rest of the material.","definitionCN":"含氨或带氨味的。氨是含氮化合物，但 ammoniacal 并不涉及材料的其他成分。"},{"word":"nitrous","ipa":"/ˈnaɪtrəs/","tag":"one oxidation state","definition":"Relating to nitrous acid or the lower oxides of nitrogen, as in nitrous oxide. It is narrower than nitrogenous.","definitionCN":"与亚硝酸或低价氮氧化物有关，如笑气。它比 nitrogenous 窄。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"nitrogen + -ous 'full of': literally 'full of nitrogen'.","cn":"nitrogen + -ous「充满」：字面就是「充满氮的」。"},{"en":"The family runs nitrogen, nitrate, nitrite, nitrify, denitrify and nitrogenase.","cn":"同族词包括 nitrogen、nitrate、nitrite、nitrify、denitrify、nitrogenase。"},{"en":"Fixed phrases mark the fields: nitrogenous waste, nitrogenous base, nitrogenous fertilizer.","cn":"固定搭配标出领域：含氮废物、含氮碱基、氮肥。"},{"en":"Animals get rid of protein nitrogen as ammonia, urea or uric acid, depending on water supply.","cn":"动物按水分条件把蛋白质代谢的氮以氨、尿素或尿酸形式排出。"},{"en":"In DNA, the pairing letters are called the nitrogenous bases.","cn":"在 DNA 里，负责配对的字母叫含氮碱基。"}],"abstract":[{"en":"Picture a fish puffing a faint cloud from its gills and a test strip darkening downstream.","cn":"想象一条鱼从鳃部吐出一缕淡雾，下游的试纸随之变色。"},{"en":"Picture four coloured rings stacked in a ladder, each carrying a nitrogen atom at its core.","cn":"想象四个彩色环叠成梯子，每个环的核心都带一个氮原子。"},{"en":"Picture a sack of white fertiliser prills dissolving into dark soil and turning leaves green.","cn":"想象一袋白色肥料颗粒溶进深色土壤，叶子随之转绿。"}]},"examples":[{"en":"Urea is the main nitrogenous waste in human urine.","cn":"尿素是人体尿液中主要的含氮废物。"},{"en":"The nitrogenous fraction of the fertiliser was measured before spreading.","cn":"施肥前先测定了肥料中的含氮比例。"},{"en":"Nitrogenous bases are often drawn as letters in a genetic code.","cn":"含氮碱基常被画成遗传密码中的字母。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「nitrogen（氮）+ ous（充满）」——充满氮的东西 → nitrogenous 含氮的","word":"nitrogenous"},"root":"希腊 nitron「硝石」+ -genes「产生者」→ nitrogen + 拉丁 -osus「充满」→ nitrogenous。","sensesIntro":{"en":"Eight senses take the adjective from a plain chemical description into waste, fertiliser, DNA, pollution, old nutrition science, analysis and rock.","cn":"八个义项把这个形容词从平白的化学描述带进废物、肥料、DNA、污染、旧营养学、分析化学与岩石。"},"semanticMap":{"core":{"en":"CORE IMAGE: white urea crystals beside a tube marked with the letter N.","cn":"核心意象：白色尿素晶体旁边一支标着 N 的试管。"},"chain":["CONTAINS N","LEAVES THE BODY","FEEDS THE FIELD","SPELLS THE CODE","FOULS THE WATER","HIDES IN ROCK"],"branches":[{"senses":"S1","en":"PLAIN CONTENT: -ous simply says the material carries nitrogen.","cn":"单纯成分：-ous 只是说这种材料带着氮。"},{"senses":"S2 · S7","en":"MEASUREMENT: waste and analytical content both describe nitrogen that can be weighed or titrated.","cn":"计量：废物与分析含量描述的都是可称量、可滴定的氮。"},{"senses":"S3 · S6","en":"FOOD CHAIN: fertiliser feeds crops, and old nutrition science classified foods by the same element.","cn":"食物链：肥料喂养作物，旧营养学也按同一元素给食物分类。"},{"senses":"S4","en":"CODE: the nitrogenous bases make the adjective part of the vocabulary of heredity.","cn":"密码：含氮碱基让这个形容词进入遗传学的词汇。"},{"senses":"S5 · S8","en":"ENVIRONMENT: the same nitrogen becomes pollution in water and a preserved signal in stone.","cn":"环境：同一种氮在水中成为污染，在石头里成为被保存的信号。"}]},"affixes":{"intro":{"en":"Nitrogenous is an element name plus the Latin adjective ending -ous, with the whole stem itself built from Greek pieces.","cn":"nitrogenous 是元素名加拉丁形容词词尾 -ous，而整个词干本身又由希腊语成分构成。"},"latinIntro":{"en":"Latin -osus 'full of' produces English -ous; Latin nitrum supplies the nitre sense that sits inside nitrogen.","cn":"拉丁 -osus「充满」产生英语 -ous；拉丁 nitrum 提供藏在 nitrogen 里的「硝石」义。"},"items":[{"word":"nitrogenous","structure":"nitrogen + -ous (full of)","meaning":"containing nitrogen","meaningCN":"含氮的","example":"Nitrogenous waste must be excreted safely.","exampleCN":"含氮废物必须安全排出。"},{"word":"nitrogen","structure":"Greek nitron + -genes","meaning":"element 7","meaningCN":"7 号元素","example":"Nitrogen is the bulk of the air.","exampleCN":"氮是空气的主体。"},{"word":"nitrate","structure":"nitre + -ate","meaning":"a salt of nitric acid","meaningCN":"硝酸的盐","example":"Nitrate is the form plants prefer.","exampleCN":"硝酸盐是植物偏好的形态。"},{"word":"nitrite","structure":"nitre + -ite","meaning":"a salt of nitrous acid","meaningCN":"亚硝酸的盐","example":"Nitrite levels peak before nitrate forms.","exampleCN":"亚硝酸盐浓度在硝酸盐生成前达到峰值。"},{"word":"nitrify","structure":"nitre + -ify","meaning":"to turn ammonia into nitrate","meaningCN":"把氨转化为硝酸盐","example":"Soil bacteria nitrify the waste.","exampleCN":"土壤细菌把废物硝化。"},{"word":"denitrify","structure":"de- + nitrify","meaning":"to return nitrate to nitrogen gas","meaningCN":"把硝酸盐还原为氮气","example":"Waterlogged fields denitrify.","exampleCN":"积水田块会发生反硝化。"},{"word":"nitrogenase","structure":"nitrogen + -ase","meaning":"the enzyme of nitrogen fixation","meaningCN":"固氮作用的酶","example":"Nitrogenase is destroyed by oxygen.","exampleCN":"固氮酶会被氧破坏。"},{"word":"nitrous","structure":"nitre + -ous (lower oxidation)","meaning":"relating to the lower oxides of nitrogen","meaningCN":"与低价氮氧化物有关的","example":"Nitrous oxide is used as an anaesthetic.","exampleCN":"一氧化二氮被用作麻醉剂。"}],"latinEntries":[{"word":"nitrum","structure":"nitrum, nitri (n., second declension)","meaning":"native soda; saltpetre","meaningCN":"天然碱；硝石"},{"word":"-osus","structure":"-osus, -a, -um (adjective suffix)","meaning":"full of, abounding in","meaningCN":"充满、富于"},{"word":"nitrogenium","structure":"nitrogenium (n., New Latin, second declension)","meaning":"nitrogen","meaningCN":"氮"}]}},{"word":"hydrogen","ipa_uk":"/ˈhaɪdrədʒən/","ipa_us":"/ˈhaɪdrədʒən/","definition_zh":"氢；氢气","definition_en":"the lightest chemical element, atomic number 1, a colourless gas that burns readily and combines with oxygen to form water","core_image":"一只细绳牵着的气球向上飘，旁边一滴水被拆成两个小球与一个更小的球","scene":"The airship was filled with hydrogen because no other gas then available gave so much lift.","sceneCN":"这里 hydrogen 指「用作浮升气体的氢气」（第 7 个义项：比空气轻、可产生浮力的气体）；当时没有别的气体能提供这么大的升力。图中可辨识物件：飞艇气囊、细绳、气压表、氢气瓶。","pos":[{"tag":"n.","zh":"氢；氢气（不可数；化学式 H₂）"}],"collocations":[{"phrase":"hydrogen bond","zh":"氢键"},{"phrase":"hydrogen peroxide","zh":"过氧化氢；双氧水"},{"phrase":"hydrogen fuel","zh":"氢燃料"},{"phrase":"hydrogen ion","zh":"氢离子"},{"phrase":"green hydrogen","zh":"绿氢（用可再生电力制取的氢）"},{"phrase":"hydrogen atom","zh":"氢原子"}],"forms":[{"label":"不可数用法","form":"hydrogen（指元素或气体时不加 -s）"},{"label":"化学式","form":"H₂（双原子分子）"},{"label":"形容词形式","form":"hydrogenous（含氢的，多用于地质学）"},{"label":"动词形式","form":"hydrogenate（使氢化）"},{"label":"化合物名词","form":"hydride（氢化物）；hydroxide（氢氧化物）"}],"derivatives":[{"word":"hydrogenate","pos":"v.","zh":"使氢化；给……加氢"},{"word":"hydrogenation","pos":"n.","zh":"氢化作用"},{"word":"hydrogenous","pos":"adj.","zh":"含氢的"},{"word":"hydride","pos":"n.","zh":"氢化物"},{"word":"hydroxide","pos":"n.","zh":"氢氧化物"},{"word":"hydrocarbon","pos":"n.","zh":"碳氢化合物；烃"}],"senses":[{"no":"01","title":"The lightest element","titleCN":"最轻的元素：原子序数 1","definition":"the chemical element with a single proton, the lightest and most abundant element in the universe","definitionCN":"只含一个质子的元素，是宇宙中最轻、最丰富的元素","example":"Hydrogen has one proton and one electron.","exampleCN":"氢有一个质子和一个电子。","why":"The name labels the element itself, so it applies to hydrogen in stars, in water and in every organic molecule.","whyCN":"这个名字标的是元素本身，因此恒星中、水里与每个有机分子中的氢都适用。"},{"no":"02","title":"The diatomic gas","titleCN":"氢气：可燃的双原子分子","definition":"molecular H2, a colourless, highly flammable gas that burns with a faint blue flame","definitionCN":"双原子分子 H₂，无色、高度易燃，燃烧时呈淡蓝色火焰","example":"Hydrogen burns with a flame that is almost invisible in daylight.","exampleCN":"氢气燃烧的火焰在日光下几乎看不见。","why":"Daily usage narrows the element to its gaseous molecule, because that is the form stored and burned.","whyCN":"日常用法把元素收窄为气态分子，因为那才是储存与燃烧的形态。"},{"no":"03","title":"The stuff of water","titleCN":"水中之氢：与氧结合成 H₂O","definition":"the element as bound in water, two hydrogen atoms to one oxygen atom","definitionCN":"结合在水中的元素，两个氢原子对一个氧原子","example":"Water is two parts hydrogen to one part oxygen by atom count.","exampleCN":"按原子数算，水是两份氢配一份氧。","why":"This is the sense behind the name itself: the gas was named as the substance that produces water when it burns.","whyCN":"这正是名字背后的义项：这种气体燃烧时生成水，因而被命名为「生水者」。"},{"no":"04","title":"Hydrogen ions and acidity","titleCN":"氢离子：决定溶液酸碱度","definition":"the bare proton released in solution that defines acidity and is measured by pH","definitionCN":"溶液中释放的裸质子，决定酸度并由 pH 衡量","example":"Acids release hydrogen ions, which is what lowers the pH.","exampleCN":"酸释放氢离子，正是它降低了 pH。","why":"Chemists track acidity by counting hydrogen ions, so the element name appears in every pH discussion.","whyCN":"化学家靠数氢离子来追踪酸度，因此这个元素名出现在每一次 pH 讨论中。"},{"no":"05","title":"Energy carrier","titleCN":"能源载体：储存与输送能量","definition":"hydrogen produced and stored as a fuel, especially when made with renewable electricity","definitionCN":"作为燃料生产与储存的氢，尤指用可再生电力制取者","example":"Green hydrogen could store summer wind power for winter.","exampleCN":"绿氢可以把夏季的风电储存到冬季。","why":"Because it burns without carbon, hydrogen is promoted from a chemical to an energy policy category.","whyCN":"由于燃烧不产生碳，氢从一种化学品被提升为能源政策类别。"},{"no":"06","title":"Hydrogen bonding","titleCN":"氢键：生命分子间的弱连接","definition":"the weak attraction between a hydrogen bonded to a small electronegative atom and a nearby lone pair","definitionCN":"与小电负性原子成键的氢，与邻近孤对电子之间的弱吸引","example":"Hydrogen bonds hold the two strands of DNA together.","exampleCN":"氢键把 DNA 的两条链维系在一起。","why":"The bond takes its name from the atom at its centre, so a whole family of weak interactions is labelled hydrogen.","whyCN":"这种键以位于中心的原子命名，因而一整族弱相互作用都被冠以 hydrogen。"},{"no":"07","title":"Lifting gas","titleCN":"浮升气体：飞艇时代的升力来源","definition":"the gas used to fill balloons and airships because it is far lighter than air","definitionCN":"因远比空气轻而用于填充气球与飞艇的气体","example":"The airship was filled with hydrogen, which gave more lift than any other gas available.","exampleCN":"飞艇充的是氢气，因为当时可用的气体中没有比它升力更大的。","why":"Buoyancy depends on density, so the lightest gas became the standard filling in the early age of flight.","whyCN":"浮力取决于密度，因此最轻的气体成了早期飞行时代的标准填充物。"},{"no":"08","title":"Fusion fuel","titleCN":"聚变燃料：恒星与氢弹的能量来源","definition":"the fuel of nuclear fusion, in which hydrogen nuclei join to release enormous energy","definitionCN":"核聚变的燃料，氢核结合并释放巨大能量","example":"The sun runs on hydrogen fusing into helium in its core.","exampleCN":"太阳靠核心中氢聚变成氦来运转。","why":"Astrophysics and weapons design both name the fuel by its nucleus, so hydrogen becomes shorthand for fusion.","whyCN":"天体物理学与武器设计都按原子核来称呼燃料，于是 hydrogen 成了聚变的代称。"}],"etymology":{"intro":{"en":"Hydrogen is a French scientific coinage of 1787 from Greek hydor 'water' and -genes 'producing', because the gas produces water when it burns.","cn":"hydrogen 是 1787 年的法语科学造词，由希腊 hydor「水」与 -genes「产生」构成，因为这种气体燃烧时生成水。"},"items":[{"era":"GREEK HYDOR","en":"Greek hydor, hydatos meant 'water', the source of English hydro- in hydrology and hydrate. The word is inherited from an older Indo-European form, reconstructed rather than recorded.","cn":"希腊 hydor、hydatos 意为「水」，是英语 hydrology、hydrate 中 hydro- 的来源。该词承自更早的印欧形式，属重构而非有记录的原词。"},{"era":"GREEK -GENES","en":"The combining form -genes 'born of, producing' comes from gen- 'to be born', the same root that gives oxygen and nitrogen their endings.","cn":"构词成分 -genes「由……所生、产生」出自 gen-「出生」，oxygen 与 nitrogen 的结尾也来自同一词根。"},{"era":"INFLAMMABLE AIR","en":"Cavendish isolated the gas in 1766 and called it 'inflammable air'. He did not yet know that water was its combustion product.","cn":"卡文迪什在 1766 年分离出这种气体，称之为「易燃空气」。他当时还不知道水是它的燃烧产物。"},{"era":"LAVOISIER 1787","en":"Lavoisier named it hydrogène 'water-former' after showing that burning the gas with oxygen yields water. English borrowed the word in the 1790s.","cn":"拉瓦锡证明这种气体与氧燃烧生成水后，把它命名为 hydrogène「生水者」。英语在 1790 年代借入该词。"},{"era":"NEW LATIN","en":"Scientific Latin formed hydrogenium, and the element took its place in the periodic table as number one.","cn":"科学拉丁语造出 hydrogenium，这个元素以第一号进入周期表。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertainty: the exact first English citation is uncertain, and the Indo-European word behind Greek hydor is a reconstruction, not a recorded form.","cn":"来源不确定：英语首见的确切书证年代存疑；希腊 hydor 背后的印欧词属重构，并非有记录的形式。"}]},"similar":{"note":{"en":"The first group holds words sharing the hydr- stem that name different substances; the second holds gases that behave differently from hydrogen.","cn":"第一组是同出 hydr- 词干但指不同物质的词；第二组是行为与氢不同的气体。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"hydroxide","ipa":"/haɪˈdrɒksaɪd/","tag":"OH group, not hydrogen","definition":"A compound or ion containing the OH group, such as sodium hydroxide. It contains hydrogen, but it is a distinct chemical unit.","definitionCN":"含 OH 基团的化合物或离子，如氢氧化钠。它含氢，但本身是独立的化学单元。"},{"word":"hydride","ipa":"/ˈhaɪdraɪd/","tag":"hydrogen with a metal","definition":"A compound in which hydrogen is bonded to a metal or another element, such as sodium hydride. It names a compound class, not the element.","definitionCN":"氢与金属或其他元素结合成的化合物，如氢化钠。它命名一类化合物，而不是元素。"},{"word":"hydrogenous","ipa":"/haɪˈdrɒdʒənəs/","tag":"the adjective","definition":"Means 'containing hydrogen', used especially of geological materials such as hydrogenous sediments.","definitionCN":"意为「含氢的」，多用于地质材料，如含氢沉积物。"}]},{"heading":"NEAR MEANING","entries":[{"word":"helium","ipa":"/ˈhiːliəm/","tag":"the safe lifting gas","definition":"The second lightest element, named after the sun. It gives slightly less lift than hydrogen but does not burn, so airships switched to it.","definitionCN":"第二轻的元素，因太阳得名。升力略低于氢，但不会燃烧，因此飞艇后来改用氦。"},{"word":"deuterium","ipa":"/djuːˈtɪəriəm/","tag":"heavy hydrogen","definition":"An isotope of hydrogen with one proton and one neutron, used as a tracer and as fusion fuel. It is hydrogen with extra mass.","definitionCN":"含一个质子与一个中子的氢同位素，用作示踪剂与聚变燃料。它是质量更大的氢。"},{"word":"methane","ipa":"/ˈmeθeɪn/","tag":"a carbon-bearing fuel gas","definition":"CH4, the main component of natural gas. It also burns, but it contains carbon and produces carbon dioxide.","definitionCN":"CH₄，天然气的主要成分。它也能燃烧，但含碳并产生二氧化碳。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Greek hydor 'water' + -genes 'producer': the gas that makes water when it burns.","cn":"希腊 hydor「水」+ -genes「产生者」：燃烧时生成水的气体。"},{"en":"The family runs hydrogenate, hydrogenation, hydride, hydroxide, hydrocarbon and hydrogenous.","cn":"同族词包括 hydrogenate、hydrogenation、hydride、hydroxide、hydrocarbon、hydrogenous。"},{"en":"Fixed phrases mark the fields: hydrogen bond, hydrogen peroxide, hydrogen ion, green hydrogen.","cn":"固定搭配标出领域：氢键、过氧化氢、氢离子、绿氢。"},{"en":"Water is H2O, so hydrogen is two thirds of every drop by atom count.","cn":"水是 H₂O，按原子数算氢占每一滴的三分之二。"},{"en":"Helium replaced hydrogen in airships mainly because hydrogen burns.","cn":"飞艇改用氦，主要是因为氢会燃烧。"}],"abstract":[{"en":"Picture a balloon rising fast on a thin string, the lightest gas lifting it without any engine.","cn":"想象一只气球被细绳牵着迅速上升，最轻的气体不用任何引擎就把它托起。"},{"en":"Picture an invisible flame above a metal nozzle, felt as heat but almost unseen.","cn":"想象金属喷嘴上方有一簇看不见的火焰，只能感到热，几乎看不见。"},{"en":"Picture two strands of a helix held by tiny dots of attraction that can be pulled apart.","cn":"想象螺旋的两条链由一个个微小的吸引力连住，随时可以被拉开。"}]},"examples":[{"en":"Hydrogen makes up about three quarters of the ordinary matter in the universe.","cn":"氢约占宇宙中普通物质的四分之三。"},{"en":"The tank holds hydrogen at very high pressure.","cn":"这个储罐在极高压力下储存氢气。"},{"en":"Hydrogen bonds break and re-form constantly in liquid water.","cn":"在液态水中，氢键不断断裂又重组。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「hydro（水）+ gen（产生）」——燃烧后生成水的气体 → hydrogen 氢","word":"hydrogen"},"root":"希腊 hydor「水」+ -genes「产生者」→ 法语 hydrogène（1787，拉瓦锡）→ 英语 hydrogen。","sensesIntro":{"en":"Eight senses follow one element from the periodic table through gas, water, acidity, energy, the hydrogen bond, flight and fusion.","cn":"八个义项让同一个元素从周期表走进气体、水、酸性、能源、氢键、飞行与聚变。"},"semanticMap":{"core":{"en":"CORE IMAGE: the lightest gas lifting a balloon, and water splitting into its atoms.","cn":"核心意象：最轻的气体托起气球，水被拆成它的原子。"},"chain":["ONE PROTON","THE LIGHT GAS","BIND IN WATER","RELEASE A PROTON","CARRY ENERGY","FUSE IN STARS"],"branches":[{"senses":"S1","en":"THE ATOM: element 1 is defined by a single proton.","cn":"原子：1 号元素由一个质子定义。"},{"senses":"S2 · S3","en":"TWO FACES: free as a flammable gas, bound as the bulk of water.","cn":"两面：游离时是可燃气体，结合时是水的主体。"},{"senses":"S4","en":"ACIDITY: the bare ion is the currency of pH.","cn":"酸性：裸离子是 pH 的通用单位。"},{"senses":"S5 · S8","en":"ENERGY: burning it stores power; fusing it powers stars.","cn":"能量：燃烧它储存电力，聚变它点亮恒星。"},{"senses":"S6 · S7","en":"LIGHTNESS: the weakest bond and the strongest lift both come from being the smallest atom.","cn":"轻：最弱的键与最大的升力都来自「它是最小的原子」。"}]},"affixes":{"intro":{"en":"Hydrogen joins a Greek word for water to a Greek suffix for producing, then passes through French before English adopts it.","cn":"hydrogen 把希腊语「水」与希腊语「产生」后缀结合，再经法语传入英语。"},"latinIntro":{"en":"New Latin hydrogenium fixed the element name, from which hydride, hydroxide and hydrogenate were later built using Latin and Greek suffixes.","cn":"新拉丁语 hydrogenium 固定了元素名，此后的 hydride、hydroxide 与 hydrogenate 都借拉丁与希腊后缀由它构成。"},"items":[{"word":"hydrogen","structure":"Greek hydor + -genes (water-producing)","meaning":"element 1 and its gas","meaningCN":"1 号元素及其气体","example":"Hydrogen is stored under pressure.","exampleCN":"氢在加压条件下储存。"},{"word":"hydride","structure":"hydr- (water, hydrogen) + -ide","meaning":"a compound of hydrogen with another element","meaningCN":"氢与另一元素形成的化合物","example":"Lithium hydride stores hydrogen safely.","exampleCN":"氢化锂可安全储存氢。"},{"word":"hydroxide","structure":"hydr- + ox- (oxygen) + -ide","meaning":"a compound containing the OH group","meaningCN":"含 OH 基团的化合物","example":"Sodium hydroxide is a strong base.","exampleCN":"氢氧化钠是强碱。"},{"word":"hydrocarbon","structure":"hydro- + carbon","meaning":"a compound of hydrogen and carbon only","meaningCN":"只由氢与碳构成的化合物","example":"Petrol is a mixture of hydrocarbons.","exampleCN":"汽油是多种碳氢化合物的混合物。"},{"word":"hydrogenate","structure":"hydrogen + -ate (verb)","meaning":"to add hydrogen to a molecule","meaningCN":"给分子加氢","example":"They hydrogenate the oil under pressure.","exampleCN":"他们在加压下氢化这种油。"},{"word":"hydrogenation","structure":"hydrogenate + -ion","meaning":"the process of adding hydrogen","meaningCN":"加氢的过程","example":"Hydrogenation hardens the fat.","exampleCN":"氢化使脂肪变硬。"},{"word":"hydrogenous","structure":"hydrogen + -ous","meaning":"containing hydrogen","meaningCN":"含氢的","example":"Hydrogenous sediments form on the sea floor.","exampleCN":"含氢沉积物在海底形成。"},{"word":"dehydrogenate","structure":"de- (remove) + hydrogenate","meaning":"to remove hydrogen from a molecule","meaningCN":"从分子中脱氢","example":"The enzyme dehydrogenates the alcohol.","exampleCN":"该酶使醇脱氢。"},{"word":"hydrology","structure":"hydro- + -logy (study)","meaning":"the study of water","meaningCN":"研究水的学科","example":"Hydrology models the river's flow.","exampleCN":"水文学为河流流量建模。"}],"latinEntries":[{"word":"hydrogenium","structure":"hydrogenium (n., New Latin, second declension)","meaning":"hydrogen","meaningCN":"氢"},{"word":"hydro-","structure":"Greek hydor, hydatos (water) used as a prefix","meaning":"water","meaningCN":"水"},{"word":"-genes","structure":"-genes (Greek combining form, from gen-)","meaning":"born of, producing","meaningCN":"由……所生、产生"}]}},{"word":"hydrogenation","ipa_uk":"/ˌhaɪdrədʒəˈneɪʃn/","ipa_us":"/ˌhaɪdrədʒəˈneɪʃn/","definition_zh":"氢化；加氢作用","definition_en":"the chemical process of adding hydrogen to a molecule, especially to unsaturated fats and oils","core_image":"液态油在催化剂与氢气流中逐渐变成半固态的白色脂肪块","scene":"Partial hydrogenation turned the liquid oil into a spreadable fat, but it also created trans fats.","sceneCN":"这里 hydrogenation 指「油脂氢化」（第 2 个义项：把液态油变成固态或半固态脂肪的工业过程）；部分氢化带来了可涂抹的质地，也带来了反式脂肪。图中可辨识物件：氢化反应釜、催化剂、氢气管路、油脂样本。","pos":[{"tag":"n.","zh":"氢化；加氢作用（多作不可数名词，指工艺时可说 partial hydrogenation）"}],"collocations":[{"phrase":"partial hydrogenation","zh":"部分氢化"},{"phrase":"catalytic hydrogenation","zh":"催化氢化"},{"phrase":"hydrogenation of oils","zh":"油脂氢化"},{"phrase":"hydrogenated fat","zh":"氢化脂肪"},{"phrase":"hydrogenation reaction","zh":"加氢反应"},{"phrase":"fully hydrogenated oil","zh":"全氢化油"}],"forms":[{"label":"不可数用法","form":"hydrogenation（指工艺过程时一般不加 -s）"},{"label":"动词形式","form":"hydrogenate（使氢化）"},{"label":"形容词形式","form":"hydrogenated（氢化的）"},{"label":"反向过程","form":"dehydrogenation（脱氢）"},{"label":"相关名词","form":"hydrogen（氢）；hydrogenator（氢化装置）"}],"derivatives":[{"word":"hydrogenate","pos":"v.","zh":"使氢化；加氢"},{"word":"hydrogenated","pos":"adj.","zh":"氢化的；加氢的"},{"word":"dehydrogenation","pos":"n.","zh":"脱氢作用"},{"word":"hydrogen","pos":"n.","zh":"氢"},{"word":"hydrogenolysis","pos":"n.","zh":"氢解（用氢断裂化学键）"}],"senses":[{"no":"01","title":"General addition of hydrogen","titleCN":"一般加氢：把氢引入分子","definition":"any chemical reaction that adds hydrogen atoms to a molecule, usually across a double or triple bond","definitionCN":"把氢原子加入分子的任何化学反应，通常发生在双键或三键上","example":"Hydrogenation of an alkene turns it into an alkane.","exampleCN":"烯烃加氢后变成烷烃。","why":"The noun simply names the act behind hydrogenate: hydrogen is made to join a molecule.","whyCN":"这个名词就是 hydrogenate 所表动作的名称化：让氢与分子结合。"},{"no":"02","title":"Hardening edible oils","titleCN":"油脂硬化：把液态油变成固态脂肪","definition":"the industrial process that adds hydrogen to vegetable oil so that it becomes semi-solid and spreadable","definitionCN":"向植物油加氢、使其变成半固态可涂抹脂肪的工业过程","example":"Hydrogenation made cottonseed oil suitable for margarine.","exampleCN":"氢化让棉籽油适合制作人造黄油。","why":"Food manufacturing needed a cheap solid fat, and hydrogenation turns a liquid oil into one by removing double bonds.","whyCN":"食品工业需要廉价的固态脂肪，而氢化通过消除双键，把液态油变成固态。"},{"no":"03","title":"The trans fat side effect","titleCN":"反式脂肪：部分氢化的副产物","definition":"the formation of trans unsaturated fatty acids when hydrogenation is stopped before completion","definitionCN":"氢化在完全之前停止时生成的反式不饱和脂肪酸","example":"Partial hydrogenation created trans fats that later drew health warnings.","exampleCN":"部分氢化产生的反式脂肪后来引发了健康警告。","why":"Because the process flips some double bonds into the trans position, the name of the process became linked to a health hazard.","whyCN":"由于该过程把部分双键翻成反式，工艺名便与一种健康危害联系在了一起。"},{"no":"04","title":"Full versus partial","titleCN":"全氢化与部分氢化：工艺程度的差别","definition":"the distinction between hydrogenating every double bond and stopping while some remain","definitionCN":"把每个双键都氢化，与在仍有双键残留时停止，两者之间的区别","example":"Fully hydrogenated oil contains almost no trans fat but is very hard.","exampleCN":"全氢化油几乎不含反式脂肪，但质地很硬。","why":"Industry controls the endpoint, so the process name splits into two grades with different properties.","whyCN":"工业控制反应终点，因此工艺名分成两级，性质也不同。"},{"no":"05","title":"Petrochemical hydrotreating","titleCN":"石油加氢：炼厂脱硫与稳定化","definition":"the refining step that adds hydrogen to petroleum fractions to remove sulfur and stabilize them","definitionCN":"炼油中向馏分加氢以脱硫并使其稳定的步骤","example":"Hydrogenation in the refinery removes sulfur from diesel.","exampleCN":"炼厂的加氢过程为柴油脱硫。","why":"Refiners use the same reaction at a huge scale, so the general chemical term doubles as an industry word.","whyCN":"炼厂以极大规模使用同一反应，因此这个普通化学术语也兼作工业用语。"},{"no":"06","title":"Coal liquefaction","titleCN":"煤加氢：把煤变成液体燃料","definition":"the Bergius-type process that adds hydrogen to coal under high pressure to produce liquid fuels","definitionCN":"在高压下向煤加氢以制取液体燃料的伯吉斯式工艺","example":"Coal hydrogenation supplied fuel when oil was scarce.","exampleCN":"石油短缺时，煤加氢提供了燃料。","why":"Because coal is hydrogen-poor, adding hydrogen is exactly what turns it into something pumpable.","whyCN":"煤贫氢，因此加氢正是把它变成可泵送液体的关键。"},{"no":"07","title":"Laboratory reduction","titleCN":"实验室还原：合成中的标准步骤","definition":"the use of hydrogen with a metal catalyst in the lab to reduce double bonds or functional groups","definitionCN":"实验室中以氢气加金属催化剂还原双键或官能团","example":"The synthesis ended with catalytic hydrogenation of the nitro group.","exampleCN":"合成以硝基的催化氢化收尾。","why":"Organic chemists speak of hydrogenation when the reagent is H2, even though the reaction is also a reduction.","whyCN":"当试剂是 H2 时，有机化学家会说 hydrogenation，尽管该反应同时属于还原。"},{"no":"08","title":"A word on food labels","titleCN":"食品标签用语：判定加工方式","definition":"the process named on packaging when a product contains hydrogenated or partially hydrogenated oils","definitionCN":"产品含氢化油或部分氢化油时，包装上标明的加工方式","example":"The label lists partially hydrogenated oil, which signals hydrogenation.","exampleCN":"标签列出部分氢化油，这表明产品经过氢化。","why":"Regulators require the process to be named, so a laboratory term became a line on a packet.","whyCN":"监管要求标明加工方式，因此一个实验室术语变成了包装上的一行字。"}],"etymology":{"intro":{"en":"Hydrogenation is hydrogen plus the Latin action-noun ending -ation, coined when chemists began adding hydrogen to compounds in the nineteenth century.","cn":"hydrogenation 是 hydrogen 加拉丁动作名词词尾 -ation，在 19 世纪化学家开始向化合物加氢时造出。"},"items":[{"era":"GREEK STEM","en":"Hydrogen itself was coined in French in 1787 from Greek hydor 'water' and -genes 'producing', because burning the gas yields water.","cn":"hydrogen 本身是 1787 年的法语造词，由希腊 hydor「水」与 -genes「产生」构成，因为燃烧该气体生成水。"},{"era":"NEW LATIN","en":"Scientific Latin formed hydrogenium, giving chemists a noun to build verbs and further nouns from.","cn":"科学拉丁语造出 hydrogenium，使化学家有了可造动词与更多名词的基底。"},{"era":"EARLY ADDITION REACTIONS","en":"In the later nineteenth century chemists described adding hydrogen across double bonds, first with platinum catalysts, and needed a name for the act.","cn":"19 世纪后期，化学家描述用铂催化在双键上加氢，并需要一个名称来指这一动作。"},{"era":"INDUSTRIAL OILS","en":"In 1901 Normann patented the hardening of liquid oils with hydrogen, the step that made margarine an industry.","cn":"1901 年诺曼取得用氢硬化液态油的专利，这一步让人造黄油成为产业。"},{"era":"HEALTH DEBATE","en":"From the 1990s regulators and doctors linked partial hydrogenation to trans fats, and the process name entered nutrition labels.","cn":"自 1990 年代起，监管者与医生把部分氢化与反式脂肪联系起来，工艺名由此进入营养标签。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertainty: the exact first English use of hydrogenation is uncertain; the term likely entered through German and French chemical literature before English textbooks.","cn":"来源不确定：hydrogenation 的英语首见确切年代存疑；该术语可能先经德语与法语化学文献，再进入英语教科书。"}]},"similar":{"note":{"en":"The first group holds process words that sound alike but move hydrogen in opposite directions; the second holds related chemical processes that are not hydrogen addition.","cn":"第一组是读音相近、但氢的走向相反的过程词；第二组是相关但并非加氢的化学过程。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"dehydrogenation","ipa":"/ˌdiːhaɪdrədʒəˈneɪʃn/","tag":"the reverse","definition":"The removal of hydrogen from a molecule, often to create a double bond. Hydrogenation adds hydrogen; dehydrogenation takes it away.","definitionCN":"从分子中除去氢，常用来形成双键。hydrogenation 加氢，dehydrogenation 去氢。"},{"word":"hydrogenated","ipa":"/ˌhaɪdrədʒəˈneɪtɪd/","tag":"the adjective","definition":"Describes a product that has undergone the process, as in hydrogenated vegetable oil. It names the result, not the reaction.","definitionCN":"描述经历过该过程的产品，如氢化植物油。它命名结果，而不是反应。"},{"word":"hydration","ipa":"/ˈhaɪdreɪʃn/","tag":"water, not hydrogen","definition":"The addition of water to a substance, or the state of being supplied with water. It is a different reaction and a different everyday word.","definitionCN":"向物质加水，或获得水的状态。它是另一种反应，也是另一个日常用词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"saturation","ipa":"/ˌsætʃəˈreɪʃn/","tag":"the chemical result","definition":"The state in which a fat or molecule has no double bonds left. Hydrogenation is one way to reach saturation, but saturation itself is only the result.","definitionCN":"脂肪或分子不再有双键的状态。氢化是达到饱和的一种方式，但饱和本身只是结果。"},{"word":"reduction","ipa":"/rɪˈdʌkʃn/","tag":"the wider class","definition":"In chemistry, the gain of electrons. Hydrogenation is usually a reduction, but many reductions involve no hydrogen at all.","definitionCN":"化学上指获得电子。氢化通常属于还原，但许多还原反应完全不涉及氢。"},{"word":"hydrotreating","ipa":"/ˈhaɪdrəʊˌtriːtɪŋ/","tag":"the refinery name","definition":"The refining version of hydrogen addition, aimed at removing sulfur and nitrogen rather than at hardening a product.","definitionCN":"炼油业中加氢的版本，目的在于脱硫脱氮，而不是硬化产品。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"hydrogen + -ation: the process of putting hydrogen in.","cn":"hydrogen + -ation：把氢放进去的过程。"},{"en":"The family runs hydrogenate, hydrogenated, dehydrogenation and hydrogenolysis.","cn":"同族词包括 hydrogenate、hydrogenated、dehydrogenation、hydrogenolysis。"},{"en":"Fixed phrases mark the fields: partial hydrogenation, catalytic hydrogenation, hydrogenated fat.","cn":"固定搭配标出领域：部分氢化、催化氢化、氢化脂肪。"},{"en":"Partial hydrogenation is the one that creates trans fats; full hydrogenation does not.","cn":"产生反式脂肪的是部分氢化；全氢化不会。"},{"en":"Margarine exists because liquid oil could be made solid by hydrogenation.","cn":"人造黄油之所以存在，是因为液态油能靠氢化变成固态。"}],"abstract":[{"en":"Picture clear yellow oil entering a steel vessel and leaving as a white block.","cn":"想象清亮的黄色油进入钢制反应釜，出来时已成白色块状。"},{"en":"Picture bubbles of gas fitting into the gaps of long molecular chains and locking them straight.","cn":"想象气体气泡嵌进长分子链的空隙，把链锁成直排。"},{"en":"Picture a packet turning around to show a line that says partially hydrogenated.","cn":"想象一个包装袋翻过来，露出一行写着「部分氢化」的字。"}]},"examples":[{"en":"Catalytic hydrogenation is a standard way to reduce a double bond.","cn":"催化氢化是还原双键的常规方法。"},{"en":"The factory stopped partial hydrogenation to cut trans fats.","cn":"这家工厂停止了部分氢化，以减少反式脂肪。"},{"en":"Coal hydrogenation produced synthetic fuel during the war.","cn":"战时煤加氢生产了合成燃料。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「hydrogen（氢）+ ation（过程）」——把氢加进分子的过程 → hydrogenation 氢化","word":"hydrogenation"},"root":"希腊 hydor「水」+ -genes「产生者」→ hydrogen + 拉丁 -atio → hydrogenation。","sensesIntro":{"en":"Eight senses follow one reaction from the laboratory to margarine, refineries, coal plants, nutrition labels and the trans fat debate.","cn":"八个义项让同一个反应从实验室走进人造黄油、炼厂、煤液化、营养标签与反式脂肪之争。"},"semanticMap":{"core":{"en":"CORE IMAGE: clear oil turning into a white block inside a steel vessel.","cn":"核心意象：清亮的油在钢制反应釜里变成白色块状物。"},"chain":["ADD H","REMOVE DOUBLE BONDS","HARDEN THE FAT","FORM TRANS FATS","TREAT FUELS","LABEL THE PACKET"],"branches":[{"senses":"S1","en":"PLAIN REACTION: hydrogen joins a molecule, usually across an unsaturated bond.","cn":"基本反应：氢加入分子，通常发生在不饱和键上。"},{"senses":"S2 · S4","en":"FOOD TEXTURE: stopping early or going all the way gives two very different fats.","cn":"食物质地：早停或走到底，得到两种很不同的脂肪。"},{"senses":"S3 · S8","en":"PUBLIC HEALTH: the side effect and the label keep the process in the news.","cn":"公共健康：副产物与标签让这一工艺持续出现在新闻里。"},{"senses":"S5 · S6","en":"FUEL: refineries and coal plants use the same reaction at industrial scale.","cn":"燃料：炼厂与煤化工厂以工业规模使用同一反应。"},{"senses":"S7","en":"SYNTHESIS: in the lab, hydrogen is the reagent that makes reduction concrete.","cn":"合成：在实验室里，氢是把「还原」落到实处的试剂。"}]},"affixes":{"intro":{"en":"Hydrogenation stacks a Greek-derived element name and a Latin action ending, so the word reads as 'the act of applying hydrogen'.","cn":"hydrogenation 把一个源自希腊的元素名与拉丁动作词尾叠在一起，读作「施加氢的动作」。"},"latinIntro":{"en":"Latin -atio marks action nouns, and New Latin hydrogenium gave the stem; the same ending appears in oxidation, saturation and dehydration.","cn":"拉丁 -atio 标记动作名词，新拉丁 hydrogenium 提供词干；同一词尾也见于 oxidation、saturation 与 dehydration。"},"items":[{"word":"hydrogenation","structure":"hydrogen + -ate + -ion","meaning":"the act of adding hydrogen","meaningCN":"加氢的动作","example":"Hydrogenation of the oil took four hours.","exampleCN":"这种油的氢化花了四个小时。"},{"word":"hydrogenate","structure":"hydrogen + -ate (verb)","meaning":"to add hydrogen to","meaningCN":"给……加氢","example":"They hydrogenate the fat under pressure.","exampleCN":"他们在加压下氢化这种脂肪。"},{"word":"hydrogenated","structure":"hydrogenate + -ed","meaning":"having undergone hydrogen addition","meaningCN":"已经加氢的","example":"Hydrogenated oils are firmer at room temperature.","exampleCN":"氢化油在室温下更硬。"},{"word":"dehydrogenation","structure":"de- (remove) + hydrogenation","meaning":"the removal of hydrogen","meaningCN":"除去氢的过程","example":"Dehydrogenation creates a double bond.","exampleCN":"脱氢会形成一个双键。"},{"word":"hydrogenolysis","structure":"hydrogen + -lysis (loosening)","meaning":"breaking a bond with hydrogen","meaningCN":"用氢断裂化学键","example":"Hydrogenolysis split the ring open.","exampleCN":"氢解把环打开了。"},{"word":"hydrogen","structure":"Greek hydor + -genes","meaning":"the element added in the reaction","meaningCN":"反应中加入的元素","example":"Hydrogen is supplied at high purity.","exampleCN":"氢以高纯度供应。"},{"word":"hydrotreating","structure":"hydro- + treating","meaning":"refinery hydrogen treatment","meaningCN":"炼厂加氢处理","example":"Hydrotreating lowered the sulfur content.","exampleCN":"加氢处理降低了硫含量。"},{"word":"hydration","structure":"hydr- + -ation","meaning":"the addition of water","meaningCN":"加水的过程","example":"Hydration keeps the skin flexible.","exampleCN":"补水让皮肤保持柔韧。"}],"latinEntries":[{"word":"hydrogenium","structure":"hydrogenium (n., New Latin, second declension)","meaning":"hydrogen","meaningCN":"氢"},{"word":"-atio","structure":"-atio, -ationis (f., third declension)","meaning":"action-noun suffix","meaningCN":"动作名词后缀"},{"word":"hydrogenare","structure":"hydrogenare (verb, New Latin, first conjugation)","meaning":"to combine with hydrogen","meaningCN":"使与氢结合"}]}},{"word":"phosphorus","ipa_uk":"/ˈfɒsfərəs/","ipa_us":"/ˈfɑːsfərəs/","definition_zh":"磷","definition_en":"the chemical element of atomic number 15, a non-metal that occurs in several coloured forms and glows faintly in the dark","core_image":"暗室中一块蜡状白色固体发出淡绿色微光，旁边是一盒火柴","scene":"In the dark, the white phosphorus on the stick glowed with a faint green light.","sceneCN":"这里 phosphorus 指「白磷」（第 2 个义项：会自燃、在暗处发光的同素异形体）；它在黑暗中缓慢氧化，发出淡绿微光。图中可辨识物件：暗室、白磷块、淡绿光晕、防火手套。","pos":[{"tag":"n.","zh":"磷（不可数；化学符号 P）"}],"collocations":[{"phrase":"white phosphorus","zh":"白磷"},{"phrase":"red phosphorus","zh":"红磷"},{"phrase":"phosphorus cycle","zh":"磷循环"},{"phrase":"phosphorus deficiency","zh":"缺磷"},{"phrase":"phosphorus content","zh":"磷含量"},{"phrase":"phosphorus pentoxide","zh":"五氧化二磷"}],"forms":[{"label":"不可数用法","form":"phosphorus（元素名，一般不加 -s）"},{"label":"化学符号","form":"P"},{"label":"形容词形式","form":"phosphoric（磷酸的）；phosphorous（亚磷的；发磷光的）"},{"label":"化合物名词","form":"phosphate（磷酸盐）；phosphide（磷化物）"},{"label":"动词形式","form":"phosphorylate（使磷酸化）"}],"derivatives":[{"word":"phosphate","pos":"n.","zh":"磷酸盐；磷酸根"},{"word":"phosphoric","pos":"adj.","zh":"磷酸的"},{"word":"phosphorous","pos":"adj.","zh":"亚磷的；发磷光的"},{"word":"phosphide","pos":"n.","zh":"磷化物"},{"word":"phosphorylate","pos":"v.","zh":"使磷酸化"},{"word":"phospholipid","pos":"n.","zh":"磷脂"}],"senses":[{"no":"01","title":"The element","titleCN":"磷元素：原子序数 15","definition":"the chemical element with atomic number 15, a non-metal essential to life and to fertiliser","definitionCN":"原子序数为 15 的元素，非金属，为生命与肥料所必需","example":"Phosphorus has fifteen protons and occurs in several allotropes.","exampleCN":"磷有十五个质子，并以多种同素异形体存在。","why":"The name is used for the element as a whole, so it covers the white, red and black forms alike.","whyCN":"这个名字用于整个元素，因此白磷、红磷与黑磷都适用。"},{"no":"02","title":"White phosphorus","titleCN":"白磷：会自燃与发光的蜡状固体","definition":"the waxy, highly reactive form that ignites in air and glows faintly in the dark, and is also toxic","definitionCN":"蜡状、极易反应的同素异形体，在空气中自燃，暗处发微光，且有毒性","example":"White phosphorus must be stored under water to keep it from igniting.","exampleCN":"白磷必须保存在水下，以免自燃。","why":"Its glow is the very reason for the name, since Greek phosphoros meant 'light-bearer'.","whyCN":"它的发光正是名字的由来，因为希腊 phosphoros 意为「带光者」。"},{"no":"03","title":"Red phosphorus","titleCN":"红磷：火柴盒上的安全形态","definition":"the safer, less reactive allotrope used on matchbox surfaces and in flame retardants","definitionCN":"较安全、较不活泼的同素异形体，用于火柴盒面与阻燃剂","example":"Red phosphorus on the box turns friction into a flame.","exampleCN":"盒面上的红磷把摩擦变成火焰。","why":"Chemistry names the allotropes by colour, so the same element appears under adjectives rather than new nouns.","whyCN":"化学按颜色给同素异形体命名，于是同一元素以形容词形式出现，而不是另造名词。"},{"no":"04","title":"In DNA and ATP","titleCN":"核酸与能量分子中的磷","definition":"the element as bound in phosphate groups that link DNA backbones and store energy in ATP","definitionCN":"结合在磷酸基团中的元素，连接 DNA 骨架并在 ATP 中储存能量","example":"Phosphorus in the sugar-phosphate backbone gives DNA its negative charge.","exampleCN":"糖-磷酸骨架中的磷赋予 DNA 负电荷。","why":"Life's energy currency is a phosphate chain, so the element name appears wherever energy transfer is discussed.","whyCN":"生命的能量货币是一条磷酸链，因此凡讨论能量转移处都会出现这个元素名。"},{"no":"05","title":"Bones and teeth","titleCN":"骨骼与牙齿：羟基磷灰石中的磷","definition":"the element stored in bone mineral as calcium phosphate, the main solid of skeleton and teeth","definitionCN":"以磷酸钙形式储存在骨矿物中的元素，是骨骼与牙齿的主要固体成分","example":"Nearly all the body's phosphorus sits in the skeleton.","exampleCN":"人体几乎全部的磷都储存在骨骼里。","why":"Bone is a mineral crystal, so the element that builds it is discussed as a reserve as well as a nutrient.","whyCN":"骨是一种矿物晶体，因此构成它的元素既被当作养分，也被当作储备。"},{"no":"06","title":"Fertiliser and phosphate rock","titleCN":"磷肥与磷矿：农业的三大养分之一","definition":"the nutrient mined as phosphate rock and applied to soil as fertiliser","definitionCN":"以磷矿石开采、作为肥料施入土壤的养分","example":"Phosphorus is one of the three main nutrients in fertiliser.","exampleCN":"磷是肥料中三大主要养分之一。","why":"Agriculture names the nutrient by the element, even though the bag contains phosphate salts.","whyCN":"农业以元素名来称呼这种养分，尽管袋子里装的是磷酸盐。"},{"no":"07","title":"Eutrophication","titleCN":"富营养化：磷过量引发藻华","definition":"the element as a pollutant that limits or, when excessive, overfeeds freshwater algae","definitionCN":"作为污染物的元素，在淡水里限制藻类生长，过量时则使其疯长","example":"Extra phosphorus from detergent runoff fed the algal bloom.","exampleCN":"洗涤剂径流带来的额外磷助长了藻华。","why":"Because freshwater algae are usually phosphorus-limited, a small excess changes the whole lake.","whyCN":"由于淡水藻类通常受磷限制，少量过量就能改变整个湖泊。"},{"no":"08","title":"The morning star","titleCN":"启明星：名字里的「带光者」","definition":"the sense carried by the name, which was an epithet of the planet Venus as the morning star before it named the element","definitionCN":"名字携带的义项：在成为元素名之前，它是金星作为启明星的称号","example":"The word phosphorus meant 'light-bearer' long before it meant element fifteen.","exampleCN":"在表示 15 号元素之前很久，phosphorus 的意思就是「带光者」。","why":"Hennig Brand named the glowing substance after the star, so the old celestial sense is still readable in the word.","whyCN":"布兰德以那颗星为发光的物质命名，因此旧的天文义至今仍能从词中读出。"}],"etymology":{"intro":{"en":"Phosphorus is Latin for the morning star, borrowed from Greek phosphoros 'light-bearer'. The element took the name because it glows in the dark.","cn":"phosphorus 是拉丁语「启明星」，借自希腊 phosphoros「带光者」。这种元素因在暗处发光而得名。"},"items":[{"era":"GREEK PHOS","en":"Greek phos, photos meant 'light'. It is related to phaos and phainein 'to show, to appear', the root behind English phenomenon and fantasy.","cn":"希腊 phos、photos 意为「光」，与 phaos 及 phainein「显现、出现」相关，后者是英语 phenomenon、fantasy 的词根。"},{"era":"GREEK PHOROS","en":"The second element comes from pherein 'to carry', so phosphoros is literally 'light-carrying'. The same verb gives English -phore and metaphor.","cn":"第二部分出自 pherein「携带」，因此 phosphoros 字面就是「带着光的」。同一动词也给英语留下 -phore 与 metaphor。"},{"era":"LATIN STAR NAME","en":"Latin phosphorus named the morning star, that is Venus at dawn, and was used as an epithet for things that bring light.","cn":"拉丁 phosphorus 指启明星，即黎明时的金星，也用作带来光明之物的称号。"},{"era":"BRAND 1669","en":"Hennig Brand isolated a glowing substance from urine in 1669 and called it phosphorus, after the star, because it shone in the dark.","cn":"1669 年亨尼格·布兰德从尿液中分离出一种发光物质，因它在暗处发亮而以那颗星命名，称之为 phosphorus。"},{"era":"ELEMENT 15","en":"Later chemistry kept the name for element 15, while the adjective phosphoric was reserved for its higher acid and phosphorous for the lower one.","cn":"后来的化学把这一名称留给 15 号元素，同时把形容词 phosphoric 留给高价酸、phosphorous 留给低价形态。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertainty: the Indo-European root behind Greek phos is reconstructed, not recorded; and the exact date when phosphorus replaced the older Latin star name in English chemistry is uncertain.","cn":"来源不确定：希腊 phos 背后的印欧词根属重构而非有记录；phosphorus 在英语化学中取代旧拉丁星名的确切年代亦存疑。"}]},"similar":{"note":{"en":"The first group holds words whose endings differ by a single letter and mean different oxidation states; the second holds neighbouring substances that are often confused with the element.","cn":"第一组是词尾仅差一个字母、却表示不同氧化态的词；第二组是常与元素本身混淆的邻近物质。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"phosphorous","ipa":"/ˈfɒsfərəs/","tag":"adjective, lower state","definition":"An adjective for the lower oxidation state, as in phosphorous acid. It is spelled with -ous, while the element noun ends in -us.","definitionCN":"表示较低氧化态的形容词，如亚磷酸。它拼作 -ous，而元素名词以 -us 结尾。"},{"word":"phosphoric","ipa":"/fɒsˈfɒrɪk/","tag":"adjective, higher state","definition":"An adjective for the higher oxidation state, as in phosphoric acid. It never names the element itself.","definitionCN":"表示较高氧化态的形容词，如磷酸。它从不指元素本身。"},{"word":"phosphate","ipa":"/ˈfɒsfeɪt/","tag":"a salt, not the element","definition":"A salt or ester containing the PO4 group, such as calcium phosphate in bone. Phosphorus is the element; phosphate is one of its commonest compounds.","definitionCN":"含 PO₄ 基团的盐或酯，如骨中的磷酸钙。phosphorus 是元素，phosphate 是它最常见的化合物之一。"}]},{"heading":"NEAR MEANING","entries":[{"word":"phosphorescence","ipa":"/ˌfɒsfəˈresns/","tag":"the glow, not the element","definition":"The slow emission of light after exposure to radiation, named after phosphorus because both glow in the dark.","definitionCN":"受辐射后缓慢发光的现象，因二者都在暗处发光而以磷命名。"},{"word":"sulfur","ipa":"/ˈsʌlfə/","tag":"the other match element","definition":"A yellow non-metal that also burns and is mined for fertiliser and chemicals. It is often mistaken for phosphorus in old match recipes.","definitionCN":"一种黄色非金属，也能燃烧，并用于肥料与化工。在旧式火柴配方中常与磷混淆。"},{"word":"calcium","ipa":"/ˈkælsiəm/","tag":"partner in bone","definition":"The metal that combines with phosphate to form bone mineral. Bones need both, so the two are usually discussed together.","definitionCN":"与磷酸结合形成骨矿物的金属。骨骼两者都需，因此常被一起讨论。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Greek phos 'light' + phoros 'bearing': the light-bearer, first a star and then a glowing element.","cn":"希腊 phos「光」+ phoros「携带」：带光者，先是星辰，后是发光的元素。"},{"en":"The family runs phosphate, phosphoric, phosphorous, phosphide, phosphorylate and phospholipid.","cn":"同族词包括 phosphate、phosphoric、phosphorous、phosphide、phosphorylate、phospholipid。"},{"en":"Fixed phrases mark the fields: white phosphorus, red phosphorus, phosphorus cycle, phosphorus deficiency.","cn":"固定搭配标出领域：白磷、红磷、磷循环、缺磷。"},{"en":"The element is stored under water because white phosphorus ignites in air.","cn":"这种元素保存在水下，因为白磷在空气中会自燃。"},{"en":"Phosphorus is one of the three main fertiliser nutrients, beside nitrogen and potassium.","cn":"磷是肥料三大主要养分之一，与氮、钾并列。"}],"abstract":[{"en":"Picture a dark room where a lump of wax-like solid gives off a faint green glow.","cn":"想象一间暗室，一块蜡状固体散出淡淡的绿光。"},{"en":"Picture a matchbox surface that turns a short scrape into a flame.","cn":"想象火柴盒面把一次短促的摩擦变成火焰。"},{"en":"Picture a lake turning green as an invisible nutrient tips the balance.","cn":"想象一种看不见的养分打破平衡，湖面转绿。"}]},"examples":[{"en":"Phosphorus is essential for ATP, the cell's energy currency.","cn":"磷是细胞能量货币 ATP 的必需成分。"},{"en":"The mine supplies phosphate rock rich in phosphorus.","cn":"这座矿山供应富含磷的磷矿石。"},{"en":"White phosphorus burns through clothing and is banned in some weapons.","cn":"白磷能烧穿衣物，在某些武器中被禁用。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「phos（光）+ phoros（带着）」——在暗处发光的元素 → phosphorus 磷","word":"phosphorus"},"root":"希腊 phos「光」+ pherein「携带」→ phosphoros「带光者」→ 拉丁 phosphorus（启明星）→ 英语 phosphorus 磷。","sensesIntro":{"en":"Eight senses follow one element from the periodic table through white and red forms, DNA, bone, fertiliser, pollution and the star name inside the word.","cn":"八个义项让同一个元素从周期表走进白磷与红磷、DNA、骨骼、肥料、污染，最后落在词里那颗星的名字上。"},"semanticMap":{"core":{"en":"CORE IMAGE: a waxy lump glowing green in the dark.","cn":"核心意象：暗处一块蜡状固体发出绿光。"},"chain":["ELEMENT FIFTEEN","GLOW IN THE DARK","LIGHT THE MATCH","BUILD DNA","FORM BONE","FEED AND POLLUTE"],"branches":[{"senses":"S1","en":"THE ATOM: element 15 exists in several allotropes, which the next senses name by colour.","cn":"原子：15 号元素有多个同素异形体，随后几个义项按颜色为它们命名。"},{"senses":"S2 · S3","en":"ALLOTROPES: one glows and burns, the other is safe enough for a matchbox.","cn":"同素异形体：一个会发光自燃，另一个安全到能放在火柴盒上。"},{"senses":"S4","en":"INFORMATION: phosphate groups give DNA its charge and ATP its energy.","cn":"信息：磷酸基团赋予 DNA 电荷、赋予 ATP 能量。"},{"senses":"S5 · S6","en":"BODY AND FIELD: the same element is bone mineral and the bag of fertiliser.","cn":"身体与田野：同一元素既是骨矿物，也是那袋肥料。"},{"senses":"S7 · S8","en":"EXCESS AND ORIGIN: too much phosphorus ruins a lake, while the name still remembers a star.","cn":"过量与起源：磷太多会毁掉湖泊，而名字仍记着一颗星。"}]},"affixes":{"intro":{"en":"Phosphorus is a Greek compound meaning 'light-bearer', taken into Latin as a star name and then attached to a glowing element.","cn":"phosphorus 是希腊语复合词，意为「带光者」，作为星名进入拉丁语，随后被赋予一种发光的元素。"},"latinIntro":{"en":"Latin phosphorus kept the Greek meaning, and later chemistry built phosphoric, phosphorous, phosphate and phosphide on the same stem.","cn":"拉丁 phosphorus 保留了希腊词义，后来的化学又用同一词干造出 phosphoric、phosphorous、phosphate 与 phosphide。"},"items":[{"word":"phosphorus","structure":"Greek phos (light) + phoros (bearing)","meaning":"the element; literally 'light-bearer'","meaningCN":"该元素；字面义「带光者」","example":"Phosphorus glows faintly as it oxidises.","exampleCN":"磷氧化时会发出微光。"},{"word":"phosphate","structure":"phosphor- + -ate (salt suffix)","meaning":"a salt or ester of phosphoric acid","meaningCN":"磷酸的盐或酯","example":"Phosphate fertiliser raises crop yields.","exampleCN":"磷肥提高作物产量。"},{"word":"phosphoric","structure":"phosphor- + -ic (higher oxidation)","meaning":"relating to phosphoric acid","meaningCN":"与磷酸有关的","example":"Phosphoric acid gives cola its tang.","exampleCN":"磷酸给可乐带来酸味。"},{"word":"phosphorous","structure":"phosphor- + -ous (lower oxidation)","meaning":"relating to the lower oxide; also glowing","meaningCN":"与低价氧化物有关；也指发光的","example":"Phosphorous acid is a reducing agent.","exampleCN":"亚磷酸是一种还原剂。"},{"word":"phosphide","structure":"phosphor- + -ide (compound suffix)","meaning":"a compound of phosphorus with a metal","meaningCN":"磷与金属形成的化合物","example":"Aluminium phosphide is used as a fumigant.","exampleCN":"磷化铝被用作熏蒸剂。"},{"word":"phosphorylate","structure":"phosphor- + -yl + -ate (verb)","meaning":"to attach a phosphate group to a molecule","meaningCN":"把磷酸基团连接到分子上","example":"Kinases phosphorylate target proteins.","exampleCN":"激酶使靶蛋白磷酸化。"},{"word":"phospholipid","structure":"phospho- + lipid (Greek lipos, fat)","meaning":"a fat containing a phosphate group","meaningCN":"含磷酸基团的脂类","example":"Cell membranes are built of phospholipids.","exampleCN":"细胞膜由磷脂构成。"},{"word":"phosphorescence","structure":"phosphor- + -escence (process)","meaning":"slow glowing after exposure to light","meaningCN":"受光照射后缓慢发光","example":"The paint showed weak phosphorescence.","exampleCN":"这种涂料显示出微弱的磷光。"}],"latinEntries":[{"word":"phosphorus","structure":"phosphorus, phosphori (m., second declension; from Greek phosphoros)","meaning":"the morning star; light-bearer","meaningCN":"启明星；带光者"},{"word":"phos","structure":"Greek phos, photos (n., third declension)","meaning":"light","meaningCN":"光"},{"word":"pherein","structure":"Greek pherein (verb, to carry)","meaning":"to bear, to carry","meaningCN":"携带、背负"}]}},{"word":"phosphate","ipa_uk":"/ˈfɒsfeɪt/","ipa_us":"/ˈfɑːsfeɪt/","definition_zh":"磷酸盐；磷酸根；磷酸酯","definition_en":"a salt or ester of phosphoric acid, containing the phosphate group PO4","core_image":"一袋白色颗粒肥料溶进土壤，旁边 DNA 双螺旋的骨架被标成亮色","scene":"The detergent was banned because its phosphate load fed algal blooms in the river.","sceneCN":"这里 phosphate 指「洗涤剂中的磷酸盐」（第 3 个义项：含磷洗涤剂带来的富营养化问题）；磷酸盐随污水进入河流，成了藻华的养料，因此被禁用。图中可辨识物件：洗衣粉盒、排污口、河面藻膜、监测采样瓶。","pos":[{"tag":"n.","zh":"磷酸盐；磷酸根；磷酸酯（化学语境可数，可加 -s）"}],"collocations":[{"phrase":"phosphate group","zh":"磷酸基团"},{"phrase":"phosphate rock","zh":"磷矿石"},{"phrase":"phosphate fertilizer","zh":"磷肥"},{"phrase":"calcium phosphate","zh":"磷酸钙"},{"phrase":"phosphate buffer","zh":"磷酸缓冲液"},{"phrase":"total phosphate","zh":"总磷"}],"forms":[{"label":"复数","form":"phosphates（指多种磷酸盐或酯时使用）"},{"label":"化学式","form":"PO₄³⁻（磷酸根）"},{"label":"形容词形式","form":"phosphatic（含磷酸盐的，多用于岩石与矿床）"},{"label":"相关形容词","form":"phosphoric（磷酸的）；phosphorous（亚磷的）"},{"label":"相关动词","form":"phosphorylate（使磷酸化）"}],"derivatives":[{"word":"phosphorus","pos":"n.","zh":"磷"},{"word":"phosphoric","pos":"adj.","zh":"磷酸的"},{"word":"phosphatic","pos":"adj.","zh":"含磷酸盐的"},{"word":"phosphorylate","pos":"v.","zh":"使磷酸化"},{"word":"phospholipid","pos":"n.","zh":"磷脂"},{"word":"superphosphate","pos":"n.","zh":"过磷酸钙（一种磷肥）"}],"senses":[{"no":"01","title":"A salt of phosphoric acid","titleCN":"磷酸盐：磷酸与碱结合的产物","definition":"a compound formed from phosphoric acid and a base, containing the PO4 group","definitionCN":"由磷酸与碱形成的化合物，含 PO₄ 基团","example":"Sodium phosphate is a common laboratory buffer salt.","exampleCN":"磷酸钠是实验室常用的缓冲盐。","why":"The suffix -ate marks salts of an -ic acid, so phosphate is to phosphoric acid what sulfate is to sulfuric acid.","whyCN":"后缀 -ate 标记「-ic 酸」的盐，因此 phosphate 之于磷酸，正如 sulfate 之于硫酸。"},{"no":"02","title":"Phosphate fertiliser","titleCN":"磷肥：农业三大养分之一的施用形态","definition":"the form in which phosphorus is mined and applied to fields, from rock phosphate to superphosphate","definitionCN":"磷被开采并施入田地的形态，从磷矿石到过磷酸钙","example":"The farm spread phosphate before sowing the wheat.","exampleCN":"农场在播麦前施用了磷肥。","why":"Plants take up phosphorus as phosphate ions, so the compound name became the agricultural name.","whyCN":"植物以磷酸根离子形式吸收磷，因此化合物名成了农业用名。"},{"no":"03","title":"Detergents and algal blooms","titleCN":"洗涤剂中的磷酸盐：富营养化的推手","definition":"the phosphate added to laundry and dishwashing products, later restricted because it overfeeds algae in rivers and lakes","definitionCN":"加入洗衣与洗碗产品的磷酸盐，后因使河湖藻类疯长而受限制","example":"Many countries banned phosphate detergents to protect freshwater lakes.","exampleCN":"许多国家禁用含磷洗涤剂以保护淡水湖。","why":"A cleaning additive became an environmental villain, so the word now appears in pollution law as well as in chemistry.","whyCN":"一种清洁助剂成了环境祸首，因此这个词既出现在化学里，也出现在污染法规里。"},{"no":"04","title":"The group in DNA and ATP","titleCN":"核酸与能量分子中的磷酸基团","definition":"the phosphate group that links the sugar backbone of DNA and carries the high-energy bonds of ATP","definitionCN":"连接 DNA 糖骨架、并承载 ATP 高能键的磷酸基团","example":"Each nucleotide in DNA carries one phosphate group.","exampleCN":"DNA 中每个核苷酸带一个磷酸基团。","why":"Biochemistry names the group rather than the whole salt, because the group is what transfers energy and charge.","whyCN":"生物化学命名的是基团而不是整盐，因为真正传递能量与电荷的是基团。"},{"no":"05","title":"Water quality testing","titleCN":"水质监测：总磷与正磷酸盐指标","definition":"in water analysis, the measured amount of dissolved phosphate, reported as total phosphorus or orthophosphate","definitionCN":"水质分析中测得的溶解磷酸盐量，以总磷或正磷酸盐计","example":"The lab reported total phosphate above the permitted level.","exampleCN":"实验室报告总磷超过允许水平。","why":"Because phosphate is the usual limiting nutrient, its concentration is the standard measure of a lake's risk.","whyCN":"由于磷酸盐通常是限制性养分，其浓度成了判断湖泊风险的标准指标。"},{"no":"06","title":"Food additives","titleCN":"食品添加剂：保水、乳化与稳定","definition":"phosphate salts used in processed meat, cheese and bakery products to hold water and stabilise texture","definitionCN":"用于加工肉、奶酪与烘焙品的磷酸盐，起保水与稳定质地的作用","example":"Phosphates keep the ham moist during cooking.","exampleCN":"磷酸盐让火腿在烹煮时保持水分。","why":"Food technology borrows the salt for its chemical behaviour, so a lab compound appears on ingredient lists.","whyCN":"食品工艺借用这种盐的化学行为，于是实验室化合物出现在配料表上。"},{"no":"07","title":"Clinical phosphate","titleCN":"临床磷：缓冲液与结合剂","definition":"in medicine, phosphate used as an intravenous buffer or as a binder that lowers absorbed phosphorus in kidney disease","definitionCN":"医学中用作静脉缓冲液，或作为结合剂减少肾病患者的磷吸收","example":"The patient takes a phosphate binder with every meal.","exampleCN":"患者每餐都服用一种磷结合剂。","why":"When kidneys fail, phosphate accumulates, so treatment names it as both a buffer and a target.","whyCN":"肾功能衰竭时磷酸盐会累积，因此治疗中它既是缓冲液，也是被控制的目标。"},{"no":"08","title":"Phosphate rock and mining","titleCN":"磷矿：不可再生的磷资源","definition":"the mineral deposit of calcium phosphate that is mined and processed into fertiliser and industrial chemicals","definitionCN":"以磷酸钙为主的矿床，经开采加工成肥料与工业化学品","example":"The country holds some of the world's largest phosphate reserves.","exampleCN":"该国拥有世界上最大的几处磷矿储量。","why":"Because phosphorus cannot be replaced by other elements in farming, the ore body is treated as a strategic resource.","whyCN":"由于农业中磷无法被其他元素替代，这种矿体被视为战略资源。"}],"etymology":{"intro":{"en":"Phosphate is a French chemical coinage of the 1780s: the stem of phosphorus plus -ate, the ending for salts of -ic acids.","cn":"phosphate 是 1780 年代的法语化学造词：phosphorus 的词干加 -ate，即「-ic 酸之盐」的词尾。"},"items":[{"era":"GREEK LIGHT-BEARER","en":"Phosphorus came from Greek phosphoros 'light-bearer', a name for the morning star, and was applied to the glowing element in the seventeenth century.","cn":"phosphorus 出自希腊 phosphoros「带光者」，本是启明星之名，17 世纪被用于那种发光的元素。"},{"era":"LATIN SALT NAMING","en":"Chemists used Latin endings to classify salts: -ate for the salt of an -ic acid and -ite for the salt of an -ous acid. Phosphate and phosphite follow that pattern.","cn":"化学家用拉丁词尾给盐分类：-ate 表示 -ic 酸的盐，-ite 表示 -ous 酸的盐。phosphate 与 phosphite 沿用这一模式。"},{"era":"FRENCH COINAGE","en":"French phosphate appears in the 1780s in the writings of Lavoisier and his colleagues, as the new nomenclature replaced older names such as 'phosphoric salt'.","cn":"法语 phosphate 出现在 1780 年代拉瓦锡及其同僚的著作中，当时新命名法取代了「磷酸盐」这类旧称。"},{"era":"FERTILISER AGE","en":"In the nineteenth century guano and phosphate rock became industrial fertiliser sources, and the word moved from the laboratory to the farm.","cn":"19 世纪鸟粪石与磷矿石成为工业肥料来源，这个词便从实验室走进农田。"},{"era":"DETERGENT ERA","en":"Twentieth-century detergents added phosphates for cleaning power, and later bans made the word familiar to the public.","cn":"20 世纪的洗涤剂为增强去污力加入磷酸盐，后来的禁用令使这个词为公众熟知。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertainty: the exact first English citation of phosphate is uncertain; the earliest uses are in translations of French chemical texts, and the precise translator is unknown.","cn":"来源不确定：phosphate 的英语首见确切书证年代存疑；最早用例出现在法语化学文献的译本中，具体译者不详。"}]},"similar":{"note":{"en":"The first group holds words with the same phosphor- stem that mean quite different things; the second holds other nutrient anions that are easy to substitute in speech.","cn":"第一组是同出 phosphor- 词干但含义很不同的词；第二组是口语中容易互相替代的其他养分阴离子。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"phosphide","ipa":"/ˈfɒsfaɪd/","tag":"metal compound","definition":"A compound of phosphorus with a metal, such as aluminium phosphide. It contains no oxygen, unlike phosphate.","definitionCN":"磷与金属形成的化合物，如磷化铝。与磷酸盐不同，它不含氧。"},{"word":"phosphite","ipa":"/ˈfɒsfaɪt/","tag":"lower oxidation salt","definition":"A salt of phosphorous acid, with phosphorus in a lower oxidation state than in phosphate.","definitionCN":"亚磷酸的盐，其中磷的氧化态低于磷酸盐。"},{"word":"phosphorus","ipa":"/ˈfɒsfərəs/","tag":"the element","definition":"The element itself. Phosphate is the compound plants and industry actually handle.","definitionCN":"元素本身。phosphate 才是植物与工业实际处理的化合物。"}]},{"heading":"NEAR MEANING","entries":[{"word":"nitrate","ipa":"/ˈnaɪtreɪt/","tag":"the other limiting nutrient","definition":"The NO3 salt of nitric acid. Freshwater is often phosphorus-limited, while coastal water is often nitrogen-limited, so the two are compared constantly.","definitionCN":"硝酸的 NO₃ 盐。淡水常受磷限制，近海水域常受氮限制，因此二者常被对照。"},{"word":"sulfate","ipa":"/ˈsʌlfeɪt/","tag":"same ending, different element","definition":"The SO4 salt of sulfuric acid. It shares the -ate ending and the salt behaviour but carries sulfur instead of phosphorus.","definitionCN":"硫酸的 SO₄ 盐。它与磷酸盐共享 -ate 词尾与盐的行为，但携带的是硫而非磷。"},{"word":"carbonate","ipa":"/ˈkɑːbəneɪt/","tag":"the carbon salt","definition":"The CO3 salt of carbonic acid. It is what limestone and shells are made of, and it buffers water much as phosphate does.","definitionCN":"碳酸的 CO₃ 盐。石灰石与贝壳由它构成，它像磷酸盐一样对水起缓冲作用。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"phosphorus + -ate: the salt of phosphoric acid, parallel to sulfate and nitrate.","cn":"phosphorus + -ate：磷酸的盐，与 sulfate、nitrate 同构。"},{"en":"The family runs phosphorus, phosphoric, phosphatic, phosphide, phosphorylate and phospholipid.","cn":"同族词包括 phosphorus、phosphoric、phosphatic、phosphide、phosphorylate、phospholipid。"},{"en":"Fixed phrases mark the fields: phosphate rock, phosphate fertilizer, phosphate group, total phosphate.","cn":"固定搭配标出领域：磷矿石、磷肥、磷酸基团、总磷。"},{"en":"DNA's backbone alternates sugar and phosphate, which is why the helix is negatively charged.","cn":"DNA 骨架由糖与磷酸交替构成，这也是螺旋带负电的原因。"},{"en":"Bans on phosphate detergents came from lakes turning green.","cn":"对含磷洗涤剂的禁令，源自湖泊变绿。"}],"abstract":[{"en":"Picture white fertiliser prills dissolving into soil and a root hair reaching toward them.","cn":"想象白色肥料颗粒溶进土壤，一根根毛朝它们伸过去。"},{"en":"Picture a spiral ladder whose rails are linked by small glowing phosphate joints.","cn":"想象一架螺旋梯，两侧梯轨由一个个发亮的磷酸接头相连。"},{"en":"Picture a river surface closing over with green scum downstream of a drain.","cn":"想象排水口下游的河面被绿色浮沫封住。"}]},"examples":[{"en":"Calcium phosphate is the main mineral of bone and teeth.","cn":"磷酸钙是骨骼与牙齿的主要矿物。"},{"en":"The soil test showed adequate phosphate for the coming season.","cn":"土壤检测显示下一季的磷已足够。"},{"en":"Phosphate buffers hold the pH steady during the assay.","cn":"磷酸缓冲液在检测过程中维持 pH 稳定。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「phosphor（磷）+ ate（盐）」——磷形成的盐 → phosphate 磷酸盐","word":"phosphate"},"root":"希腊 phos「光」+ pherein「携带」→ phosphorus；再加拉丁盐类词尾 -ate → phosphate。","sensesIntro":{"en":"Eight senses follow one salt from chemistry to fertiliser, detergent pollution, DNA, water testing, food, medicine and the mine.","cn":"八个义项让同一种盐从化学走进肥料、洗涤剂污染、DNA、水质监测、食品、医学与矿山。"},"semanticMap":{"core":{"en":"CORE IMAGE: white fertiliser grains meeting a glowing DNA backbone.","cn":"核心意象：白色肥料颗粒与发亮的 DNA 骨架相遇。"},"chain":["PHOSPHORIC SALT","FEED THE CROP","FOUL THE LAKE","LINK THE GENE","MEASURE THE WATER","PRESERVE THE FOOD"],"branches":[{"senses":"S1","en":"CHEMISTRY: -ate marks a salt, so phosphate is a compound and not the element.","cn":"化学：-ate 标记盐，因此 phosphate 是化合物而不是元素。"},{"senses":"S2 · S8","en":"AGRICULTURE: the same salt is spread on fields and dug out of rock.","cn":"农业：同一种盐既被施进田里，也被从岩石中挖出。"},{"senses":"S3 · S5","en":"WATER: a cleaning additive becomes a pollutant and then a monitored number.","cn":"水：一种清洁助剂变成污染物，再变成一个被监测的数字。"},{"senses":"S4","en":"LIFE: the phosphate group carries charge and energy in DNA and ATP.","cn":"生命：磷酸基团在 DNA 与 ATP 中承载电荷与能量。"},{"senses":"S6 · S7","en":"INDUSTRY AND MEDICINE: the same salt stabilises food and binds phosphorus in patients.","cn":"工业与医学：同一种盐既稳定食品，也在患者体内结合磷。"}]},"affixes":{"intro":{"en":"Phosphate is a Greek-derived element stem with a Latin salt ending, the pattern that organises inorganic chemistry vocabulary.","cn":"phosphate 是一个源自希腊的元素词干加拉丁盐类词尾，这正是组织无机化学词汇的模式。"},"latinIntro":{"en":"Latin -atus supplied the salt ending -ate, while the stem came from Greek phosphoros through Latin phosphorus.","cn":"拉丁 -atus 提供了盐类词尾 -ate，词干则经拉丁 phosphorus 来自希腊 phosphoros。"},"items":[{"word":"phosphate","structure":"phosphor- + -ate (salt of an -ic acid)","meaning":"a salt or ester of phosphoric acid","meaningCN":"磷酸的盐或酯","example":"Phosphate levels in the river doubled.","exampleCN":"河水的磷酸盐浓度翻了一倍。"},{"word":"phosphorus","structure":"Greek phos + phoros (light-bearing)","meaning":"element 15","meaningCN":"15 号元素","example":"Phosphorus is mined as phosphate rock.","exampleCN":"磷以磷矿石形式开采。"},{"word":"phosphoric","structure":"phosphor- + -ic","meaning":"relating to the higher acid of phosphorus","meaningCN":"与磷的高价酸有关","example":"Phosphoric acid is used in rust removal.","exampleCN":"磷酸用于除锈。"},{"word":"phosphite","structure":"phosphor- + -ite (salt of an -ous acid)","meaning":"a salt of phosphorous acid","meaningCN":"亚磷酸的盐","example":"Phosphite is a plant fungicide.","exampleCN":"亚磷酸盐是一种植物杀菌剂。"},{"word":"phosphide","structure":"phosphor- + -ide","meaning":"a binary compound with a metal","meaningCN":"与金属形成的二元化合物","example":"Metal phosphides react with water.","exampleCN":"金属磷化物遇水反应。"},{"word":"superphosphate","structure":"super- + phosphate","meaning":"a concentrated phosphate fertiliser","meaningCN":"一种浓缩磷肥","example":"Superphosphate is made by treating rock with acid.","exampleCN":"过磷酸钙由矿石经酸处理制得。"},{"word":"phosphorylate","structure":"phosphor- + -yl + -ate","meaning":"to attach a phosphate group","meaningCN":"连接一个磷酸基团","example":"The enzyme phosphorylates the sugar.","exampleCN":"该酶使糖磷酸化。"},{"word":"phospholipid","structure":"phospho- + lipid","meaning":"a lipid carrying a phosphate group","meaningCN":"带磷酸基团的脂类","example":"Phospholipids form the cell membrane.","exampleCN":"磷脂构成细胞膜。"},{"word":"sulfate","structure":"sulfur + -ate","meaning":"the parallel salt of sulfuric acid","meaningCN":"硫酸的对应盐类","example":"Sulfate and phosphate behave alike in water.","exampleCN":"硫酸盐与磷酸盐在水中行为相似。"}],"latinEntries":[{"word":"phosphorus","structure":"phosphorus, phosphori (m., second declension)","meaning":"morning star; the element","meaningCN":"启明星；该元素"},{"word":"-atus","structure":"-atus, -a, -um (adjective and participle ending)","meaning":"provided with, made into","meaningCN":"具有、被做成（构成盐名的来源）"},{"word":"phosphas","structure":"phosphas, phosphatis (m., New Latin, third declension)","meaning":"phosphate","meaningCN":"磷酸盐"}]}},{"word":"mineral","ipa_uk":"/ˈmɪnərəl/","ipa_us":"/ˈmɪnərəl/","definition_zh":"矿物；矿物质；（营养）无机盐","definition_en":"a naturally occurring inorganic solid with a definite chemical composition and structure, and by extension such substances in nutrition","core_image":"一块带晶面的矿石放在木托盘上，旁边一小堆白色晶体盐","scene":"The sample was a dark mineral with a metallic lustre, harder than glass.","sceneCN":"这里 mineral 指「矿物」（第 1 个义项：天然产出的无机固体，有确定成分与结构）；它呈深色、带金属光泽，硬度超过玻璃。图中可辨识物件：矿石标本、晶面、木托盘、硬度测试片。","pos":[{"tag":"n.","zh":"矿物；矿物质；（复数）无机养分、矿质元素"},{"tag":"adj.","zh":"矿物的；含矿物的（如 mineral water、mineral resources）"}],"collocations":[{"phrase":"mineral water","zh":"矿泉水"},{"phrase":"mineral resources","zh":"矿产资源"},{"phrase":"mineral deposit","zh":"矿床"},{"phrase":"essential minerals","zh":"必需矿物质"},{"phrase":"mineral extraction","zh":"矿物开采"},{"phrase":"mineral oil","zh":"矿物油"}],"forms":[{"label":"复数","form":"minerals（矿物；矿物质）"},{"label":"形容词形式","form":"mineral（作定语，如 mineral water）"},{"label":"副词形式","form":"mineralogically（从矿物学角度）"},{"label":"动词形式","form":"mineralize（使矿化）"},{"label":"学科名词","form":"mineralogy（矿物学）"}],"derivatives":[{"word":"mineralize","pos":"v.","zh":"使矿化；使变成矿物"},{"word":"mineralization","pos":"n.","zh":"矿化；成矿作用"},{"word":"mineralogy","pos":"n.","zh":"矿物学"},{"word":"mineralogist","pos":"n.","zh":"矿物学家"},{"word":"mineralogical","pos":"adj.","zh":"矿物学的"}],"senses":[{"no":"01","title":"A natural inorganic solid","titleCN":"矿物：天然产出的无机固体","definition":"a naturally formed inorganic solid with a definite chemical composition and a characteristic crystal structure","definitionCN":"天然形成的无机固体，具有确定的化学成分与特征晶体结构","example":"Quartz is a mineral made of silicon and oxygen.","exampleCN":"石英是由硅与氧构成的矿物。","why":"Geology defines minerals by four tests at once: natural, inorganic, definite composition, ordered structure.","whyCN":"地质学同时用四条标准界定矿物：天然、无机、成分确定、结构有序。"},{"no":"02","title":"Dietary minerals","titleCN":"矿物质养分：人体必需的无机元素","definition":"in nutrition, the inorganic elements such as calcium, iron and zinc that the body needs in small amounts","definitionCN":"营养学中指钙、铁、锌等人体少量必需的无机元素","example":"Leafy greens supply calcium and other minerals.","exampleCN":"绿叶蔬菜提供钙与其他矿物质。","why":"Nutrition borrowed the geology word because these nutrients arrive as mineral salts rather than as carbon compounds.","whyCN":"营养学借用地质学词汇，因为这些养分以矿物盐而非碳化合物的形式到来。"},{"no":"03","title":"Mineral water and springs","titleCN":"矿泉水：含溶解矿物质的天然水","definition":"water drawn from a spring and containing dissolved mineral salts, often sold as a drink","definitionCN":"取自泉水、含溶解矿物盐的水，常作为饮品出售","example":"The hotel serves local mineral water from the valley spring.","exampleCN":"旅馆供应来自山谷泉眼的当地矿泉水。","why":"The adjective simply says what the water contains, and the phrase mineral water then became a product category.","whyCN":"这个形容词只是说明水含有什么，而「矿泉水」这一短语随后成了一个产品类别。"},{"no":"04","title":"Mineral resources and rights","titleCN":"矿产资源与矿权：法律经济意义上的矿物","definition":"in law and economics, the valuable inorganic substances in the ground and the rights to extract them","definitionCN":"法律与经济中指地下有价值的无机物质及开采它的权利","example":"The state owns all mineral rights beneath private land.","exampleCN":"私有土地之下的一切矿权归国家所有。","why":"Because extraction is worth money, the word shifts from a scientific category to a legal asset.","whyCN":"由于开采具有经济价值，这个词从科学分类转成了法律资产。"},{"no":"05","title":"Rock-forming minerals","titleCN":"造岩矿物：组成岩石的基本单元","definition":"in petrology, the individual mineral species whose grains make up a rock","definitionCN":"岩石学中指构成岩石颗粒的各个矿物种类","example":"Granite is a rock made of quartz, feldspar and mica minerals.","exampleCN":"花岗岩是由石英、长石与云母等矿物构成的岩石。","why":"Petrologists must name the parts as well as the whole, so mineral is the countable unit inside an uncountable rock.","whyCN":"岩石学家既要命名整体也要命名部件，因此 mineral 是岩石这个不可数整体中的可数单元。"},{"no":"06","title":"Ore minerals","titleCN":"矿石矿物：值得开采提炼的矿物","definition":"the mineral in a deposit that contains a metal or other element valuable enough to extract","definitionCN":"矿床中含金属或其他元素、值得提炼的矿物","example":"Chalcopyrite is the main ore mineral of copper.","exampleCN":"黄铜矿是铜的主要矿石矿物。","why":"Mining distinguishes the valuable grains from the worthless gangue, so ore mineral is a commercial as well as a geological label.","whyCN":"采矿把有价值的颗粒与无价值的脉石分开，因此矿石矿物既是地质标签也是商业标签。"},{"no":"07","title":"The mineral kingdom","titleCN":"矿物界：旧自然分类中的第三界","definition":"in older natural history, the third division of the natural world beside the animal and vegetable kingdoms","definitionCN":"旧自然史中指与动物界、植物界并列的自然界第三界","example":"Old textbooks divided nature into animal, vegetable and mineral kingdoms.","exampleCN":"旧教科书把自然分为动物界、植物界与矿物界。","why":"Before modern chemistry, classifying by kingdom was the easiest way to place lifeless matter.","whyCN":"在现代化学之前，按「界」分类是把无生命物质归位的最简便方法。"},{"no":"08","title":"Specimens and gems","titleCN":"矿物标本与宝石：收藏与鉴赏对象","definition":"a cut or collected mineral specimen valued for colour, crystal form or rarity","definitionCN":"因颜色、晶形或稀有性而被切磨或收藏的矿物标本","example":"The museum displays minerals from old copper mines.","exampleCN":"博物馆展出旧铜矿出产的矿物标本。","why":"Collectors treat the same scientific object as an aesthetic one, so the word also names what sits in a display case.","whyCN":"收藏者把同一个科学对象当作审美对象，因此这个词也指展柜里的东西。"}],"etymology":{"intro":{"en":"Mineral comes from Medieval Latin minerale, from minera 'ore, mine'. The deeper origin of minera is disputed and may be Celtic.","cn":"mineral 出自中世纪拉丁 minerale，源自 minera「矿石、矿」。minera 的更深来源有争议，可能来自凯尔特语。"},"items":[{"era":"MEDIEVAL LATIN MINERA","en":"Medieval Latin minera meant 'ore, mine, pit'. It appears in mining and metallurgical texts from the late Middle Ages.","cn":"中世纪拉丁 minera 意为「矿石、矿、矿坑」，见于中世纪末的采矿与冶金文献。"},{"era":"CELTIC HYPOTHESIS","en":"Many etymologists link minera to a Celtic root for ore, seen in Welsh mwyn 'ore'. This link is generally accepted but not proved.","cn":"许多词源学家把 minera 与表示矿石的凯尔特词根联系起来，可见威尔士语 mwyn「矿石」。这一联系被普遍接受，但未经证实。"},{"era":"MINARE ALTERNATIVE","en":"Others derive it from Latin minari 'to jut, to project', because ore bodies stand out from the rock. This explanation is less favoured.","cn":"另有人把它追溯到拉丁 minari「突出、伸出」，因为矿体在岩石中显眼。这一解释较少被采纳。"},{"era":"FRENCH MINERAL","en":"Old French mineral passed into English in the late Middle Ages, first as an adjective for substances dug from the earth.","cn":"古法语 mineral 在中世纪末进入英语，最初作形容词，指从地下挖出的物质。"},{"era":"SCIENCE AND NUTRITION","en":"Chemistry fixed the modern geological definition in the nineteenth century, and nutrition later borrowed the word for dietary elements.","cn":"化学在 19 世纪确立了现代地质学定义，营养学后来又借这个词指膳食元素。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertainty: the origin of minera is unresolved; both the Celtic and the Latin minari explanations are hypotheses, and the first English date is uncertain.","cn":"来源不确定：minera 的来源尚无定论；凯尔特说与拉丁 minari 说都属假说，英语首见年代亦存疑。"}]},"similar":{"note":{"en":"The first group holds words built on mineral that name studies or processes rather than the substance; the second holds earth materials that are often called minerals loosely.","cn":"第一组是由 mineral 构成、却指学科或过程的词；第二组是常被宽泛称作矿物的地球材料。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"mineralogy","ipa":"/ˌmɪnəˈrælədʒi/","tag":"the science","definition":"The scientific study of minerals, their composition, structure and classification. It is a discipline, not a substance.","definitionCN":"研究矿物的成分、结构与分类的学科。它是一门学问，不是物质。"},{"word":"mineralize","ipa":"/ˈmɪnərəlaɪz/","tag":"the verb","definition":"To convert organic matter into mineral form, or to impregnate something with minerals.","definitionCN":"把有机物转化为矿物形态，或用矿物浸染某物。"},{"word":"mineralized","ipa":"/ˈmɪnərəlaɪzd/","tag":"the adjective","definition":"Describes something that has been converted into or impregnated with mineral matter, such as mineralized bone.","definitionCN":"描述已被转化为矿物或被矿物浸染的事物，如矿化骨。"}]},{"heading":"NEAR MEANING","entries":[{"word":"rock","ipa":"/rɒk/","tag":"the aggregate","definition":"A natural aggregate of one or more minerals. A rock is the whole mixture; a mineral is one ingredient.","definitionCN":"由一种或多种矿物组成的天然集合体。岩石是整体混合物，矿物是其中一种成分。"},{"word":"crystal","ipa":"/ˈkrɪstl/","tag":"the ordered form","definition":"A solid whose atoms are arranged in a repeating pattern. Many minerals form crystals, but glass is a solid without that order.","definitionCN":"原子呈重复排列的固体。许多矿物形成晶体，但玻璃是缺乏这种有序性的固体。"},{"word":"ore","ipa":"/ɔː/","tag":"the profitable rock","definition":"Rock or mineral material rich enough in a metal to be mined at a profit. All ore contains minerals, but most minerals are not ore.","definitionCN":"金属含量高到值得开采获利的岩石或矿物材料。矿石都含矿物，但多数矿物并非矿石。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"minera 'ore' + -ale: what comes out of a mine.","cn":"minera「矿石」+ -ale：从矿里出来的东西。"},{"en":"The family runs mineralize, mineralization, mineralogy, mineralogist and mineralogical.","cn":"同族词包括 mineralize、mineralization、mineralogy、mineralogist、mineralogical。"},{"en":"Fixed phrases mark the fields: mineral water, mineral resources, mineral deposit, essential minerals.","cn":"固定搭配标出领域：矿泉水、矿产资源、矿床、必需矿物质。"},{"en":"A rock is a mixture; a mineral is one ingredient with a fixed formula.","cn":"岩石是混合物；矿物是成分固定的一种配料。"},{"en":"Nutrition calls calcium and iron minerals because they arrive as inorganic salts.","cn":"营养学把钙与铁称为矿物质，因为它们以无机盐形式到来。"}],"abstract":[{"en":"Picture a cut stone with flat shiny faces lying on a wooden tray.","cn":"想象一块切开的石头，平面闪亮，躺在木托盘上。"},{"en":"Picture a glass of still water with a faint mineral taste and a spring behind it.","cn":"想象一杯静水，带一点矿物味，背后是一眼泉。"},{"en":"Picture an old chart dividing the world into animal, vegetable and mineral bands.","cn":"想象一张旧图把世界分成动物、植物与矿物三条带。"}]},"examples":[{"en":"The region is rich in mineral deposits but short of water.","cn":"该地区矿产丰富，却缺水。"},{"en":"Iron is a mineral that many people do not get enough of.","cn":"铁是许多人摄入不足的一种矿物质。"},{"en":"The geologist identified the green mineral as malachite.","cn":"地质学家把那块绿色矿物鉴定为孔雀石。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「mine（矿）+ ral」——从矿里挖出来的东西 → mineral 矿物","word":"mineral"},"root":"中世纪拉丁 minera「矿石、矿」→ minerale → 古法语 mineral → 英语 mineral。","sensesIntro":{"en":"Eight senses follow one substance from a crystal in rock to a nutrient in food, a product on a shelf, a legal right, an ore, an old kingdom and a museum specimen.","cn":"八个义项让同一种物质从岩石中的晶体走到食物里的养分、货架上的产品、法律上的权利、矿石、旧时的「界」与博物馆标本。"},"semanticMap":{"core":{"en":"CORE IMAGE: a faceted stone on a tray beside a heap of white salt crystals.","cn":"核心意象：木托盘上的晶面矿石，旁边一小堆白色盐晶。"},"chain":["DUG FROM ROCK","ORDERED SOLID","ELEMENT IN FOOD","DISSOLVED IN WATER","LEGAL ASSET","SPECIMEN ON SHOW"],"branches":[{"senses":"S1 · S5","en":"GEOLOGY: the definition needs nature, no life, a fixed formula and an ordered structure.","cn":"地质：定义需要天然、无生命、成分固定与结构有序四条。"},{"senses":"S2","en":"NUTRITION: the same word names the inorganic elements the body needs.","cn":"营养：同一个词指身体所需的无机元素。"},{"senses":"S3","en":"PRODUCT: dissolved salts turn spring water into a branded drink.","cn":"产品：溶解的盐把泉水变成有品牌的饮品。"},{"senses":"S4 · S6","en":"VALUE: rights underground and ore in the vein both measure the word in money.","cn":"价值：地下的权利与矿脉中的矿石，都用钱来衡量这个词。"},{"senses":"S7 · S8","en":"CLASSIFICATION AND BEAUTY: an old kingdom and a display case are two ends of the same label.","cn":"分类与美：旧时的「界」与展柜，是同一标签的两端。"}]},"affixes":{"intro":{"en":"Mineral is a Medieval Latin noun ending in -ale, the suffix that turns a stem into a thing name, later used as an adjective without change.","cn":"mineral 是带 -ale 的中世纪拉丁名词，该后缀把词干变成事物名，后来它又原形用作形容词。"},"latinIntro":{"en":"Medieval Latin minera supplied the stem and minerale the noun; the -alis ending later produced English mineralogy through a different path.","cn":"中世纪拉丁 minera 提供词干、minerale 提供名词；-alis 词尾后来经另一条路径产生了英语 mineralogy。"},"items":[{"word":"mineral","structure":"minera + -ale (noun suffix)","meaning":"a natural inorganic solid; also an adjective","meaningCN":"天然无机固体；也作形容词","example":"The mineral is harder than steel.","exampleCN":"这种矿物比钢还硬。"},{"word":"mineralize","structure":"mineral + -ize (to make)","meaning":"to turn into mineral form","meaningCN":"使转化为矿物形态","example":"Soil microbes mineralize the organic matter.","exampleCN":"土壤微生物把有机质矿化。"},{"word":"mineralization","structure":"mineralize + -ation","meaning":"the process of becoming mineral","meaningCN":"变成矿物的过程","example":"Mineralization preserved the fossil.","exampleCN":"矿化作用保存了这具化石。"},{"word":"mineralogy","structure":"mineral + -logy (study)","meaning":"the science of minerals","meaningCN":"研究矿物的学科","example":"Mineralogy classifies crystals by symmetry.","exampleCN":"矿物学按对称性给晶体分类。"},{"word":"mineralogist","structure":"mineralogy + -ist (practitioner)","meaning":"a specialist in minerals","meaningCN":"矿物学专家","example":"The mineralogist identified the specimen.","exampleCN":"矿物学家鉴定了这块标本。"},{"word":"mineralogical","structure":"mineralogy + -ical","meaning":"relating to mineralogy","meaningCN":"与矿物学有关的","example":"The mineralogical survey mapped the district.","exampleCN":"矿物学调查绘制了该区地图。"},{"word":"demineralize","structure":"de- (remove) + mineralize","meaning":"to remove minerals from water or bone","meaningCN":"从水或骨中去除矿物质","example":"The filter demineralizes the tap water.","exampleCN":"该过滤器去除自来水中的矿物质。"},{"word":"miner","structure":"mine + -er (agent noun)","meaning":"a person who works in a mine","meaningCN":"在矿上工作的人","example":"The miners went down at dawn.","exampleCN":"矿工们在黎明下井。"}],"latinEntries":[{"word":"minera","structure":"minera, minerae (f., Medieval Latin, first declension)","meaning":"ore, mine","meaningCN":"矿石、矿"},{"word":"minerale","structure":"minerale (n., Medieval Latin, third declension)","meaning":"a thing dug from the earth","meaningCN":"从地下挖出的东西"},{"word":"-ale","structure":"-ale (neuter noun suffix, Medieval Latin)","meaning":"thing associated with","meaningCN":"与……相关之物"}]}},{"word":"mineralization","ipa_uk":"/ˌmɪnərəlaɪˈzeɪʃn/","ipa_us":"/ˌmɪnərələˈzeɪʃn/","definition_zh":"矿化；成矿作用；（水的）矿化度","definition_en":"the process by which organic matter is converted into mineral form, or by which minerals are deposited in rock or tissue","core_image":"一根骨头埋进岩层，逐渐被矿物替换，旁边是一条发亮的矿脉","scene":"The fossil's bone had undergone complete mineralization, so no original tissue remained.","sceneCN":"这里 mineralization 指「矿化取代」（第 1 个义项：有机组织被矿物逐步替换的过程）；骨组织已被矿物完全取代，原有组织不再存在。图中可辨识物件：化石骨、岩层剖面、矿物沉积、放大镜。","pos":[{"tag":"n.","zh":"矿化；成矿作用；矿化度（多作不可数名词）"}],"collocations":[{"phrase":"soil mineralization","zh":"土壤矿化"},{"phrase":"nitrogen mineralization","zh":"氮矿化"},{"phrase":"degree of mineralization","zh":"矿化度"},{"phrase":"ore mineralization","zh":"成矿作用"},{"phrase":"biomineralization","zh":"生物矿化"},{"phrase":"mineralization rate","zh":"矿化速率"}],"forms":[{"label":"不可数用法","form":"mineralization（指过程或程度，一般不加 -s）"},{"label":"动词形式","form":"mineralize（使矿化）"},{"label":"形容词形式","form":"mineralized（已矿化的）"},{"label":"反向过程","form":"demineralization（脱矿）"},{"label":"施动名词","form":"mineralizer（矿化剂；成矿介质）"}],"derivatives":[{"word":"mineralize","pos":"v.","zh":"使矿化；使成矿"},{"word":"mineralized","pos":"adj.","zh":"矿化的"},{"word":"mineral","pos":"n.","zh":"矿物；矿物质"},{"word":"mineralogy","pos":"n.","zh":"矿物学"},{"word":"demineralization","pos":"n.","zh":"脱矿；去矿化"},{"word":"mineralizer","pos":"n.","zh":"矿化剂"}],"senses":[{"no":"01","title":"Replacement by minerals","titleCN":"矿化取代：有机组织被矿物替换","definition":"the process by which minerals replace organic tissue, as in the fossilisation of bone or wood","definitionCN":"矿物替换有机组织的过程，如骨骼或木材的化石化的过程","example":"The wood's cell walls survived only as mineralization.","exampleCN":"木头的细胞壁只以矿化形态保存下来。","why":"Because ground water slowly deposits minerals in the spaces of tissue, the process is named after what fills the space.","whyCN":"由于地下水缓慢地把矿物沉积在组织的空隙里，这个过程便以填入空隙的东西命名。"},{"no":"02","title":"Release of soil nutrients","titleCN":"土壤矿化：有机养分转为可吸收的离子","definition":"in soil science, the conversion of organic nitrogen and phosphorus into inorganic ions that plants can take up","definitionCN":"土壤科学中指把有机氮、有机磷转化为植物可吸收的无机离子","example":"Warm, moist soil speeds up nitrogen mineralization.","exampleCN":"温暖潮湿的土壤会加快氮的矿化。","why":"Here the direction is the reverse of fossilisation: organic matter breaks down into mineral ions instead of being replaced by them.","whyCN":"这里的方向与化石化的方向相反：有机质分解成矿物离子，而不是被矿物替换。"},{"no":"03","title":"Ore formation","titleCN":"成矿作用：金属富集进岩脉","definition":"in economic geology, the concentration of ore minerals into a deposit by hydrothermal or magmatic processes","definitionCN":"经济地质学中指经热液或岩浆过程把矿石矿物富集成矿床","example":"The gold mineralization follows a quartz vein for several kilometres.","exampleCN":"金的成矿作用沿一条石英脉延伸数公里。","why":"Geologists borrow the general 'becoming mineral' word for the specific event that makes a deposit worth mining.","whyCN":"地质学家借用「变成矿物」这一泛称，专指使矿床值得开采的那个事件。"},{"no":"04","title":"Tissue calcification","titleCN":"组织钙化：医学上的矿物沉积","definition":"in medicine, the abnormal deposition of calcium minerals in soft tissue such as arteries or kidneys","definitionCN":"医学中指钙矿物异常沉积在动脉、肾脏等软组织里","example":"Arterial mineralization stiffens the vessel wall.","exampleCN":"动脉矿化使血管壁变硬。","why":"Clinical writing uses the same word as geology because the deposit is chemically the same kind of mineral.","whyCN":"临床写作与地质学使用同一个词，因为沉积物在化学上是同一类矿物。"},{"no":"05","title":"Biomineralization","titleCN":"生物矿化：生物主动构建矿物","definition":"the controlled formation of minerals by living organisms, as in shells, teeth and bone","definitionCN":"生物受控地形成矿物，如贝壳、牙齿与骨骼","example":"Coral biomineralization builds reefs from dissolved carbonate.","exampleCN":"珊瑚的生物矿化用溶解的碳酸盐造礁。","why":"Biologists add the prefix bio- to separate deliberate construction by cells from passive geological deposition.","whyCN":"生物学家加前缀 bio-，把细胞有意的建造与被动的地址沉积区分开。"},{"no":"06","title":"Mineral content of water","titleCN":"矿化度：水中溶解矿物的总量","definition":"in hydrology, the total dissolved mineral content of water, also called its degree of mineralization","definitionCN":"水文学中指水中溶解矿物的总量，也称矿化度","example":"The well's high mineralization makes the water unsuitable for irrigation.","exampleCN":"这口井矿化度高，水不适合灌溉。","why":"The process word doubles as a quantity, because the result of dissolved minerals accumulating is a measurable total.","whyCN":"过程词兼作数量词，因为矿物溶解累积的结果就是一个可测量的总量。"},{"no":"07","title":"Complete breakdown of pollutants","titleCN":"污染物彻底矿化：分解为无机终产物","definition":"in environmental chemistry, the complete conversion of an organic pollutant into carbon dioxide, water and inorganic salts","definitionCN":"环境化学中指把有机污染物完全转化为二氧化碳、水与无机盐","example":"The treatment aims for full mineralization of the solvent.","exampleCN":"该处理的目标是让溶剂彻底矿化。","why":"Regulators care whether a pollutant is destroyed or merely transformed, so 'complete mineralization' became a standard.","whyCN":"监管者关心污染物是被销毁还是仅仅被转化，因此「彻底矿化」成了标准说法。"},{"no":"08","title":"Preservation in archaeology","titleCN":"考古保存：矿化留下的遗存","definition":"in archaeology, the mineral replacement that lets bone, shell or metal survive in the ground for millennia","definitionCN":"考古学中指矿物替换使骨骼、贝壳或金属得以在地下保存数千年","example":"Only the mineralized parts of the burial survived the wet soil.","exampleCN":"只有墓葬中已矿化的部分在湿土中保存下来。","why":"Archaeologists rely on the same process to explain why some objects last and others vanish.","whyCN":"考古学家依靠同一过程来解释为何有些物件留存、有些消失。"}],"etymology":{"intro":{"en":"Mineralization joins mineral, from Medieval Latin minera 'ore', to the verb suffix -ize and the action ending -ation.","cn":"mineralization 把源自中世纪拉丁 minera「矿石」的 mineral，与动词后缀 -ize 和动作词尾 -ation 组合起来。"},"items":[{"era":"MEDIEVAL LATIN","en":"Minera meant 'ore, mine' in medieval mining texts. Its deeper origin is disputed, with a Celtic ore word as the usual hypothesis.","cn":"minera 在中世纪采矿文献中意为「矿石、矿」。其更深来源有争议，通常的假说是某个凯尔特语表示矿石的词。"},{"era":"FRENCH -ISER","en":"The verb suffix -ize came into English through French -iser, which itself rests on Greek -izein 'to do, to make'.","cn":"动词后缀 -ize 经法语 -iser 进入英语，而法语形式又建立在希腊 -izein「做、使」之上。"},{"era":"LATIN -ATIO","en":"The action ending -ation descends from Latin -atio, so the whole word reads as 'the making of mineral'.","cn":"动作词尾 -ation 出自拉丁 -atio，因此整个词读作「使成为矿物的过程」。"},{"era":"GEOLOGY","en":"Nineteenth-century geology applied the word to ore deposition and to the replacement of organic matter in fossils.","cn":"19 世纪地质学把这个词用于成矿作用，也用于化石中有机物被替换的过程。"},{"era":"SOIL AND WATER","en":"Twentieth-century soil science and hydrology extended it to nutrient release and to the dissolved mineral load of water.","cn":"20 世纪的土壤学与水文学又把它扩展到养分释放与水中溶解矿物总量。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertainty: the first English use of mineralization is uncertain, and the deeper origin of minera is unresolved; the Celtic link is a hypothesis rather than a recorded fact.","cn":"来源不确定：mineralization 的英语首见年代存疑，minera 的更深来源亦无定论；凯尔特语关联属假说而非有记录的事实。"}]},"similar":{"note":{"en":"The first group holds mineral-family words that name different things; the second holds processes that also preserve or harden tissue.","cn":"第一组是同属 mineral 词族但指不同事物的词；第二组是同样保存或硬化组织的其他过程。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"mineralogy","ipa":"/ˌmɪnəˈrælədʒi/","tag":"the study","definition":"The science of minerals. Mineralization is a process; mineralogy is the discipline that studies its products.","definitionCN":"研究矿物的学科。mineralization 是过程，mineralogy 是研究其产物的学科。"},{"word":"mineralize","ipa":"/ˈmɪnərəlaɪz/","tag":"the verb","definition":"The verb meaning to convert into mineral form. Mineralization is its noun, naming the same event as a thing.","definitionCN":"意为使转化为矿物形态的动词。mineralization 是其名词，把同一事件当作事物来命名。"},{"word":"mineral","ipa":"/ˈmɪnərəl/","tag":"the substance","definition":"The natural inorganic solid itself. Mineralization names the process by which such material forms or replaces something.","definitionCN":"天然无机固体本身。mineralization 命名这种材料形成或替换某物的过程。"}]},{"heading":"NEAR MEANING","entries":[{"word":"fossilization","ipa":"/ˌfɒsəlaɪˈzeɪʃn/","tag":"the wider event","definition":"The whole process of turning a living thing into a fossil. Mineralization is often the mechanism, but freezing or drying can also preserve.","definitionCN":"把生物变成化石的整个过程。矿化常是其中的机制，但冷冻或干燥也能保存。"},{"word":"calcification","ipa":"/ˌkælsɪfɪˈkeɪʃn/","tag":"calcium only","definition":"The deposition of calcium salts in tissue. Mineralization in medicine often means calcification, but it can involve other minerals.","definitionCN":"钙盐在组织中的沉积。医学中的矿化常指钙化，但也可能涉及其他矿物。"},{"word":"diagenesis","ipa":"/ˌdaɪəˈdʒenəsɪs/","tag":"sediment change","definition":"The physical and chemical changes that turn loose sediment into rock. Mineralization is one of the changes it includes.","definitionCN":"把松散沉积物变成岩石的物理与化学变化。矿化是其中包含的一种变化。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"mineral + -ize + -ation: the process of becoming mineral.","cn":"mineral + -ize + -ation：变成矿物的过程。"},{"en":"The family runs mineralize, mineralized, mineral, mineralogy and demineralization.","cn":"同族词包括 mineralize、mineralized、mineral、mineralogy、demineralization。"},{"en":"Fixed phrases mark the fields: soil mineralization, ore mineralization, degree of mineralization.","cn":"固定搭配标出领域：土壤矿化、成矿作用、矿化度。"},{"en":"In soil, mineralization releases nutrients; in fossils, it replaces tissue; the word covers both directions.","cn":"在土壤中矿化释放养分，在化石中矿化替换组织；这个词覆盖了两个方向。"},{"en":"Biomineralization is mineralization run by cells, as in shells and teeth.","cn":"生物矿化是由细胞执行的矿化，如贝壳与牙齿。"}],"abstract":[{"en":"Picture a bone in wet ground slowly filling with stone until none of it is bone.","cn":"想象湿土中的骨头慢慢被石头填满，直到一点也不剩骨。"},{"en":"Picture a dark vein threading through grey rock, marking where metal was concentrated.","cn":"想象一条暗色矿脉穿过灰色岩石，标出金属富集之处。"},{"en":"Picture a glass of well water leaving a white ring when it evaporates.","cn":"想象一杯井水蒸发后留下一圈白痕。"}]},"examples":[{"en":"Warm weather increased the mineralization of soil organic matter.","cn":"温暖天气提高了土壤有机质的矿化速度。"},{"en":"The degree of mineralization determines whether the water is drinkable.","cn":"矿化度决定这水能否饮用。"},{"en":"The company claims complete mineralization of the pesticide within a week.","cn":"该公司声称这种农药在一周内可彻底矿化。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「mineral（矿物）+ ization（化）」——变成矿物的过程 → mineralization 矿化","word":"mineralization"},"root":"中世纪拉丁 minera「矿石」→ mineral；加希腊 -izein 与拉丁 -atio → mineralization。","sensesIntro":{"en":"Eight senses follow one process in both directions: minerals replacing tissue, organic matter releasing ions, ores concentrating, arteries hardening, cells building shells, water carrying salts, pollutants dissolving and graves preserving bone.","cn":"八个义项让同一过程向两个方向展开：矿物替换组织、有机质释放离子、矿石富集、动脉硬化、细胞造壳、水携带盐、污染物被分解、墓葬保存骨骼。"},"semanticMap":{"core":{"en":"CORE IMAGE: bone turning to stone inside a layer of rock.","cn":"核心意象：岩层中的骨头变成石头。"},"chain":["MINERAL ENTERS","TISSUE REPLACED","ORGANIC RELEASED","ORE CONCENTRATED","WATER LOADED","POLLUTANT DESTROYED"],"branches":[{"senses":"S1 · S8","en":"REPLACEMENT: fossils and burials survive because minerals take the place of tissue.","cn":"替换：化石与墓葬之所以留存，是因为矿物取代了组织。"},{"senses":"S2","en":"RELEASE: in soil, the same word runs the other way and turns organic matter into ions.","cn":"释放：在土壤中，同一个词反向运行，把有机质变成离子。"},{"senses":"S3","en":"CONCENTRATION: economic geology names the event that makes a deposit worth mining.","cn":"富集：经济地质学以此命名使矿床值得开采的事件。"},{"senses":"S4 · S5","en":"BODY: cells can build mineral deliberately, or deposit it where it does not belong.","cn":"身体：细胞可以有意构建矿物，也可以把它沉积在不该在的地方。"},{"senses":"S6 · S7","en":"MEASURE AND REMEDY: water reports mineralization as a number, and treatment aims for its completion.","cn":"计量与治理：水以数字报告矿化度，处理则以彻底矿化为目标。"}]},"affixes":{"intro":{"en":"Mineralization combines a Medieval Latin noun, a Greek-derived verb suffix and a Latin action ending, three layers from three languages.","cn":"mineralization 把一个中世纪拉丁名词、一个源自希腊的动词后缀与一个拉丁动作词尾合在一起，三层来自三种语言。"},"latinIntro":{"en":"Latin -atio gave the noun ending; the -ize layer came through French from Greek -izein; and minera supplied the stem.","cn":"拉丁 -atio 提供名词词尾，-ize 一层经法语来自希腊 -izein，minera 提供词干。"},"items":[{"word":"mineralization","structure":"mineral + -ize + -ation","meaning":"the process of becoming or replacing with mineral","meaningCN":"变成矿物或用矿物替换的过程","example":"Mineralization preserved the shell.","exampleCN":"矿化作用保存了贝壳。"},{"word":"mineralize","structure":"mineral + -ize","meaning":"to convert into mineral form","meaningCN":"使转化为矿物形态","example":"Bacteria mineralize the leaf litter.","exampleCN":"细菌把落叶矿化。"},{"word":"mineralized","structure":"mineralize + -ed","meaning":"converted into mineral","meaningCN":"已转化为矿物的","example":"The mineralized tissue is hard as stone.","exampleCN":"矿化组织硬如石头。"},{"word":"mineral","structure":"minera + -ale","meaning":"the substance involved","meaningCN":"所涉及的物质","example":"The mineral is mostly calcium phosphate.","exampleCN":"该矿物主要是磷酸钙。"},{"word":"demineralization","structure":"de- + mineralization","meaning":"loss of mineral","meaningCN":"矿物质的流失","example":"Demineralization weakens the enamel.","exampleCN":"脱矿使牙釉质变弱。"},{"word":"mineralizer","structure":"mineralize + -er","meaning":"a substance or fluid that promotes mineralization","meaningCN":"促进矿化的物质或流体","example":"The mineralizer carried dissolved silica.","exampleCN":"该矿化剂携带溶解的二氧化硅。"},{"word":"biomineralization","structure":"bio- + mineralization","meaning":"mineral formation controlled by organisms","meaningCN":"由生物控制的矿物形成","example":"Biomineralization builds coral reefs.","exampleCN":"生物矿化建造珊瑚礁。"},{"word":"mineralogy","structure":"mineral + -logy","meaning":"the study of minerals","meaningCN":"矿物研究","example":"Mineralogy explains the crystal shapes.","exampleCN":"矿物学解释了晶体的形状。"},{"word":"fossilization","structure":"fossil + -ization","meaning":"the wider process of becoming a fossil","meaningCN":"变成化石的更广过程","example":"Fossilization required rapid burial.","exampleCN":"化石化需要迅速埋藏。"}],"latinEntries":[{"word":"minera","structure":"minera, minerae (f., Medieval Latin, first declension)","meaning":"ore, mine","meaningCN":"矿石、矿"},{"word":"-atio","structure":"-atio, -ationis (f., third declension)","meaning":"action-noun suffix","meaningCN":"动作名词后缀"},{"word":"-izare","structure":"-izare (Medieval Latin verb suffix, from Greek -izein)","meaning":"to make, to cause to be","meaningCN":"使成为、使变成"}]}},{"word":"nutrient","ipa_uk":"/ˈnjuːtriənt/","ipa_us":"/ˈnuːtriənt/","definition_zh":"养分；营养素","definition_en":"a substance that provides nourishment and is needed by a living thing for growth and health","core_image":"植物的根系伸向土壤颗粒，旁边一盘食物被分成几块不同颜色的区域","scene":"Nitrogen is the nutrient that limits plant growth in most temperate soils.","sceneCN":"这里 nutrient 指「限制性养分」（第 3 个义项：生态学中供应最不足、决定生长上限的那种养分）；温带土壤里最缺的往往是氮，它因此限制了植物生长。图中可辨识物件：植物根系、土壤颗粒、氮标记、生长曲线。","pos":[{"tag":"n.","zh":"养分；营养素（可数，如 essential nutrients）"},{"tag":"adj.","zh":"提供养分的；营养的（多作定语，如 nutrient-rich）"}],"collocations":[{"phrase":"essential nutrients","zh":"必需营养素"},{"phrase":"nutrient cycling","zh":"养分循环"},{"phrase":"limiting nutrient","zh":"限制性养分"},{"phrase":"nutrient absorption","zh":"营养吸收"},{"phrase":"nutrient pollution","zh":"养分污染；营养物污染"},{"phrase":"plant nutrients","zh":"植物养分"}],"forms":[{"label":"复数","form":"nutrients（多种养分）"},{"label":"作定语","form":"nutrient + 名词（如 nutrient-rich、nutrient cycling）"},{"label":"相关形容词","form":"nutritious（有营养的）；nutritional（营养的）"},{"label":"相关名词","form":"nutrition（营养）；nutrient medium（营养培养基）"},{"label":"相关动词","form":"nourish（滋养）"}],"derivatives":[{"word":"nutrition","pos":"n.","zh":"营养；营养学"},{"word":"nutritional","pos":"adj.","zh":"营养的"},{"word":"nutritious","pos":"adj.","zh":"有营养的"},{"word":"nourish","pos":"v.","zh":"滋养；养育"},{"word":"nourishment","pos":"n.","zh":"营养物；滋养"},{"word":"malnutrition","pos":"n.","zh":"营养不良"}],"senses":[{"no":"01","title":"A substance that nourishes","titleCN":"养分：为生命提供养料的东西","definition":"any substance that an organism takes in and uses to build tissue or obtain energy","definitionCN":"生物摄入并用于构建组织或获取能量的任何物质","example":"Every cell needs a steady supply of nutrients.","exampleCN":"每个细胞都需要稳定的养分供应。","why":"The word is the present participle of Latin nutrire 'to nourish', so a nutrient is literally 'a nourishing thing'.","whyCN":"这个词是拉丁 nutrire「滋养」的现在分词，因此 nutrient 字面就是「正在滋养的东西」。"},{"no":"02","title":"Essential nutrients in food","titleCN":"必需营养素：人体不能自己合成的成分","definition":"the dietary components, such as vitamins, minerals, amino acids and fatty acids, that the body cannot make in sufficient amounts","definitionCN":"维生素、矿物质、氨基酸与脂肪酸这类人体无法足量自造的膳食成分","example":"Vitamin C is an essential nutrient for humans.","exampleCN":"维生素 C 是人体的一种必需营养素。","why":"Nutrition separates what the body can synthesise from what it must eat, and calls the second group essential.","whyCN":"营养学把身体能合成的与必须从食物摄入的分开，称后者为「必需」。"},{"no":"03","title":"Limiting nutrient in ecology","titleCN":"限制性养分：决定生长上限的那一种","definition":"in ecology, the nutrient in shortest supply relative to demand, which caps growth until it is added","definitionCN":"生态学中指相对需求供应最不足的养分，在补充它之前一直限制生长","example":"Phosphorus is often the limiting nutrient in freshwater lakes.","exampleCN":"磷常常是淡水湖泊中的限制性养分。","why":"Ecologists name the bottleneck rather than the whole list, so 'limiting nutrient' became a single fixed phrase.","whyCN":"生态学家命名的是瓶颈而非整张清单，因此「限制性养分」成了一个固定短语。"},{"no":"04","title":"Plant nutrients","titleCN":"植物养分：氮磷钾等矿质元素","definition":"the mineral elements that plants absorb from soil or water, especially nitrogen, phosphorus and potassium","definitionCN":"植物从土壤或水中吸收的矿质元素，尤其是氮、磷、钾","example":"The fertiliser supplies the three main plant nutrients.","exampleCN":"这种肥料提供三种主要的植物养分。","why":"Agriculture lists nutrients by element because a plant's needs can be measured as ions taken from soil.","whyCN":"农业按元素列出养分，因为植物的需求可以按从土壤吸收的离子来衡量。"},{"no":"05","title":"Absorption and deficiency","titleCN":"吸收与缺乏：临床上的养分供应","definition":"in medicine, a nutrient as something absorbed by the gut or lacking in a patient's diet","definitionCN":"医学中指被肠道吸收、或在患者膳食中缺乏的养分","example":"The disease blocks nutrient absorption in the small intestine.","exampleCN":"这种病阻碍小肠吸收养分。","why":"Clinical usage focuses on the path from food to cell, so the word appears in absorption and deficiency alike.","whyCN":"临床用法关注从食物到细胞的路径，因此这个词在「吸收」与「缺乏」两种语境里都出现。"},{"no":"06","title":"Nutrient pollution","titleCN":"养分污染：过量营养物进入水体","definition":"in environmental science, nitrogen and phosphorus entering water in excess and triggering algal blooms","definitionCN":"环境科学中指过量的氮与磷进入水体并引发藻华","example":"Nutrient pollution from farms turned the bay green.","exampleCN":"农场带来的养分污染让海湾变绿。","why":"The same substances that are food on land become pollution in water, so the neutral word gains a negative use.","whyCN":"在陆地上是食物的同一物质，在水里成了污染，因此这个中性词获得了负面用法。"},{"no":"07","title":"Nutrient-rich as an adjective","titleCN":"作定语：富含养分的","definition":"used before a noun to describe something that supplies nutrients, as in nutrient-rich soil or nutrient solution","definitionCN":"置于名词前，描述提供养分的事物，如富含养分的土壤或营养液","example":"The delta's nutrient-rich silt feeds the rice fields.","exampleCN":"三角洲富含养分的淤泥滋养着稻田。","why":"English lets nouns modify nouns, so the same word describes a medium without changing form.","whyCN":"英语允许名词作定语，因此同一个词不需变形就能描述某种介质。"},{"no":"08","title":"Nutrient medium in the lab","titleCN":"营养培养基：培养微生物的配方","definition":"in microbiology, the prepared mixture of nutrients used to grow cells or bacteria in culture","definitionCN":"微生物学中指用于培养细胞或细菌的配制养分混合物","example":"The bacteria grew well on the nutrient agar.","exampleCN":"细菌在营养琼脂上长得很好。","why":"Laboratory practice turns the general word into a countable product name, as in nutrient agar and nutrient broth.","whyCN":"实验室实践把这个泛称变成可数的产品名，如营养琼脂与营养肉汤。"}],"etymology":{"intro":{"en":"Nutrient is the English form of Latin nutriens, the present participle of nutrire 'to nourish, to suckle'.","cn":"nutrient 是拉丁 nutriens 的英语形式，即动词 nutrire「滋养、哺乳」的现在分词。"},"items":[{"era":"LATIN NUTRIRE","en":"Latin nutrire meant 'to nourish, to feed, to suckle'. It is the source of nutrition, nutritious, nourish and nurse.","cn":"拉丁 nutrire 意为「滋养、喂养、哺乳」。它是 nutrition、nutritious、nourish 与 nurse 的来源。"},{"era":"PRESENT PARTICIPLE","en":"The form nutriens, nutrient- meant 'nourishing, the thing that nourishes', and English took it as an adjective and later as a noun.","cn":"形式 nutriens、nutrient- 意为「滋养的、滋养之物」，英语先把它作形容词，后来才作名词。"},{"era":"ENGLISH ADJECTIVE","en":"English nutrient is recorded as an adjective in the sixteenth century, meaning 'nourishing', in medical and botanical writing.","cn":"英语 nutrient 在 16 世纪作为形容词有记录，意为「滋养的」，见于医学与植物学著作。"},{"era":"ENGLISH NOUN","en":"The noun use, meaning 'a nourishing substance', became common in the nineteenth century with the rise of nutritional science.","cn":"名词用法「滋养物质」在 19 世纪随营养科学的兴起而普及。"},{"era":"ECOLOGY AND AGRICULTURE","en":"Twentieth-century ecology and agriculture extended the noun to soil, water and fertiliser, producing phrases such as limiting nutrient.","cn":"20 世纪的生态学与农业把这一名词扩展到土壤、水与肥料，产生了「限制性养分」这类短语。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertainty: the exact first English citation of nutrient is uncertain; the adjective and noun dates overlap, and the shift from one to the other is not documented in a single text.","cn":"来源不确定：nutrient 的英语首见确切书证年代存疑；形容词与名词的用法年代相互交叠，从前者转为后者的过程并无单一文献记录。"}]},"similar":{"note":{"en":"The first group holds words from the same Latin family that answer different grammatical questions; the second holds words for what is eaten or added.","cn":"第一组是同出拉丁词族、但回答不同语法问题的词；第二组指被吃掉或被添加的东西。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"nutrition","ipa":"/njuˈtrɪʃn/","tag":"the process or science","definition":"The process of being nourished, or the scientific study of it. A nutrient is the substance; nutrition is the process and the field.","definitionCN":"被滋养的过程，或研究它的学科。nutrient 是物质，nutrition 是过程与学科。"},{"word":"nutritious","ipa":"/njuˈtrɪʃəs/","tag":"the quality adjective","definition":"Describes food that is rich in nutrients, as in a nutritious meal. It judges the food, not the substance.","definitionCN":"描述富含养分的食物，如「有营养的一餐」。它评价食物，而不是物质本身。"},{"word":"nutritional","ipa":"/ˌnjuːtrɪˈʃənl/","tag":"relating to nutrition","definition":"Means 'relating to nutrition', as in nutritional value. It frames a topic, while nutritious makes a judgement.","definitionCN":"意为「与营养有关的」，如营养价值。它框定话题，而 nutritious 作出评价。"}]},{"heading":"NEAR MEANING","entries":[{"word":"nourishment","ipa":"/ˈnuːrɪʃmənt/","tag":"the sustaining effect","definition":"The food or support that keeps something alive and growing. It stresses the effect of being fed rather than the chemical identity.","definitionCN":"维持生命与生长的食物或支持。它强调被喂养的效果，而非化学身份。"},{"word":"food","ipa":"/fuːd/","tag":"the whole thing eaten","definition":"Any substance eaten to sustain life. Food contains nutrients, but a food is the whole item, not one component.","definitionCN":"为维持生命而摄入的任何物质。食物含有养分，但食物是整体，不是某一成分。"},{"word":"supplement","ipa":"/ˈsʌplɪmənt/","tag":"an added dose","definition":"A product taken to add a nutrient that the diet may lack. It is a delivery format, not a category of nutrient.","definitionCN":"为补充膳食可能缺乏的养分而服用的产品。它是供给形式，而不是养分类别。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Latin nutrire 'nourish' + -ent: the nourishing thing.","cn":"拉丁 nutrire「滋养」+ -ent：正在滋养的东西。"},{"en":"The family runs nutrition, nutritional, nutritious, nourish, nourishment and malnutrition.","cn":"同族词包括 nutrition、nutritional、nutritious、nourish、nourishment、malnutrition。"},{"en":"Fixed phrases mark the fields: essential nutrients, nutrient cycling, limiting nutrient, nutrient pollution.","cn":"固定搭配标出领域：必需营养素、养分循环、限制性养分、养分污染。"},{"en":"A nutrient is a substance; nutrition is the process; nutritious describes the food.","cn":"nutrient 是物质，nutrition 是过程，nutritious 描述食物。"},{"en":"Nitrogen, phosphorus and potassium are the three main plant nutrients.","cn":"氮、磷、钾是三种主要的植物养分。"}],"abstract":[{"en":"Picture a root hair touching a soil grain and drawing a tiny charged particle out of it.","cn":"想象一根根毛碰到土壤颗粒，从里面吸出一颗带电的微粒。"},{"en":"Picture a plate divided into coloured sections, each standing for a different kind of nourishment.","cn":"想象一只餐盘被分成几块彩色区域，每块代表一种不同的养分。"},{"en":"Picture a petri dish of gel where colonies appear only where the mixture was rich enough.","cn":"想象一只培养皿，只有混合物足够丰富的地方才长出菌落。"}]},"examples":[{"en":"Legumes add nitrogen, a key nutrient, to the soil.","cn":"豆科植物把氮这种关键养分加入土壤。"},{"en":"The gut lining absorbs nutrients from digested food.","cn":"肠壁从消化后的食物中吸收养分。"},{"en":"Excess nutrients washed off lawns can choke a stream.","cn":"草坪冲下的过量养分会使溪流窒息。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「nutri（滋养）+ ent（东西）」——起滋养作用的东西 → nutrient 养分","word":"nutrient"},"root":"拉丁 nutrire「滋养、哺乳」→ 现在分词 nutriens、nutrient- → 英语 nutrient。","sensesIntro":{"en":"Eight senses follow one substance from a general nourishing thing to a dietary essential, an ecological bottleneck, a plant ion, a clinical issue, a pollutant and a laboratory medium.","cn":"八个义项让同一种物质从泛指的滋养物走到膳食必需成分、生态瓶颈、植物离子、临床问题、污染物与实验室培养基。"},"semanticMap":{"core":{"en":"CORE IMAGE: a root hair drawing a charged particle from a soil grain.","cn":"核心意象：根毛从土壤颗粒中吸出一颗带电微粒。"},"chain":["NOURISHING THING","MUST BE EATEN","LIMITS GROWTH","FEEDS THE CROP","PASSES THE GUT","OVERFEEDS THE LAKE"],"branches":[{"senses":"S1","en":"GENERAL: any substance that builds tissue or supplies energy.","cn":"泛指：任何构建组织或提供能量的物质。"},{"senses":"S2 · S5","en":"HUMAN BODY: what cannot be made must be eaten, absorbed and delivered.","cn":"人体：不能自造的就必须吃进、吸收并送达。"},{"senses":"S3 · S7","en":"ECOLOGY: the scarcest nutrient caps growth, and a rich medium is described by the same word.","cn":"生态：最稀缺的养分决定生长上限，而富含养分的介质也用同一个词描述。"},{"senses":"S4","en":"AGRICULTURE: nitrogen, phosphorus and potassium are counted as the main plant nutrients.","cn":"农业：氮、磷、钾被算作主要的植物养分。"},{"senses":"S6 · S8","en":"EXCESS AND CULTURE: too much in a river is pollution; the right mix in a dish grows microbes.","cn":"过量与培养：河里太多是污染，皿里配好则培养微生物。"}]},"affixes":{"intro":{"en":"Nutrient is a Latin participle used unchanged in English, so its ending -ent marks 'the one doing the nourishing'.","cn":"nutrient 是原样进入英语的拉丁分词，词尾 -ent 标记「正在做滋养这件事的一方」。"},"latinIntro":{"en":"Latin nutrire supplied the whole family: nutriens as participle, nutritio as action noun, and nutritius as adjective.","cn":"拉丁 nutrire 提供了整族词：分词 nutriens、动作名词 nutritio 与形容词 nutritius。"},"items":[{"word":"nutrient","structure":"nutrire + -ens (present participle)","meaning":"a nourishing substance","meaningCN":"滋养性的物质","example":"The soil is low in nutrients.","exampleCN":"这种土壤养分不足。"},{"word":"nutrition","structure":"nutrire + -tio (action noun)","meaning":"the process of being nourished","meaningCN":"被滋养的过程","example":"Nutrition begins with digestion.","exampleCN":"营养始于消化。"},{"word":"nutritional","structure":"nutrition + -al","meaning":"relating to nutrition","meaningCN":"与营养有关的","example":"The nutritional value varies by variety.","exampleCN":"营养价值因品种而异。"},{"word":"nutritious","structure":"nutritius + -ous","meaning":"rich in nutrients","meaningCN":"富含养分的","example":"Beans are a nutritious food.","exampleCN":"豆类是富有营养的食物。"},{"word":"nourish","structure":"Old French nourrir, from Latin nutrire","meaning":"to feed and sustain","meaningCN":"喂养并维持","example":"The soil nourishes the seedlings.","exampleCN":"土壤滋养幼苗。"},{"word":"nourishment","structure":"nourish + -ment","meaning":"food that sustains","meaningCN":"维持生命的食物","example":"The broth provided nourishment.","exampleCN":"这碗汤提供了营养。"},{"word":"malnutrition","structure":"mal- (bad) + nutrition","meaning":"poor or unbalanced nourishment","meaningCN":"营养不足或不均衡","example":"Malnutrition stunts growth.","exampleCN":"营养不良阻碍生长。"},{"word":"nutrient medium","structure":"nutrient + medium (Latin medius)","meaning":"a prepared growth mixture","meaningCN":"配制好的培养混合物","example":"The lab prepared a nutrient medium.","exampleCN":"实验室配制了一种营养培养基。"}],"latinEntries":[{"word":"nutrire","structure":"nutrire (verb, fourth conjugation)","meaning":"to nourish, to suckle","meaningCN":"滋养、哺乳"},{"word":"nutriens","structure":"nutriens, nutrientis (present participle)","meaning":"nourishing","meaningCN":"滋养的"},{"word":"nutritio","structure":"nutritio, nutritionis (f., third declension)","meaning":"nourishment, the act of feeding","meaningCN":"营养；喂养的动作"}]}},{"word":"nutrition","ipa_uk":"/njuˈtrɪʃn/","ipa_us":"/nuˈtrɪʃn/","definition_zh":"营养；营养学","definition_en":"the process by which living things obtain and use the food they need, and the scientific study of that process","core_image":"一只餐盘被分成几块，旁边一本翻开的教科书与一条向上生长的曲线","scene":"Good nutrition in the first two years shapes growth for the rest of childhood.","sceneCN":"这里 nutrition 指「膳食质量」（第 3 个义项：一个人实际获得的营养状况）；最初两年的营养质量会影响此后整个童年的生长。图中可辨识物件：餐盘、食物分区、生长曲线、儿童身高手册。","pos":[{"tag":"n.","zh":"营养；营养学（多作不可数名词；指学科时为不可数）"}],"collocations":[{"phrase":"nutrition facts","zh":"营养标签；营养成分表"},{"phrase":"nutrition science","zh":"营养科学"},{"phrase":"clinical nutrition","zh":"临床营养"},{"phrase":"plant nutrition","zh":"植物营养"},{"phrase":"nutrition education","zh":"营养教育"},{"phrase":"nutrition label","zh":"营养标签"}],"forms":[{"label":"不可数用法","form":"nutrition（指过程或学科时不加 -s）"},{"label":"形容词形式","form":"nutritional（营养的）；nutritious（有营养的）"},{"label":"副词形式","form":"nutritionally（在营养方面）"},{"label":"从业者名词","form":"nutritionist（营养师；营养学家）"},{"label":"相关动词","form":"nourish（滋养）；nutrify（加营养，较少用）"}],"derivatives":[{"word":"nutritional","pos":"adj.","zh":"营养的；营养方面的"},{"word":"nutritionist","pos":"n.","zh":"营养师；营养学家"},{"word":"nutritionally","pos":"adv.","zh":"在营养方面"},{"word":"nutritious","pos":"adj.","zh":"有营养的"},{"word":"nourish","pos":"v.","zh":"滋养；养育"},{"word":"malnutrition","pos":"n.","zh":"营养不良"}],"senses":[{"no":"01","title":"The process of being nourished","titleCN":"营养过程：摄入与利用食物的全过程","definition":"the whole process by which an organism takes in food and uses it for energy, growth and repair","definitionCN":"生物摄入食物并把它用于能量、生长与修复的全过程","example":"Nutrition begins with chewing and ends inside every cell.","exampleCN":"营养从咀嚼开始，到每个细胞为止。","why":"The Latin action noun names an activity, not a substance, so nutrition is first of all something that happens.","whyCN":"这个拉丁动作名词命名的是活动而非物质，因此 nutrition 首先是一件正在发生的事。"},{"no":"02","title":"The scientific discipline","titleCN":"营养学：研究食物与健康的学科","definition":"the branch of science that studies nutrients, how the body uses them and how diet affects health","definitionCN":"研究养分、身体如何利用它们以及膳食如何影响健康的科学分支","example":"She studied nutrition before working in public health.","exampleCN":"她在进入公共卫生领域之前学的是营养学。","why":"Because the process is complex enough to study, the same noun came to name the academic field without any change of form.","whyCN":"由于这一过程复杂到值得研究，同一个名词不需变形就成了一门学科的名字。"},{"no":"03","title":"The quality of a diet","titleCN":"膳食质量：一个人实际获得的营养","definition":"the nourishment a person or population actually receives through their diet, judged as good or poor","definitionCN":"个人或群体通过膳食实际获得的营养，可评为良好或不足","example":"Good nutrition in early childhood pays off for decades.","exampleCN":"幼儿期良好的营养会在几十年后仍然受益。","why":"Clinicians and policy makers speak of nutrition as a state to be assessed, so the process word also names a condition.","whyCN":"临床医生与政策制定者把营养当作可评估的状态，因此过程词也指一种状况。"},{"no":"04","title":"Clinical nutrition","titleCN":"临床营养：以营养手段治疗患者","definition":"the medical specialty that manages diet, tube feeding and intravenous feeding in illness","definitionCN":"在疾病中管理膳食、管饲与静脉营养的医学专科","example":"The clinical nutrition team adjusted his tube feed.","exampleCN":"临床营养团队调整了他的管饲配方。","why":"When eating is impossible, nutrition becomes a medical intervention with doses and protocols.","whyCN":"当无法进食时，营养就变成有剂量与规程的医疗干预。"},{"no":"05","title":"Plant nutrition","titleCN":"植物营养：根系吸收与光合作用","definition":"in botany, the way plants obtain mineral ions from soil and carbon from the air","definitionCN":"植物学中指植物从土壤取得矿质离子、从空气取得碳的方式","example":"Plant nutrition depends on both root uptake and photosynthesis.","exampleCN":"植物营养同时依赖根系吸收与光合作用。","why":"Botanists reuse the word for a completely different strategy, because the goal of obtaining matter for growth is the same.","whyCN":"植物学家把这个词用于完全不同的策略，因为「获取物质以生长」这一目标是相同的。"},{"no":"06","title":"Public health nutrition","titleCN":"公共营养：人群层面的膳食政策","definition":"the population-level field that shapes food supply, fortification and dietary advice","definitionCN":"在人群层面塑造食物供应、营养强化与膳食建议的领域","example":"Public health nutrition cut iodine deficiency across the country.","exampleCN":"公共营养工作在全国范围内减少了碘缺乏。","why":"The unit of study shifts from a body to a population, and the word scales up with it.","whyCN":"研究对象从个体身体转为整个人群，这个词也随之放大。"},{"no":"07","title":"On the packet","titleCN":"营养标签：包装上的营养成分","definition":"the nutrient information printed on food packaging, often headed nutrition facts","definitionCN":"食品包装上印制的养分信息，常以「营养成分表」为标题","example":"The nutrition label lists sugar per serving.","exampleCN":"营养标签列出每份的糖含量。","why":"Regulation turned the science into a standard table, so the word appears on every packet.","whyCN":"法规把这门科学变成标准表格，因此这个词出现在每个包装上。"},{"no":"08","title":"Nutrition transition","titleCN":"营养转型：人群膳食结构的改变","definition":"the shift in a population's diet toward processed food, sugar and fat as incomes rise","definitionCN":"随着收入提高，人群膳食向加工食品、糖与脂肪转变的过程","example":"The country's nutrition transition brought rising obesity.","exampleCN":"该国的营养转型带来了肥胖率上升。","why":"Epidemiologists needed a name for a society-wide change, so they extended the word with 'transition'.","whyCN":"流行病学家需要为全社会层面的变化命名，便给它加上了 transition。"}],"etymology":{"intro":{"en":"Nutrition comes from Latin nutritio, an action noun from nutrire 'to nourish'. English adopted it in the sixteenth century.","cn":"nutrition 出自拉丁 nutritio，是动词 nutrire「滋养」构成的行动名词，英语在 16 世纪借入。"},"items":[{"era":"LATIN NUTRIRE","en":"Latin nutrire meant 'to nourish, to suckle'. Its family includes nutriens 'nourishing' and nutritius 'nourishing, nutritious'.","cn":"拉丁 nutrire 意为「滋养、哺乳」，其同族词包括 nutriens「滋养的」与 nutritius「有营养的」。"},{"era":"LATIN NUTRITIO","en":"The action noun nutritio, nutritionis named the act of feeding and the state of being fed, in medical and philosophical Latin.","cn":"行动名词 nutritio、nutritionis 在医学与哲学拉丁文中指喂养的动作与被滋养的状态。"},{"era":"FRENCH AND ENGLISH","en":"Old French nutrition passed into English in the sixteenth century, first as a medical term for the body's uptake and use of food.","cn":"古法语 nutrition 在 16 世纪进入英语，最初是医学术语，指身体摄取与利用食物。"},{"era":"SCIENCE OF NUTRITION","en":"In the nineteenth and early twentieth centuries the word became the name of a discipline, as calories, vitamins and deficiency diseases were described.","cn":"19 世纪至 20 世纪初，随着热量、维生素与缺乏病被描述，这个词成了一门学科的名称。"},{"era":"PUBLIC HEALTH","en":"Later in the twentieth century nutrition entered policy language through fortification programmes, school meals and labelling rules.","cn":"20 世纪后期，营养经强化计划、学校供餐与标签规则进入政策语言。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertainty: the exact first English citation of nutrition is uncertain, usually given as the 1550s but not fixed; the earliest uses are translations of Latin medical texts.","cn":"来源不确定：nutrition 的英语首见确切书证年代存疑，通常写作 16 世纪 50 年代但并不确定；最早用例是拉丁医学文献的译本。"}]},"similar":{"note":{"en":"The first group holds same-family words that divide the topic differently; the second holds words for what is eaten, how much is eaten, and whether it is enough.","cn":"第一组是同族词，但把话题切分得不同；第二组指吃的东西、吃的量以及是否足够。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"nutrient","ipa":"/ˈnjuːtriənt/","tag":"one substance","definition":"A single nourishing substance such as a vitamin or an amino acid. Nutrition is the process and the field that study many nutrients together.","definitionCN":"单一种滋养物质，如某种维生素或氨基酸。nutrition 是过程，也是把多种 nutrient 放在一起研究的学科。"},{"word":"nutritious","ipa":"/njuˈtrɪʃəs/","tag":"a judgement","definition":"An adjective praising food as rich in nutrients. It evaluates a meal, while nutrition names a process or a science.","definitionCN":"称赞食物富含养分的形容词。它评价一餐，而 nutrition 命名过程或学科。"},{"word":"nutritional","ipa":"/ˌnjuːtrɪˈʃənl/","tag":"a topic frame","definition":"An adjective meaning 'relating to nutrition', as in nutritional value. It labels the dimension being discussed.","definitionCN":"意为「与营养有关的」的形容词，如营养价值。它标明讨论的是哪个维度。"}]},{"heading":"NEAR MEANING","entries":[{"word":"nourishment","ipa":"/ˈnuːrɪʃmənt/","tag":"what sustains","definition":"The material or support that keeps something alive. It is more concrete and emotional than the clinical word nutrition.","definitionCN":"维持生命所需的物质或支持。它比临床味更重的 nutrition 更具体、更有情感色彩。"},{"word":"diet","ipa":"/ˈdaɪət/","tag":"the pattern of eating","definition":"The usual food a person or group eats, or a planned restriction. Nutrition is what the body does with that diet.","definitionCN":"个人或群体常吃的食物，或计划性的限制饮食。nutrition 是身体对这份膳食做了什么。"},{"word":"malnutrition","ipa":"/ˌmælnjuːˈtrɪʃn/","tag":"the deficit state","definition":"Poor nutrition caused by too little food or by an unbalanced diet. It is the failure case of nutrition, not a synonym.","definitionCN":"因食物不足或膳食失衡造成的营养不佳。它是营养的反面情形，而非同义词。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Latin nutrire 'nourish' + -tio: the act of nourishing, turned into a noun.","cn":"拉丁 nutrire「滋养」+ -tio：滋养的动作，再变成名词。"},{"en":"The family runs nutrient, nutritional, nutritious, nourish, nutritionist and malnutrition.","cn":"同族词包括 nutrient、nutritional、nutritious、nourish、nutritionist、malnutrition。"},{"en":"Fixed phrases mark the fields: nutrition facts, clinical nutrition, plant nutrition, nutrition education.","cn":"固定搭配标出领域：营养成分表、临床营养、植物营养、营养教育。"},{"en":"nutrition is the process and the science; a nutrient is one substance.","cn":"nutrition 是过程也是学科；nutrient 是某一种物质。"},{"en":"Malnutrition is what happens when nutrition fails, not a synonym for it.","cn":"malnutrition 是营养失败时的情形，而不是 nutrition 的同义词。"}],"abstract":[{"en":"Picture a plate with a child's height marked on the wall behind it, rising year by year.","cn":"想象一只餐盘，背后墙上画着逐年升高的儿童身高刻度。"},{"en":"Picture a packet turned over to show a grid of numbers headed nutrition facts.","cn":"想象一个包装袋翻过来，露出一张标题为「营养成分表」的数字表格。"},{"en":"Picture a country's market shelves filling with sweet drinks over a single generation.","cn":"想象一个国家在一代人的时间里，货架上逐渐堆满含糖饮料。"}]},"examples":[{"en":"Nutrition is now a compulsory subject for medical students.","cn":"营养学如今是医学生的必修科目。"},{"en":"Poor nutrition in the camp weakened the children before the epidemic arrived.","cn":"疫病到来之前，营地里的营养不良已使孩子们虚弱。"},{"en":"The study compared the nutrition of urban and rural households.","cn":"这项研究比较了城乡家庭的营养状况。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「nutri（滋养）+ tion（过程）」——身体被滋养的全过程 → nutrition 营养","word":"nutrition"},"root":"拉丁 nutrire「滋养、哺乳」→ 动作名词 nutritio → 古法语 nutrition → 英语 nutrition。","sensesIntro":{"en":"Eight senses follow one process from digestion to a scientific discipline, a diet's quality, a hospital service, a plant's strategy, national policy, a label and a whole society's diet.","cn":"八个义项让同一过程从消化走到学科、膳食质量、医院服务、植物策略、国家政策、包装标签，以及整个社会的膳食。"},"semanticMap":{"core":{"en":"CORE IMAGE: a divided plate beside a textbook and a rising growth curve.","cn":"核心意象：分格的餐盘，旁边是一本教科书与上升的生长曲线。"},"chain":["TAKE IN FOOD","USE IT INSIDE","BECOME A SCIENCE","JUDGE THE DIET","TREAT THE PATIENT","SHAPE A POPULATION"],"branches":[{"senses":"S1","en":"THE PROCESS: food is taken in, broken down, absorbed and used.","cn":"过程：食物被摄入、分解、吸收与利用。"},{"senses":"S2 · S3","en":"KNOWLEDGE AND STATE: the same noun names the field and the condition of a person's diet.","cn":"知识与状态：同一个名词既指学科，也指一个人膳食的状况。"},{"senses":"S4","en":"TREATMENT: when eating fails, nutrition becomes a medical procedure.","cn":"治疗：当进食失败时，营养成为医疗规程。"},{"senses":"S5","en":"PLANTS: another kingdom, the same goal of obtaining matter to grow.","cn":"植物：另一个生物界，同一个「获取物质以生长」的目标。"},{"senses":"S6 · S7 · S8","en":"POPULATION AND PACKET: policy, labels and dietary shifts all use the word at scale.","cn":"人群与包装：政策、标签与膳食变迁都在更大尺度上使用这个词。"}]},"affixes":{"intro":{"en":"Nutrition is a Latin action noun, and its -tion ending still marks it as a process rather than a thing.","cn":"nutrition 是拉丁行动名词，其 -tion 词尾仍标记它是过程而不是实物。"},"latinIntro":{"en":"Latin -tio produced nutritio; the same ending appears in nutrition's neighbours, oxidation and radiation.","cn":"拉丁 -tio 产生 nutritio；同一词尾也出现在 oxidation、radiation 这些邻近词中。"},"items":[{"word":"nutrition","structure":"nutrire + -tio (action noun)","meaning":"the process of being nourished; the science of it","meaningCN":"被滋养的过程；研究它的学科","example":"Nutrition drives recovery after surgery.","exampleCN":"营养推动术后恢复。"},{"word":"nutrient","structure":"nutrire + -ens (participle)","meaning":"a nourishing substance","meaningCN":"滋养性物质","example":"Each nutrient has a different role.","exampleCN":"每种养分的作用各不相同。"},{"word":"nutritional","structure":"nutrition + -al","meaning":"relating to nutrition","meaningCN":"与营养有关的","example":"The nutritional profile changed with processing.","exampleCN":"加工后营养成分构成改变了。"},{"word":"nutritionist","structure":"nutrition + -ist (practitioner)","meaning":"a person who advises on diet","meaningCN":"提供膳食建议的人","example":"The nutritionist planned the menu.","exampleCN":"营养师制定了菜单。"},{"word":"nutritionally","structure":"nutritional + -ly","meaning":"in nutritional terms","meaningCN":"从营养角度看","example":"The two cereals are nutritionally similar.","exampleCN":"这两种麦片在营养上相似。"},{"word":"nutritious","structure":"nutritius + -ous","meaning":"rich in nutrients","meaningCN":"富含养分的","example":"The soup is cheap but nutritious.","exampleCN":"这汤便宜却有营养。"},{"word":"malnutrition","structure":"mal- (bad) + nutrition","meaning":"deficient or unbalanced nutrition","meaningCN":"不足或不均衡的营养","example":"Malnutrition weakens immunity.","exampleCN":"营养不良削弱免疫力。"},{"word":"nourish","structure":"Old French nourrir, from Latin nutrire","meaning":"to feed and sustain","meaningCN":"喂养并维持","example":"The soil nourishes the crop.","exampleCN":"土壤滋养作物。"}],"latinEntries":[{"word":"nutrire","structure":"nutrire (verb, fourth conjugation)","meaning":"to nourish, to suckle","meaningCN":"滋养、哺乳"},{"word":"nutritio","structure":"nutritio, nutritionis (f., third declension)","meaning":"nourishment, feeding","meaningCN":"营养；喂养"},{"word":"nutritius","structure":"nutritius, -a, -um (adjective)","meaning":"nourishing","meaningCN":"有营养的"}]}},{"word":"nutritional","ipa_uk":"/ˌnjuːtrɪˈʃənl/","ipa_us":"/ˌnuːtrɪˈʃənl/","definition_zh":"营养的；营养方面的","definition_en":"relating to nutrition, or to the nutrients contained in a food","core_image":"一个被放大的食品标签，上面的成分表被红笔圈出","scene":"The nutritional value of the flour fell when the bran was removed.","sceneCN":"这里 nutritional 指「营养价值的」（第 2 个义项：食物所含养分的数量与质量）；去掉麸皮后，面粉的营养价值随之下降。图中可辨识物件：面粉袋、放大镜、营养成分表、红笔圈注。","pos":[{"tag":"adj.","zh":"营养的；营养方面的（多作定语，如 nutritional value）"}],"collocations":[{"phrase":"nutritional value","zh":"营养价值"},{"phrase":"nutritional deficiency","zh":"营养缺乏"},{"phrase":"nutritional status","zh":"营养状况"},{"phrase":"nutritional supplement","zh":"营养补充剂"},{"phrase":"nutritional requirements","zh":"营养需求"},{"phrase":"nutritional labeling","zh":"营养标签标注"}],"forms":[{"label":"比较级","form":"more nutritional（营养更丰富的）"},{"label":"最高级","form":"most nutritional"},{"label":"副词形式","form":"nutritionally（在营养上）"},{"label":"名词形式","form":"nutrition（营养）；nutrient（养分）"},{"label":"作定语","form":"nutritional + 名词（如 nutritional value、nutritional status）"}],"derivatives":[{"word":"nutrition","pos":"n.","zh":"营养；营养学"},{"word":"nutritionist","pos":"n.","zh":"营养师"},{"word":"nutritionally","pos":"adv.","zh":"在营养方面"},{"word":"nutritious","pos":"adj.","zh":"有营养的"},{"word":"nutrient","pos":"n.","zh":"养分；营养素"},{"word":"malnutrition","pos":"n.","zh":"营养不良"}],"senses":[{"no":"01","title":"Relating to nutrition","titleCN":"与营养有关：泛指这一领域","definition":"concerning nutrition as a process or a field, without naming a specific value","definitionCN":"涉及营养这一过程或领域，但不指名具体的数值","example":"The clinic offers nutritional advice for young mothers.","exampleCN":"该诊所为准妈妈提供营养建议。","why":"The suffix -al turns the noun into a general adjective of relation, the same pattern as nation to national.","whyCN":"后缀 -al 把名词变成表示关系的泛形容词，nation 变 national 也是同一模式。"},{"no":"02","title":"Nutritional value","titleCN":"营养价值：食物所含养分的数量与质量","definition":"the amount and quality of nutrients a food provides per unit, often per serving or per hundred grams","definitionCN":"食物每单位（常按份或每百克）提供的养分数量与质量","example":"Refining removes much of the grain's nutritional value.","exampleCN":"精加工去掉了谷物的大部分营养价值。","why":"Value language lets nutrition be compared and priced, so the adjective attaches to a measurable quantity.","whyCN":"用「价值」这一说法能让营养被比较与计价，因此这个形容词常附着于可测量的量。"},{"no":"03","title":"Nutritional deficiency","titleCN":"营养缺乏：某种养分长期不足","definition":"a state caused by too little of one or more nutrients over time, producing specific symptoms","definitionCN":"长期缺乏一种或多种养分造成的状态，会产生特定症状","example":"Iron deficiency is the commonest nutritional deficiency worldwide.","exampleCN":"缺铁是全世界最常见的营养缺乏。","why":"Medicine labels the cause rather than the symptom, so a disease such as anaemia is traced back to a nutritional deficiency.","whyCN":"医学命名的是原因而非症状，因此贫血这类疾病会被追溯到营养缺乏。"},{"no":"04","title":"Nutritional status","titleCN":"营养状况：个体整体的营养水平","definition":"the overall condition of a person's body as judged by weight, growth, blood markers and diet","definitionCN":"通过体重、生长、血液指标与膳食判断的个人身体整体状况","example":"The survey mapped the nutritional status of schoolchildren.","exampleCN":"该调查描绘了学龄儿童的营养状况。","why":"Public health needs one phrase for the combined result of many measurements, so 'status' is added to the adjective.","whyCN":"公共卫生需要用一个短语概括多项测量的综合结果，因此在形容词后加上 status。"},{"no":"05","title":"Nutritional supplements and therapy","titleCN":"营养补充与营养治疗","definition":"products or treatments that supply nutrients missing from the diet or unavailable through eating","definitionCN":"补充膳食中缺失、或因无法进食而不能获得的养分的产品或治疗","example":"She took a nutritional supplement during pregnancy.","exampleCN":"她在孕期服用了一种营养补充剂。","why":"The adjective marks the purpose, separating a nutrient product from a drug with a different action.","whyCN":"这个形容词标明用途，把营养产品与作用机制不同的药物区分开。"},{"no":"06","title":"Nutritional labelling","titleCN":"营养标签标注：法规要求的成分披露","definition":"the regulated declaration of nutrient content on food packaging","definitionCN":"法规要求在食品包装上披露养分含量","example":"Nutritional labelling made sugar content impossible to hide.","exampleCN":"营养标签标注让糖含量无处隐藏。","why":"Regulators name the panel after the adjective, so the word appears on every packet as a legal category.","whyCN":"监管者以这个形容词命名标签，因此它作为法律类别出现在每个包装上。"},{"no":"07","title":"Nutritional requirements","titleCN":"营养需求：维持健康所需的量","definition":"the amounts of each nutrient needed daily for health, set by expert committees","definitionCN":"专家委员会设定的、每日维持健康所需的各养分数量","example":"The feed was formulated to meet the birds' nutritional requirements.","exampleCN":"饲料按禽类的营养需求配制。","why":"Once needs are quantified, they become requirements, and the adjective ties them to nutrition rather than to appetite.","whyCN":"一旦需求被量化，它就成了「要求」，而这个形容词把它与营养而非食欲联系起来。"},{"no":"08","title":"Nutritional ecology","titleCN":"营养生态学：食物质量如何影响动物","definition":"the study of how the nutrient content of food shapes the behaviour, health and distribution of animals","definitionCN":"研究食物的养分含量如何塑造动物行为、健康与分布","example":"Nutritional ecology explains why deer choose young shoots.","exampleCN":"营养生态学解释了鹿为何选择嫩枝。","why":"Ecology borrows the adjective to study food quality rather than mere quantity, giving it a research field of its own.","whyCN":"生态学借这个形容词研究食物质量而非仅有数量，从而形成一个独立研究领域。"}],"etymology":{"intro":{"en":"Nutritional is nutrition plus the adjective ending -al, from Latin -alis. The noun itself comes from Latin nutritio.","cn":"nutritional 是 nutrition 加形容词词尾 -al，后者出自拉丁 -alis。名词本身则来自拉丁 nutritio。"},"items":[{"era":"LATIN NUTRIRE","en":"Latin nutrire 'to nourish, to suckle' is the ultimate source, and it also gives nutrient, nourish and nurse.","cn":"拉丁 nutrire「滋养、哺乳」是最终来源，它也给出 nutrient、nourish 与 nurse。"},{"era":"LATIN NUTRITIO","en":"The action noun nutritio 'a feeding, nourishment' supplied the French and English noun nutrition.","cn":"行动名词 nutritio「喂养、营养」提供了法语与英语的 nutrition。"},{"era":"LATIN -ALIS","en":"The adjective ending -alis meant 'relating to' and became English -al, visible in national, natural and nutritional.","cn":"形容词词尾 -alis 意为「与……有关」，变为英语 -al，可见于 national、natural 与 nutritional。"},{"era":"NINETEENTH CENTURY","en":"As nutrition became a science, English formed nutritional to describe values, deficiencies and requirements. The exact first date is uncertain.","cn":"随着营养成为一门科学，英语造出 nutritional 来描述价值、缺乏与需求。最早的确切年代存疑。"},{"era":"TWENTIETH CENTURY","en":"The adjective spread into food law and ecology, producing fixed terms such as nutritional labelling and nutritional ecology.","cn":"这个形容词扩散到食品法规与生态学，产生了营养标签标注、营养生态学等固定术语。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertainty: the first English use of nutritional is not securely dated, and it may have appeared independently in medical and agricultural writing.","cn":"来源不确定：nutritional 的英语首见年代没有可靠定论，它可能在医学与农业文献中各自独立出现。"}]},"similar":{"note":{"en":"The first group holds adjective and noun forms from the same family that are constantly interchanged; the second holds adjectives describing food quality.","cn":"第一组是同族但常被互换的形容词与名词形式；第二组是描述食物质量的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"nutritious","ipa":"/njuˈtrɪʃəs/","tag":"makes a judgement","definition":"Means 'rich in nutrients' and praises the food. Nutritional merely labels the dimension, as in nutritional value.","definitionCN":"意为「富含养分的」，带有对食物的称赞。nutritional 只是标明维度，如营养价值。"},{"word":"nutrition","ipa":"/njuˈtrɪʃn/","tag":"the noun","definition":"The noun for the process or the science. Nutritional is the adjective built from it.","definitionCN":"表示过程或学科的名词。nutritional 是由它构成的形容词。"},{"word":"nutrient","ipa":"/ˈnjuːtriənt/","tag":"one substance","definition":"The countable substance, as in essential nutrients. Nutritional describes a property of a whole food.","definitionCN":"可数的物质，如必需营养素。nutritional 描述整个食物的一种属性。"}]},{"heading":"NEAR MEANING","entries":[{"word":"nutritive","ipa":"/ˈnjuːtrətɪv/","tag":"the older technical adjective","definition":"A near synonym meaning 'serving as nourishment', still used in animal science, as in nutritive value.","definitionCN":"意为「起滋养作用的」近义词，仍用于动物科学，如营养价值。"},{"word":"dietary","ipa":"/ˈdaɪətəri/","tag":"about the diet","definition":"Relating to the diet as a whole, as in dietary fibre. It frames intake, while nutritional frames nutrient content.","definitionCN":"与整体膳食有关，如膳食纤维。它框定摄入，而 nutritional 框定养分含量。"},{"word":"wholesome","ipa":"/ˈhəʊlsəm/","tag":"moral tone","definition":"Describes food or living that is good for health, often with a moral or traditional overtone that nutritional lacks.","definitionCN":"描述有益健康的食物或生活，常带道德或传统色彩，而 nutritional 没有这层意味。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"nutrition + -al: relating to nutrition.","cn":"nutrition + -al：与营养有关的。"},{"en":"The family runs nutrition, nutritionist, nutritionally, nutritious, nutrient and malnutrition.","cn":"同族词包括 nutrition、nutritionist、nutritionally、nutritious、nutrient、malnutrition。"},{"en":"Fixed phrases mark the fields: nutritional value, nutritional status, nutritional supplement, nutritional labelling.","cn":"固定搭配标出领域：营养价值、营养状况、营养补充剂、营养标签标注。"},{"en":"nutritional labels a dimension; nutritious praises the food.","cn":"nutritional 标明维度，nutritious 称赞食物。"},{"en":"Removing bran lowers flour's nutritional value, which is why wholemeal is preferred.","cn":"去掉麸皮会降低面粉的营养价值，这也是全麦更受青睐的原因。"}],"abstract":[{"en":"Picture a magnified label with a table of numbers and one row circled in red.","cn":"想象一个被放大的标签，上面一张数字表格，其中一行被红笔圈出。"},{"en":"Picture two loaves side by side, one dark and dense, one pale and airy.","cn":"想象两条面包并排，一条深色紧实，一条浅色松软。"},{"en":"Picture a child's growth chart where the line flattens for a year and then climbs again.","cn":"想象一张儿童生长图，曲线平了一年，然后又向上走。"}]},"examples":[{"en":"Wholemeal bread has a higher nutritional value than white bread.","cn":"全麦面包的营养价值高于白面包。"},{"en":"The team assessed the children's nutritional status before the programme.","cn":"项目开始前，团队评估了儿童的营养状况。"},{"en":"Nutritional labelling is mandatory on most packaged foods.","cn":"多数包装食品必须标注营养标签。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「nutrition（营养）+ al（的）」——与营养有关的 → nutritional 营养的","word":"nutritional"},"root":"拉丁 nutrire「滋养」→ nutritio → nutrition；加拉丁 -alis（英语 -al）→ nutritional。","sensesIntro":{"en":"Eight senses show one adjective doing different jobs: framing a topic, pricing a food, naming a deficiency, describing a person, a product, a label, a requirement and a research field.","cn":"八个义项展示同一个形容词的不同职务：框定话题、给食物定价、命名缺乏、描述个人、产品、标签、需求与一个研究领域。"},"semanticMap":{"core":{"en":"CORE IMAGE: a magnified food label with one row circled in red.","cn":"核心意象：被放大的食品标签，其中一行被红笔圈出。"},"chain":["ABOUT NUTRITION","MEASURE THE VALUE","NAME THE LACK","ASSESS THE BODY","SUPPLY THE GAP","LABEL AND STUDY"],"branches":[{"senses":"S1","en":"GENERAL FRAME: -al simply says the topic is nutrition.","cn":"泛框定：-al 只是说话题属于营养。"},{"senses":"S2 · S7","en":"MEASUREMENT: value and requirements turn nutrients into numbers to compare and prescribe.","cn":"计量：价值与需求把养分变成可比较、可规定的数字。"},{"senses":"S3 · S4","en":"CLINICAL PICTURE: a deficiency is named, and a person's overall state is assessed.","cn":"临床图景：命名一种缺乏，并评估一个人的整体状态。"},{"senses":"S5","en":"REMEDY: supplements and therapy fill the gap that diet leaves.","cn":"补救：补充剂与治疗填上膳食留下的缺口。"},{"senses":"S6 · S8","en":"LAW AND RESEARCH: labels are regulated, and ecology studies food quality.","cn":"法规与研究：标签受监管，生态学研究食物质量。"}]},"affixes":{"intro":{"en":"Nutritional is a Latin action noun with a Latin relational ending, so the whole word says 'pertaining to nourishment'.","cn":"nutritional 是拉丁行动名词加拉丁关系词尾，整个词的意思就是「与滋养相关的」。"},"latinIntro":{"en":"Latin -alis gives English -al; the stem comes from nutritio, itself from nutrire.","cn":"拉丁 -alis 给出英语 -al；词干来自 nutritio，而 nutritio 又出自 nutrire。"},"items":[{"word":"nutritional","structure":"nutrition + -al (relating to)","meaning":"relating to nutrition","meaningCN":"与营养有关的","example":"The nutritional content varies with soil.","exampleCN":"营养成分随土壤而变化。"},{"word":"nutrition","structure":"nutrire + -tio","meaning":"nourishment; the science of it","meaningCN":"营养；研究它的学科","example":"Nutrition is taught in schools.","exampleCN":"学校教授营养学。"},{"word":"nutrient","structure":"nutrire + -ens","meaning":"a nourishing substance","meaningCN":"滋养性物质","example":"Nutrients are lost in refining.","exampleCN":"精加工会损失养分。"},{"word":"nutritionist","structure":"nutrition + -ist","meaning":"a diet specialist","meaningCN":"膳食专家","example":"The nutritionist reviewed the menu.","exampleCN":"营养师审阅了菜单。"},{"word":"nutritionally","structure":"nutritional + -ly","meaning":"in nutritional terms","meaningCN":"从营养角度看","example":"The snack is nutritionally poor.","exampleCN":"这种零食营养贫乏。"},{"word":"nutritious","structure":"nutritius + -ous","meaning":"nutrient-rich","meaningCN":"富含养分的","example":"The meal was simple but nutritious.","exampleCN":"这餐简单却有营养。"},{"word":"malnutrition","structure":"mal- + nutrition","meaning":"poor nutrition","meaningCN":"营养不佳","example":"Malnutrition impairs healing.","exampleCN":"营养不良妨碍愈合。"},{"word":"nutritive","structure":"nutritius + -ive","meaning":"serving as nourishment","meaningCN":"起滋养作用的","example":"Nutritive value is measured per kilogram.","exampleCN":"营养价值按千克计。"}],"latinEntries":[{"word":"nutritio","structure":"nutritio, nutritionis (f., third declension)","meaning":"nourishment, feeding","meaningCN":"营养；喂养"},{"word":"-alis","structure":"-alis, -ale (adjective suffix)","meaning":"relating to","meaningCN":"与……有关的"},{"word":"nutrire","structure":"nutrire (verb, fourth conjugation)","meaning":"to nourish","meaningCN":"滋养"}]}}]);
